  polAlso_automation_literal_ids: "Feste IDs: {ids}", polAlso_automation_self_trigger: "Ändert den eigenen Auslöser: {ids}", polAlso_exposure_unused: "Freigegeben für: {ids}", polAlso_exposure_sensitive: "Freigegeben für: {ids}",
