// InventoryMixin: methods of the panel element, mixed into the class in 99-register.js.
class InventoryMixin {
  // The state of the inventory list is the shared list state; the old names stay as accessors for the jumps and the tiles.
  invState() { return this.lvState("inventory", "name", "asc"); }
  invSetFilter(name, value) { const f = this.invState().f; if (value) f[name] = value; else delete f[name]; }

  get query() { return this.invState().q; }
  set query(v) { this.invState().q = v; }
  get typeFilter() { return this.invState().f.type || ""; }
  set typeFilter(v) { this.invSetFilter("type", v); if (v !== "config_entry") this.invSetFilter("origin", ""); if (v !== "helper") this.invSetFilter("idle", ""); }
  get statusFilter() { return this.invState().f.status || ""; }
  set statusFilter(v) { this.invSetFilter("status", v); }
  // The origin only means something for integrations: it is dropped with any other type.
  get originFilter() { return this.typeFilter === "config_entry" ? this.invState().f.origin || "" : ""; }
  set originFilter(v) { this.invSetFilter("origin", v); }
  get helperIdle() { return this.typeFilter === "helper" ? this.invState().f.idle || "" : ""; }
  set helperIdle(v) { this.invSetFilter("idle", v); }

  filtered() {
    if (!this.data) return [];
    const st = this.invState(), q = st.q.trim().toLowerCase(), sort = st.sort, desc = st.dir === "desc";
    const type = this.typeFilter, status = this.statusFilter, origin = this.originFilter, idle = this.helperIdle;
    return this.memo("inventory", [q, type, status, origin, idle, sort, st.dir, this.lang], () => {
      const { natural, ids } = this.collators();
      const reason = item => (item.reason ? this.t(item.reason) : item.missing_reference_count ? String(item.missing_reference_count) : "");
      const pick = item => sort === "status" ? item.status : sort === "type" ? item.object_type : sort === "since" ? item.status_since : sort === "version" ? item.integration_version : sort === "reason" ? reason(item) : sort === "entities" ? String(item.entity_count ?? "") : sort === "usedByCol" ? String(this.usedByCount(item) ?? "") : sort === "changedCol" ? (item.last_changed || "") : (item.name || item.object_id);
      const rows = this.data.objects.filter(item => (!q || this.haystack(item).includes(q)) && (!type || (type === "helper" ? this.isHelper(item) : item.object_type === type))
        && (!status || item.status === status)
        && (!(type === "helper" && idle) || this.isIdleHelper(item, Number(idle)))
        && (!origin || (item.object_type === "config_entry" && !!item.custom === (origin === "custom")))).map(item => ({ item, key: pick(item) }));
      rows.sort((a, b) => {
        if (!a.key !== !b.key) return a.key ? -1 : 1; // missing values stay last in both directions
        const order = natural.compare(String(a.key ?? ""), String(b.key ?? ""));
        return (desc ? -order : order) || ids.compare(String(a.item.object_id), String(b.item.object_id));
      });
      return rows.map(row => row.item);
    });
  }

  // A helper is a config entry of a helper domain or an entity of a helper platform.
  isHelper(item) {
    return item.object_type === "config_entry" ? HELPER_DOMAINS.has(item.domain) : item.object_type === "entity" && (HELPER_PLATFORMS.has(item.platform) || HELPER_DOMAINS.has(item.platform));
  }

  // How many objects use this one (incoming edges of the usage kinds); a config entry adds up its entities.
  usedByIndex() {
    return this.memo("usedBy", [], () => {
      const own = new Map(), perEntry = new Map(), newest = new Map();
      for (const o of this.data.objects) {
        if (o.object_type !== "entity") continue;
        const n = this.edgesTo(this.objectKey(o)).filter(e => USAGE_RELATIONS.includes(e.relation)).length;
        own.set(o.object_id, n);
        if (o.config_entry_id) {
          perEntry.set(o.config_entry_id, (perEntry.get(o.config_entry_id) || 0) + n);
          if (o.last_changed && o.last_changed > (newest.get(o.config_entry_id) || "")) newest.set(o.config_entry_id, o.last_changed);
        }
      }
      return { own, perEntry, newest };
    });
  }

  usedByCount(item) {
    const counts = this.usedByIndex();
    if (item.object_type === "config_entry") return counts.perEntry.get(item.object_id) ?? 0;
    return item.object_type === "entity" ? counts.own.get(item.object_id) ?? 0 : null;
  }

  // A hint, not a finding: nobody uses this helper in what the scan reads and it has not changed for `days` days.
  // Dashboards outside the scan, apps and YAML can still use it, so nothing here suggests deleting it.
  isIdleHelper(item, days) {
    if (!this.isHelper(item) || this.usedByCount(item) !== 0) return false;
    const changed = item.object_type === "config_entry" ? this.usedByIndex().newest.get(item.object_id) : item.last_changed;
    const time = changed ? Date.parse(changed) : NaN;
    return Number.isFinite(time) && Date.now() - time >= days * 86400000;
  }

  // The text a search looks in, built once per object.
  haystack(item) {
    const cache = this._haystacks ||= new WeakMap();
    let text = cache.get(item);
    if (text === undefined) { text = [item.name, item.object_id, item.platform, item.domain, item.unique_id].join(" ").toLowerCase(); cache.set(item, text); }
    return text;
  }

  inventory() {
    if (this.xp?.open) return this.xpView();
    const st = this.invState();
    const rows = this.filtered();
    const pg = this.paginate("inventory", rows);
    this._invPage = pg.rows.filter(item => item.object_type === "entity").map(item => item.object_id);
    const { types, statuses } = this.memo("facets", [], () => ({
      types: [...new Set(this.data.objects.map(x => x.object_type))].sort(),
      statuses: [...new Set(this.data.objects.map(x => x.status))].sort(),
    }));
    const all = this.data.objects;
    const tiles = this.invTypesCard(all);
    // Version and entity count only mean something for integrations; the helper columns for helpers.
    const integ = this.typeFilter === "config_entry", helperMode = this.typeFilter === "helper";
    const integCols = [...(integ ? ["version", "entities"] : []), ...(helperMode ? ["usedByCol", "changedCol"] : [])];
    const colValue = (item, k) => k === "version" ? (item.object_type === "config_entry" ? item.integration_version || "" : "") : k === "entities" ? (item.object_type === "config_entry" ? item.entity_count ?? 0 : "") : k === "usedByCol" ? this.usedByCount(item) ?? "" : item.last_changed || "";
    const reasonText = item => (item.reason ? this.t(item.reason) : item.missing_reference_count ? `${item.missing_reference_count} ${this.t("missingReferences")}` : "");
    this.setExporter("inventory", "inventory", [this.t("name"), "ID", this.t("type"), this.t("status"), this.t("reason"), this.t("since"), ...(integ ? [this.t("origin")] : []), ...integCols.map(k => this.t(k))], () => rows.map(i => [i.name, i.object_id, this.t(i.object_type), this.statusLabel(i.status), reasonText(i), i.status_since || "", ...(integ ? [i.object_type === "config_entry" ? this.t(i.custom ? "originKindCustom" : "originKindCore") : ""] : []), ...integCols.map(k => colValue(i, k))]));
    const sorts = [
      { key: "name", label: "sortName", dir: "asc" }, { key: "type", label: "sortType", dir: "asc" }, { key: "status", label: "sortStatus", dir: "asc" },
      { key: "reason", label: "reason", dir: "asc" }, { key: "since", label: "sortSince", dir: "desc" },
      ...integCols.map(k => ({ key: k, label: k, dir: k === "version" ? "asc" : "desc" })),
    ];
    if (!sorts.some(x => x.key === st.sort)) st.sort = "name";
    const filters = [
      { name: "type", all: this.t("allTypes"), options: [["helper", this.t("helperKind")], ...types.map(x => [x, this.t(x)])] },
      { name: "status", all: this.t("allStatus"), options: statuses.map(x => [x, this.statusLabel(x)]) },
      ...(integ ? [{ name: "origin", all: this.t("allOrigins"), options: [["core", this.t("originKindCore")], ["custom", this.t("originKindCustom")]] }] : []),
      ...(helperMode ? [{ name: "idle", all: this.t("helperIdleAny"), options: ["30", "90", "180"].map(d => [d, this.t("helperIdleOpt", { days: d })]) }] : []),
    ];
    const bar = this.listBar("inventory", { table: true, dense: true, sorts, filters, columns: ["type", "status", "reason", "since", ...integCols].map(k => ({ key: k, label: k === "reason" ? "reason" : k })) });
    const idleHint = helperMode && this.helperIdle ? `<div class="hintbox"><ha-icon icon="mdi:lightbulb-on-outline"></ha-icon><div><p>${this.esc(this.t("helperIdleHint"))}</p></div></div>` : "";
    const columns = [
      { key: "sel", label: "selectPage", narrow: true, sortable: false, allBox: () => this.invHeadBox(), cell: item => this.invSelBox(item) },
      { key: "name", label: "name", dir: "asc", cell: item => `<span class="object">${this.tile(item.object_type, this.tone(item.status) === "ok" ? "" : this.tone(item.status))}${this.nameCell(item.name, item.object_id, "span")}</span>` },
      { key: "type", label: "type", dir: "asc", cell: item => this.esc(this.t(item.object_type)) },
      { key: "status", label: "status", dir: "asc", cell: item => this.pill(item.status) },
      { key: "reason", label: "reason", dir: "asc", cell: item => this.esc(reasonText(item) || "—") },
      { key: "since", label: "since", dir: "desc", cell: item => this.formatDate(item.status_since) },
      ...integCols.map(k => ({ key: k, label: k, dir: k === "version" ? "asc" : "desc", cell: item => this.esc(k === "usedByCol" ? (this.usedByCount(item) == null ? "—" : this.formatNumber(this.usedByCount(item))) : k === "changedCol" ? (item.last_changed ? this.formatDate(item.last_changed) : "—") : item.object_type !== "config_entry" ? "—" : k === "version" ? (item.integration_version || "—") : this.formatNumber(item.entity_count ?? 0)) })),
    ];
    const table = rows.length ? this.listTable("inventory", columns, pg.rows, { cls: "inv", rowAttrs: item => `data-object="${this.esc(this.objectKey(item))}" tabindex="0" role="button" aria-label="${this.esc(item.name)}"` }) : `<div class="emptymsg">${this.t("noResults")}</div>`;
    return `<div class="stack">${tiles}<div class="panel">${bar}${idleHint}${this.invSelBar(rows)}${table}${pg.footer || `<div class="tablefoot"><span>${this.formatNumber(rows.length)} ${this.t("of_total")} ${this.formatNumber(this.data.objects.length)} ${this.t("shown")}</span></div>`}</div></div>`;
  }

  // The types as a ring with a table beside it: the largest few, the rest behind a button. A row filters the list below (a
  // second click lifts it); the columns for unavailable and orphaned objects filter by type and state together.
  invTypesCard(all) {
    const SHOWN = 5;
    const by = new Map(), origins = { core: { n: 0, un: 0, or: 0 }, custom: { n: 0, un: 0, or: 0 } };
    for (const x of all) {
      const r = by.get(x.object_type) || { type: x.object_type, n: 0, un: 0, or: 0 };
      r.n += 1; if (x.status === "unavailable") r.un += 1; else if (x.status === "orphaned") r.or += 1;
      by.set(x.object_type, r);
      if (x.object_type === "config_entry") {
        const o = origins[x.custom ? "custom" : "core"];
        o.n += 1; if (x.status === "unavailable") o.un += 1; else if (x.status === "orphaned") o.or += 1;
      }
    }
    const sorted = [...by.values()].sort((a, b) => b.n - a.n || a.type.localeCompare(b.type));
    let rows = this.invAllTypes ? sorted : sorted.slice(0, SHOWN);
    const picked = sorted.find(r => r.type === this.typeFilter);
    if (picked && !rows.includes(picked)) rows = [...rows, picked]; // a chosen type is never hidden
    const rest = sorted.filter(r => !rows.includes(r));
    const total = all.length || 1, sum = key => sorted.reduce((a, r) => a + r[key], 0);
    const colors = ["var(--hk-blue)", "var(--hk-green)", "var(--hk-amber)", "var(--hk-violet)", "color-mix(in srgb,var(--hk-blue) 50%,var(--hk-green))", "color-mix(in srgb,var(--hk-violet) 55%,var(--hk-red))", "color-mix(in srgb,var(--hk-amber) 55%,var(--hk-red))", "color-mix(in srgb,var(--hk-green) 55%,var(--hk-amber))", "color-mix(in srgb,var(--hk-blue) 55%,var(--hk-violet))", "color-mix(in srgb,var(--hk-blue) 40%,var(--hk-gray))", "color-mix(in srgb,var(--hk-green) 40%,var(--hk-gray))"];
    const color = i => colors[i % colors.length];
    const pct = n => `${this.formatNumber(Math.round((n / total) * 1000) / 10)} %`;
    // Ring: one segment per shown type and one grey one for the rest.
    const R = 70, C = 2 * Math.PI * R;
    let acc = 0;
    const seg = (n, stroke, attrs, on) => { const len = Math.max((n / total) * C, 1.5), at = acc; acc += (n / total) * C; return `<circle cx="100" cy="100" r="${R}" fill="none" style="stroke:${stroke}" stroke-width="${on ? 30 : 22}" stroke-dasharray="${len} ${C - len}" stroke-dashoffset="${-at}" transform="rotate(-90 100 100)" ${attrs}/>`; };
    const picks = r => this.typeFilter === r.type && !this.statusFilter && !this.originFilter;
    const ring = rows.map((r, i) => seg(r.n, color(i), `class="invseg${this.typeFilter && !picks(r) ? " dim" : ""}" data-seg="${i}" data-inv-filter="${this.esc(r.type)}|" tabindex="0" role="button" aria-label="${this.esc(this.t(r.type))}: ${this.formatNumber(r.n)}"`, picks(r))).join("")
      + (rest.length ? seg(rest.reduce((a, r) => a + r.n, 0), "var(--hk-gray)", `class="invseg${this.typeFilter ? " dim" : ""}" data-seg="rest"`, false) : "");
    const mid = picked && !this.statusFilter ? [this.formatNumber(picked.n), this.t(picked.type)] : [this.formatNumber(all.length), this.t("objects")];
    const donut = `<svg class="invring" viewBox="0 0 200 200" role="img" aria-label="${this.esc(this.t("byType"))}">${ring}<text x="100" y="100" text-anchor="middle" class="invmid">${this.esc(mid[0])}</text><text x="100" y="120" text-anchor="middle" class="invsub">${this.esc(mid[1])}</text></svg>`;
    const num = (n, attr, label) => n ? `<button class="linkbtn" ${attr} aria-label="${this.esc(label)}">${this.formatNumber(n)}</button>` : `<span class="muted">–</span>`;
    const line = (r, i) => `<tr data-seg="${i}"${picks(r) ? ' class="sel"' : ""}><td><button class="linkbtn invtype" data-inv-filter="${this.esc(r.type)}|" aria-pressed="${picks(r)}"><span class="sw" style="background:${color(i)}"></span>${this.esc(this.t(r.type))}</button></td><td data-label="${this.t("invColCount")}">${this.formatNumber(r.n)}</td><td data-label="${this.t("invColShare")}">${pct(r.n)}</td><td data-label="${this.statusLabel("unavailable")}">${num(r.un, `data-inv-filter="${this.esc(r.type)}|unavailable"`, `${this.t(r.type)}: ${this.statusLabel("unavailable")}`)}</td><td data-label="${this.statusLabel("orphaned")}">${num(r.or, `data-inv-filter="${this.esc(r.type)}|orphaned"`, `${this.t(r.type)}: ${this.statusLabel("orphaned")}`)}</td></tr>`;
    // Under "integration": how many are built in and how many are custom; a click sets the type and the origin together.
    const sub = (kind, o) => { const on = this.typeFilter === "config_entry" && this.originFilter === kind && !this.statusFilter; return `<tr class="invsubrow${on ? " sel" : ""}"><td><button class="linkbtn invtype invsub" data-inv-filter="config_entry||${kind}" aria-pressed="${on}">${this.esc(this.t(kind === "core" ? "invOfCore" : "invOfCustom"))}</button></td><td data-label="${this.t("invColCount")}">${this.formatNumber(o.n)}</td><td data-label="${this.t("invColShare")}">${pct(o.n)}</td><td data-label="${this.statusLabel("unavailable")}">${num(o.un, `data-inv-filter="config_entry|unavailable|${kind}"`, `${this.t(kind === "core" ? "invOfCore" : "invOfCustom")}: ${this.statusLabel("unavailable")}`)}</td><td data-label="${this.statusLabel("orphaned")}">${num(o.or, `data-inv-filter="config_entry|orphaned|${kind}"`, `${this.t(kind === "core" ? "invOfCore" : "invOfCustom")}: ${this.statusLabel("orphaned")}`)}</td></tr>`; };
    const lineWithSub = (r, i) => line(r, i) + (r.type === "config_entry" && origins.custom.n ? sub("core", origins.core) + sub("custom", origins.custom) : "");
    const others = rest.length ? `<tr class="dim" data-seg="rest"><td><span class="sw" style="background:var(--hk-gray)"></span>${this.esc(this.t("invOthers", { n: rest.length }))}</td><td data-label="${this.t("invColCount")}">${this.formatNumber(rest.reduce((a, r) => a + r.n, 0))}</td><td data-label="${this.t("invColShare")}">${pct(rest.reduce((a, r) => a + r.n, 0))}</td><td data-label="${this.statusLabel("unavailable")}">${rest.reduce((a, r) => a + r.un, 0) || "–"}</td><td data-label="${this.statusLabel("orphaned")}">${rest.reduce((a, r) => a + r.or, 0) || "–"}</td></tr>` : "";
    const allRow = `<tr class="invall"><td><button class="linkbtn invtype" data-inv-filter="|" aria-pressed="${!this.typeFilter && !this.statusFilter}">${this.esc(this.t("all"))}</button></td><td data-label="${this.t("invColCount")}">${this.formatNumber(all.length)}</td><td data-label="${this.t("invColShare")}">100 %</td><td data-label="${this.statusLabel("unavailable")}">${num(sum("un"), `data-inv-filter="|unavailable"`, this.statusLabel("unavailable"))}</td><td data-label="${this.statusLabel("orphaned")}">${num(sum("or"), `data-inv-filter="|orphaned"`, this.statusLabel("orphaned"))}</td></tr>`;
    const more = sorted.length > SHOWN ? `<button type="button" class="btn quiet" data-inv-more>${this.esc(this.invAllTypes ? this.t("invFewer", { n: SHOWN }) : this.t("invMore", { n: sorted.length }))}</button>` : "";
    const table = `<table class="invtypes"><thead><tr><th>${this.t("type")}</th><th>${this.t("invColCount")}</th><th>${this.t("invColShare")}</th><th>${this.statusLabel("unavailable")}</th><th>${this.statusLabel("orphaned")}</th></tr></thead><tbody>${rows.map(lineWithSub).join("")}${others}${allRow}</tbody></table>${more}`;
    const filtered = this.typeFilter || this.statusFilter;
    const shown = this.filtered().length;
    return `<div class="panel">${this.fold("inv_types", { title: this.esc(this.t("byType")), pill: filtered ? this.t("invOfAll", { n: this.formatNumber(shown), total: this.formatNumber(all.length) }) : "" }, `<div class="invbody">${donut}<div class="tablewrap">${table}</div></div>`, true)}</div>`;
  }

  nodeButton(key, label, tone = "") {
    const obj = this.findObject(key);
    const [type, ...rest] = key.split(":");
    const id = rest.join(":");
    return `<button class="node" data-graph="${this.esc(key)}">${this.tile(type, tone)}<span><small>${this.t(type)}</small><strong>${this.esc(obj?.name || id)}</strong><span class="meta">${this.esc(label || (obj ? obj.object_id : this.t("missing")))}</span></span>${obj ? this.pill(obj.status) : `<span class="pill red">${this.t("missing")}</span>`}</button>`;
  }

  graph() {
    const search = `<div class="panel searchpanel"><div class="search">${this.pickerBox("graph", this.t("searchObject"), 'id="graphQuery"')}</div></div>`;
    if (!this.graphSelected) {
      return `${search}<div class="panel"><div class="emptymsg"><ha-icon icon="mdi:graph-outline"></ha-icon>${this.t("graphHint")}</div></div>`;
    }
    const item = this.graphSelected, key = this.objectKey(item);
    const head = `<div class="panel pathcard">${this.tile(item.object_type, this.tone(item.status) === "ok" ? "" : this.tone(item.status))}<div><h2>${this.esc(item.name)} ${this.pill(item.status)}</h2><span class="id">${this.esc(item.object_id)}</span></div><button class="btn" data-object="${this.esc(key)}">${this.t("details")}</button></div>`;
    if (this.useGraph()) return `${search}${head}${this.graphBar(item, key)}${this.graphPanel(item, key)}`;
    const USAGE = USAGE_RELATIONS;
    const incoming = this.edgesTo(key), outgoing = this.edgesFrom(key);
    const originEdges = incoming.filter(e => !USAGE.includes(e.relation));
    const usageEntries = [
      ...incoming.filter(e => USAGE.includes(e.relation)).map(e => ({ key: e.source, edge: e, label: `${this.t("usedBy")} · ${this.t(e.relation)}` })),
      ...outgoing.map(e => ({ key: e.target, edge: e, label: this.t(e.relation) })),
    ];
    const edgeNote = edge => `${this.t(edge.confidence)}${edge.location && edge.location !== "runtime_extraction" ? ` · ${edge.location}` : ""}`;
    const origin = originEdges.map(e => `${this.nodeButton(e.source, edgeNote(e))}<div class="link-label"><ha-icon icon="mdi:arrow-down" class="u-ic14"></ha-icon>${this.t(e.relation)}</div>`).join("");
    const usage = usageEntries.length
      ? `<div class="branch">${usageEntries.map(u => `<div><div class="link-label flat">${u.label}</div>${this.nodeButton(u.key, edgeNote(u.edge))}</div>`).join("")}</div>`
      : `<p class="emptyrel sm">${this.t("noRelations")}</p>`;
    return `${search}${head}${this.graphBar(item, key)}
      <div class="panel"><div class="panelhead"><h2>${this.t("origin")} → ${this.t("usage")}</h2><span class="date">${this.t("origin")} ${originEdges.length} · ${this.t("usage")} ${usageEntries.length}</span></div>
      <div class="path">${origin}<div class="node current">${this.tile(item.object_type, this.tone(item.status) === "ok" ? "" : this.tone(item.status))}<span><small>${this.t(item.object_type)}</small><strong>${this.esc(item.name)}</strong><span class="meta">${this.esc(item.object_id)}</span></span>${this.pill(item.status)}</div>${usage}</div></div>`;
  }
}

// GraphMixin: methods of the panel element, mixed into the class in 99-register.js.
// The graph is a second view of the dependency list: origin on the left, the object in the middle,
// what uses it on the right, up to three levels deep. The list stays the default and the fallback.
class GraphMixin {
  // The graph needs room; on a narrow screen only the list is offered.
  canGraph() {
    try { return globalThis.matchMedia ? globalThis.matchMedia("(min-width:600px)").matches : true; } catch (_) { return true; }
  }

  useGraph() { return this.prefs.graphMode === "graph" && this.canGraph(); }

  // Walks the edges level by level from the object. Left: what the object comes from (non-usage
  // edges pointing at it). Right: what uses it (usage edges pointing at it) and what it uses
  // (edges leaving it). Returns nodes per level, the edges between included nodes and the notes.
  graphModel(item, key, { depth = 1, relation = "", certainOnly = false, limit = GRAPH_NODE_STEP, group = true, open = new Set() } = {}) {
    const keep = e => (!relation || e.relation === relation) && (!certainOnly || e.confidence === "certain");
    const sides = {
      left: { levels: [], seen: new Map(), next: node => this.edgesTo(node).filter(e => !USAGE_RELATIONS.includes(e.relation) && keep(e)).map(e => [e.source, e]) },
      right: { levels: [], seen: new Map(), next: (node, via) => (via === "out"
        ? this.edgesFrom(node).filter(keep).map(e => [e.target, e])
        : this.edgesTo(node).filter(e => USAGE_RELATIONS.includes(e.relation) && keep(e)).map(e => [e.source, e])) },
    };
    const edges = [], cycles = new Set();
    let hidden = 0;
    const record = (from, to, edge, cycle) => {
      edges.push({ from, to, edge, cycle });
      if (cycle) cycles.add(edge);
    };
    for (const [name, side] of Object.entries(sides)) {
      let frontier = [{ key, via: null }];
      for (let level = 1; level <= depth && frontier.length; level++) {
        const found = [];
        for (const parent of frontier) {
          const candidates = name === "right" && parent.key === key
            ? [...sides.right.next(key, "in").map(([k, e]) => [k, e, "in"]), ...sides.right.next(key, "out").map(([k, e]) => [k, e, "out"])]
            : side.next(parent.key, parent.via).map(([k, e]) => [k, e, parent.via]);
          for (const [other, edge, via] of candidates) {
            const known = side.seen.get(other);
            const opposite = (name === "left" ? sides.right : sides.left).seen.has(other);
            // Back to the object, to an earlier level or to the other side closes a loop.
            if (other === key || opposite || (known && known.level <= level - 1)) { record(other, parent.key, edge, true); continue; }
            if (known) { record(other, parent.key, edge, false); continue; } // a second way to a node of this level
            if (side.seen.size >= limit) { hidden++; continue; }
            const node = { key: other, level, via, parent: parent.key };
            side.seen.set(other, node);
            found.push(node);
            record(other, parent.key, edge, false);
          }
        }
        if (found.length) side.levels.push(found);
        frontier = found;
      }
    }
    // Leaf nodes of one type that hang on the same node, five or more of them, become one node ("12 × Sensor") until it is opened.
    const repl = new Map();
    if (group) {
      for (const [name, side] of Object.entries(sides)) {
        side.levels = side.levels.map((level, i) => {
          const parents = new Set((side.levels[i + 1] || []).map(n => n.parent));
          const buckets = new Map();
          for (const n of level) {
            if (parents.has(n.key)) continue;
            const id = `${name}|${n.parent}|${n.key.split(":")[0]}|${n.via}`;
            if (!buckets.has(id)) buckets.set(id, []);
            buckets.get(id).push(n);
          }
          const grouped = new Set(), made = [];
          for (const [id, members] of buckets) {
            if (members.length < GRAPH_GROUP_MIN || open.has(id)) continue;
            const g = { key: `group:${id}`, level: members[0].level, via: members[0].via, parent: members[0].parent, group: members.map(m => m.key) };
            members.forEach(m => { repl.set(m.key, g.key); grouped.add(m.key); });
            made.push(g);
          }
          return [...level.filter(n => !grouped.has(n.key)), ...made];
        });
      }
    }
    const seenEdge = new Set(), mapped = [];
    for (const e of edges) {
      const from = repl.get(e.from) ?? e.from, to = repl.get(e.to) ?? e.to;
      const id = `${from}>${to}>${e.edge.relation}`;
      if (from === to || seenEdge.has(id)) continue;
      seenEdge.add(id);
      mapped.push({ ...e, from, to });
    }
    const nodes = new Set([key, ...sides.left.levels.flat().map(n => n.key), ...sides.right.levels.flat().map(n => n.key)]);
    const shown = mapped.filter(e => nodes.has(e.from) && nodes.has(e.to));
    const all = [...sides.left.seen.values(), ...sides.right.seen.values()];
    return {
      key, left: sides.left.levels, right: sides.right.levels, edges: shown,
      hidden, cycles: [...cycles].filter(e => shown.some(s => s.edge === e)).length,
      missing: all.filter(n => !this.findObject(n.key)).length,
      probable: shown.filter(e => e.edge.confidence !== "certain").length,
      count: all.length,
    };
  }

  // Columns from the outermost left level to the outermost right level, the object in the middle.
  graphLayout(model) {
    const W = 232, H = 48, GAPX = 72, GAPY = 14;
    // Children stand in the order of their parents (and then by type and name), so edges run side by side instead of crossing.
    const sortKey = n => { const obj = this.findObject(n.key), [type, ...rest] = n.key.split(":"); return `${type}\u0000${obj?.name || rest.join(":")}`.toLowerCase(); };
    const order = levels => {
      let before = new Map([[model.key, 0]]);
      return levels.map(level => {
        const sorted = [...level].sort((a, b) => (before.get(a.parent) ?? 0) - (before.get(b.parent) ?? 0) || sortKey(a).localeCompare(sortKey(b)));
        before = new Map(sorted.map((n, i) => [n.key, i]));
        return sorted;
      });
    };
    const columns = [...order(model.left).reverse(), [{ key: model.key, center: true }], ...order(model.right)];
    const tallest = Math.max(...columns.map(c => c.length));
    const height = tallest * H + (tallest - 1) * GAPY;
    const at = new Map();
    columns.forEach((column, i) => {
      const top = (height - (column.length * H + (column.length - 1) * GAPY)) / 2;
      column.forEach((node, j) => at.set(node.key, { x: i * (W + GAPX), y: top + j * (H + GAPY), node }));
    });
    // Room on the right for the arcs between nodes of one column.
    return { W, H, width: columns.length * W + (columns.length - 1) * GAPX + 48, height, at };
  }

  graphClip(text, max) { const s = String(text ?? ""); return s.length > max ? `${s.slice(0, max - 1)}…` : s; }

  graphSvg(model, item, hitKeys) {
    const layout = this.graphLayout(model), { W, H, at } = layout;
    // Every edge ends at a port on a node's right or left side. Several edges on one side get their own height
    // (ordered by where the other end stands), so they leave the node side by side instead of on top of each other.
    const geo = model.edges.map(({ from, to, edge, cycle }) => {
      const a = at.get(from), b = at.get(to);
      if (!a || !b) return null;
      const sameColumn = a.x === b.x;
      const [l, r] = sameColumn ? (a.y < b.y ? [a, b] : [b, a]) : a.x < b.x ? [a, b] : [b, a];
      return { from, to, edge, cycle, a, l, r, sameColumn, lp: `${l === a ? from : to}|R`, rp: `${r === a ? from : to}|${sameColumn ? "R" : "L"}` };
    }).filter(Boolean);
    const ports = new Map();
    for (const g of geo) {
      ports.set(g.lp, [...(ports.get(g.lp) || []), { g, end: "l", other: g.r.y }]);
      ports.set(g.rp, [...(ports.get(g.rp) || []), { g, end: "r", other: g.l.y }]);
    }
    for (const list of ports.values()) {
      list.sort((p, q) => p.other - q.other);
      list.forEach((entry, i) => { entry.g[`${entry.end}y`] = (list.length === 1 ? 0.5 : i / (list.length - 1)) * (H - 16) + 8; });
    }
    const edgeSvg = geo.map(({ edge, cycle, a, from, to, l, r, sameColumn, ly, ry }) => {
      const x1 = l.x + W, y1 = l.y + ly, x2 = sameColumn ? r.x + W : r.x, y2 = r.y + ry;
      // Arcs between nodes of one column bulge out further the more rows they span, so nested arcs do not coincide.
      const rows = Math.round(Math.abs(y2 - y1) / (H + 14));
      const dx = sameColumn ? Math.min(14 + 10 * rows, 44) : (x2 - x1) / 2;
      const forward = edge.source === (l === a ? from : to); // the data direction runs from the first to the second end
      const hit = hitKeys && (hitKeys.has(edge.source) && (hitKeys.has(edge.target) || edge.target === model.key));
      const cls = ["gedge", edge.confidence === "certain" ? "" : "prob", cycle ? "cycle" : "", hit ? "hit" : "", hitKeys && !hit ? "gdim" : ""].filter(Boolean).join(" ");
      const mark = forward ? 'marker-end="url(#hk-arrow)"' : 'marker-start="url(#hk-arrow)"';
      return `<path class="${cls}" d="M${x1},${y1} C${x1 + dx},${y1} ${sameColumn ? x2 + dx : x2 - dx},${y2} ${x2},${y2}" ${mark}><title>${this.esc(`${edge.source} → ${edge.target}: ${this.t(edge.relation)} (${this.t(edge.confidence)})`)}</title></path>`;
    }).join("");
    const nodeSvg = [...at.entries()].map(([key, { x, y, node }]) => {
      if (node.group) {
        const type = node.group[0].split(":")[0], hit = hitKeys && node.group.some(k => hitKeys.has(k));
        const names = node.group.slice(0, 8).map(k => this.findObject(k)?.name || k.split(":").slice(1).join(":")).join(", ") + (node.group.length > 8 ? ", …" : "");
        const label = this.t("graphGroup", { n: node.group.length, type: this.t(type) });
        return `<g class="gnode ggroup ${hit ? "hit" : ""}" data-graph-group="${this.esc(key.slice(6))}" tabindex="0" role="button" aria-label="${this.esc(`${label}. ${this.t("graphGroupOpen")}`)}" data-tip="${this.esc(label)}" data-tip-sub="${this.esc(names)}" transform="translate(${x},${y})">
          <rect width="${W}" height="${H}" rx="8"></rect><text class="t1" x="14" y="18">${this.esc(this.graphClip(label, 30))}</text><text x="14" y="36">${this.esc(this.graphClip(this.t("graphGroupOpen"), 30))}</text></g>`;
      }
      const obj = this.findObject(key), [type, ...rest] = key.split(":"), id = rest.join(":");
      const name = obj?.name || id, status = obj ? this.statusLabel(obj.status) : this.t("missing");
      const hit = hitKeys?.has(key), tone = obj ? this.tone(obj.status) : "red";
      const cls = ["gnode", node.center ? "center" : "", obj ? "" : "missing", hit ? "hit" : "", hitKeys && !hit && !node.center ? "gdim" : ""].filter(Boolean).join(" ");
      const label = `${this.t(type)}: ${name}, ${status}${hit ? `, ${this.t("graphBreaks")}` : ""}`;
      return `<g class="${cls}" ${node.center ? "" : `data-graph="${this.esc(key)}" tabindex="0" role="button"`} aria-label="${this.esc(label)}" data-tip="${this.esc(name)}" data-tip-sub="${this.esc(`${this.t(type)} · ${status}${hit ? ` · ${this.t("graphBreaks")}` : ""} · ${id}`)}" transform="translate(${x},${y})">
        <rect width="${W}" height="${H}" rx="8"></rect><rect class="bar ${tone}" width="5" height="${H}" rx="2"></rect>
        <text class="t1" x="14" y="18">${this.esc(this.graphClip(`${this.t(type)} · ${status}${hit ? ` · ${this.t("graphBreaks")}` : ""}`, 38))}</text>
        <text x="14" y="36">${this.esc(this.graphClip(name, 27))}</text></g>`;
    }).join("");
    return `<div class="graphwrap"><svg class="graphsvg" role="group" aria-label="${this.esc(this.t("graphLabel", { name: item.name }))}" width="${layout.width}" height="${layout.height}" viewBox="0 0 ${layout.width} ${layout.height}">
      <defs><marker id="hk-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path class="garrow" d="M0,0 L8,4 L0,8z"></path></marker></defs>${edgeSvg}${nodeSvg}</svg></div>`;
  }

  // The switch between list and graph, and for the graph the depth, filters and the removal highlight.
  graphBar(item, key) {
    const canGraph = this.canGraph(), graph = this.useGraph();
    const toggle = canGraph ? `<div class="seg" role="group" aria-label="${this.esc(this.t("graphMode"))}">${[["list", "graphList"], ["graph", "graphGraph"]].map(([mode, label]) => `<button class="btn ${(graph ? "graph" : "list") === mode ? "primary" : ""}" data-pref="graphMode|${mode}" aria-pressed="${(graph ? "graph" : "list") === mode}">${this.t(label)}</button>`).join("")}</div>` : "";
    if (!graph) return toggle ? `<div class="panel graphbar">${toggle}</div>` : `<p class="factnote graphphone">${this.t("graphPhone")}</p>`;
    const depth = [1, 2, 3].map(n => `<button class="btn ${this.graphDepth === n ? "primary" : ""}" data-graph-depth="${n}" aria-pressed="${this.graphDepth === n}">${n}</button>`).join("");
    const relations = [...new Set(this.graphModel(item, key, { depth: this.graphDepth, limit: 400 }).edges.map(e => e.edge.relation))].sort();
    const relSelect = `<select id="graphRel" aria-label="${this.esc(this.t("graphRelation"))}"><option value="">${this.t("graphAllRelations")}</option>${relations.map(r => `<option value="${r}" ${this.graphRel === r ? "selected" : ""}>${this.t(r)}</option>`).join("")}</select>`;
    const confSelect = `<select id="graphConf" aria-label="${this.esc(this.t("graphConfidence"))}"><option value="all" ${this.graphConf === "all" ? "selected" : ""}>${this.t("graphAllConf")}</option><option value="certain" ${this.graphConf === "certain" ? "selected" : ""}>${this.t("graphCertainOnly")}</option></select>`;
    const impact = this.impact(item, key);
    const impactBtn = impact ? `<button class="btn ${this.graphImpact ? "primary" : ""}" data-graph-impact aria-pressed="${this.graphImpact}">${this.t("graphImpact")}</button>` : "";
    return `<div class="panel graphbar">${toggle}<span class="graphctl"><small>${this.t("graphDepth")}</small><span class="seg" role="group" aria-label="${this.esc(this.t("graphDepth"))}">${depth}</span></span>${relSelect}${confSelect}${impactBtn}</div>`;
  }

  graphPanel(item, key) {
    const model = this.graphModel(item, key, { depth: this.graphDepth, relation: this.graphRel, certainOnly: this.graphConf === "certain", limit: this.graphLimit, open: this.graphOpen });
    const impact = this.graphImpact ? this.impact(item, key) : null;
    const hitKeys = impact ? new Set([...impact.hits.map(h => h.key)]) : null;
    const nothing = !model.count;
    const shownHits = hitKeys ? [...hitKeys].filter(k => model.left.concat(model.right).some(level => level.some(n => n.key === k || n.group?.includes(k)))).length : 0;
    const notes = [
      hitKeys && hitKeys.size > shownHits ? this.t("graphHitsOutside", { n: hitKeys.size - shownHits }) : "",
      model.missing ? this.t("graphMissing", { n: model.missing }) : "", model.probable ? this.t("graphProbable", { n: model.probable }) : "",
      model.cycles ? this.t("graphCycles", { n: model.cycles }) : "", model.hidden ? this.t("graphHidden", { n: model.hidden }) : "",
    ].filter(Boolean).join(" · ");
    const more = (model.hidden ? `<button class="btn" data-graph-more>${this.t("graphMore")}</button>` : "") + (this.graphOpen.size ? ` <button class="btn" data-graph-regroup>${this.t("graphRegroup")}</button>` : "");
    return `<div class="panel"><div class="panelhead"><h2>${this.t("origin")} → ${this.t("usage")}</h2><span class="date">${this.t("graphNodes", { n: model.count })}</span></div>
      ${nothing ? `<p class="emptyrel">${this.t("noRelations")}</p>` : this.graphSvg(model, item, hitKeys)}
      ${notes || more.trim() ? `<p class="factnote">${this.esc(notes)} ${more}</p>` : ""}${this.fold("graph_legend", { title: this.t("graphLegendTitle") }, `<p class="factnote">${this.t("graphLegend")}</p>`, false)}</div>`;
  }
}

// UnusedMixin: methods of the panel element, mixed into the class in 99-register.js.
class UnusedMixin {
  batteryRows() {
    const rows = [];
    for (const o of this.data.objects) {
      if (o.object_type !== "entity" || o.device_class !== "battery" || o.status !== "active" || this.batteryExcluded(o)) continue;
      const domain = o.object_id.split(".")[0];
      if (domain === "binary_sensor") rows.push({ item: o, level: null, low: o.state === "on" });
      else if (domain === "sensor" && (!o.unit || o.unit === "%") && o.state !== null && o.state !== "" && !Number.isNaN(Number(o.state))) rows.push({ item: o, level: Number(o.state), low: false });
    }
    const limit = this.data.meta.low_battery_percent ?? 20;
    rows.forEach(r => { r.low = r.low || (r.level !== null && r.level <= limit); });
    return rows.sort((a, b) => (Number(b.low) - Number(a.low)) || ((a.level ?? -1) - (b.level ?? -1)) || a.item.name.localeCompare(b.item.name));
  }

  // Active entities no source refers to. A hint only; see unreferencedHint for the blind spots.
  unreferencedRows() {
    const { used } = this.edgeIndex();
    const SELF = ["automation", "script", "scene"];
    return this.data.objects.filter(o => o.object_type === "entity" && o.status === "active" && !o.entity_category
      && !SELF.includes(o.object_id.split(".")[0]) && !used.has(this.objectKey(o)))
      .sort((a, b) => a.object_id.localeCompare(b.object_id));
  }

  unrefTabs() {
    if (this._embedUnref) return "";
    const stats = this.data.orphaned_statistics || [];
    const tabs = [{ id: "entities", label: this.t("unreferencedEntities"), count: this.unreferencedRows().length }, { id: "statistics", label: this.t("orphanStats"), count: stats.length }];
    return this.viewTabBar("unreferenced", tabs, this.unrefTab === "statistics" ? "statistics" : "entities");
  }

  // Key figures of the unused entities (the counts themselves are in the cleanup tiles above).
  unrefTiles() {
    const rows = this.unreferencedRows();
    const top = list => { const counts = new Map(); list.forEach(x => x && counts.set(x, (counts.get(x) || 0) + 1)); return [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]; };
    const domain = top(rows.map(o => o.object_id.split(".")[0])), platform = top(rows.map(o => o.platform));
    const withStats = rows.filter(o => o.has_statistics).length;
    return this.sumTiles([
      this.data.meta.recorder_available && rows.length ? { label: this.t("unrefSumStats"), value: this.formatNumber(withStats), sub: this.t("unrefSumStatsHint"), tone: "mute" } : null,
      domain ? { label: this.t("unrefSumDomain"), value: this.esc(domain[0]), sub: this.formatNumber(domain[1]), tone: "mute" } : null,
      platform ? { label: this.t("unrefSumPlatform"), value: this.esc(platform[0]), sub: this.formatNumber(platform[1]), tone: "mute" } : null,
    ]);
  }

  // Active entities that look like what an orphaned statistic became after a rename: same domain, same unit, similar name.
  statSuccessors(orphan) { return this.successorsOf(orphan.statistic_id, orphan.unit, 2); }

  // The same idea for any entity id; `unit` is optional. Hints only, never chosen for the person.
  successorsOf(id, unit, limit = 5) {
    const [domain, name = ""] = String(id || "").split(".");
    if (!domain) return [];
    const words = new Set(name.split("_").filter(Boolean));
    const found = [];
    for (const o of this.data.objects) {
      if (o.object_type !== "entity" || o.status !== "active" || o.object_id === id || !o.object_id.startsWith(`${domain}.`)) continue;
      if (unit && o.unit !== unit) continue;
      const other = new Set(o.object_id.split(".")[1].split("_").filter(Boolean));
      const shared = [...words].filter(w => other.has(w)).length;
      const score = shared / (words.size + other.size - shared || 1);
      if (score >= 0.5) found.push({ item: o, score });
    }
    return found.sort((a, b) => b.score - a.score || a.item.object_id.localeCompare(b.item.object_id)).slice(0, limit).map(f => f.item);
  }

  statSuccessorLine(orphan) {
    const successors = this.statSuccessors(orphan);
    if (!successors.length) return "";
    const links = successors.map(s => `<button class="linklike" data-object="entity:${this.esc(s.object_id)}">${this.esc(s.object_id)}</button>`).join(", ");
    return `<small class="statsucc">${this.t("statSuccessors")} ${links}</small>`;
  }

  // The same as plain text, for the tooltip of the name while the rows are compact.
  statSuccessorText(orphan) {
    const successors = this.statSuccessors(orphan);
    return successors.length ? `${this.t("statSuccessors")} ${successors.map(s => s.object_id).join(", ")}` : null;
  }

  // When the statistic last received a value: read on the first visit of the list, never during a scan.
  async loadOrphanLast(refresh = false) {
    this.orphanLastLoading = true; this.render();
    try { this.orphanLast = await this._hass.callWS({ type: "ha_housekeeper/statistics_last", refresh }); }
    catch (_) { this.orphanLast = null; }
    this.orphanLastLoading = false; this.render();
  }

  // Switching to the tab asks again after a failure or a busy recorder; rendering alone never loops.
  retryOrphanLast() {
    if (!this.orphanLast || this.orphanLast.busy) this._orphanLastRequested = false;
  }

  ensureOrphanLast() {
    if (this.orphanLastLoading || this._orphanLastRequested || !this.data?.meta?.recorder_available) return;
    this._orphanLastRequested = true;
    setTimeout(() => this.loadOrphanLast(), 0);
  }

  orphanStatsView() {
    const all = this.data.orphaned_statistics || [];
    this.lvState("orphanstats", "id", "asc");
    const kind = o => (o.has_sum && o.has_mean ? "kindBoth" : o.has_sum ? "kindSum" : "kindMean");
    const lastOf = o => this.orphanLast?.last?.[o.statistic_id];
    const firstOf = o => this.orphanLast?.first?.[o.statistic_id];
    const rowsOf = o => this.orphanLast?.rows?.[o.statistic_id];
    const sorts = [
      { key: "id", label: "sortId", dir: "asc", get: o => o.statistic_id },
      { key: "kind", label: "sortKind", dir: "asc", get: o => this.t(kind(o)) },
      { key: "unit", label: "sortUnit", dir: "asc", get: o => o.unit },
      { key: "last", label: "sortLastEntry", dir: "desc", get: lastOf },
      { key: "first", label: "sortFirstEntry", dir: "asc", get: firstOf },
      { key: "rows", label: "sortRows", dir: "desc", get: rowsOf },
    ];
    this.ensureOrphanLast();
    const kinds = [...new Set(all.map(kind))];
    const units = [...new Set(all.map(o => o.unit).filter(Boolean))].sort();
    const AGES = [30, 365, 730];
    this.setExporter("orphanstats", "orphaned-statistics", ["ID", this.t("utKind"), this.t("utUnit"), this.t("utFirst"), this.t("utLast"), this.t("utRows"), this.t("inEnergy")], () => rows.map(o => [o.statistic_id, this.t(kind(o)), o.unit || "", firstOf(o) ? new Date(firstOf(o) * 1000).toISOString() : "", lastOf(o) ? new Date(lastOf(o) * 1000).toISOString() : "", rowsOf(o) ?? "", o.in_energy ? "yes" : "no"]));
    const bar = this.listBar("orphanstats", { table: true, dense: true, columns: [{ key: "kind", label: "utKind" }, { key: "unit", label: "utUnit" }, { key: "first", label: "utFirst" }, { key: "last", label: "utLast" }, { key: "rows", label: "utRows" }, { key: "energy", label: "utEnergy" }], sorts, filters: [
      { name: "kind", all: this.t("allKinds"), options: kinds.map(k => [k, this.t(k)]) },
      { name: "unit", all: this.t("allUnits"), options: units.map(u => [u, u]) },
      { name: "age", all: this.t("allAges"), options: AGES.map(d => [String(d), this.t(`statAge${d}`)]) },
    ] });
    const refined = this.refine("orphanstats", all, { text: o => [o.statistic_id, o.unit].join(" "), filters: {
      kind: (o, v) => kind(o) === v, unit: (o, v) => o.unit === v,
      age: (o, v) => { const ts = lastOf(o); return typeof ts === "number" && Date.now() - ts * 1000 > Number(v) * 864e5; },
    }, sorts, tie: o => o.statistic_id });
    const rows = this.selOnly?.orphanstats ? refined.filter(o => this.purgeSel.has(o.statistic_id)) : refined;
    const pg = this.paginate("orphanstats", rows);
    this._purgeTotal = rows.length;
    this._purgePage = pg.rows.filter(o => !o.in_energy).map(o => o.statistic_id);
    const lastCell = o => {
      if (this.orphanLastLoading && !this.orphanLast) return `<span class="muted">${this.t("loadingShort")}</span>`;
      if (this.orphanLast?.busy) return `<span class="muted">${this.t("lastEntryBusyShort")}</span>`;
      const ts = lastOf(o);
      if (ts === null || ts === undefined) return `<span class="muted">${this.orphanLast?.available ? this.t("lastEntryNone") : "–"}</span>`;
      return this.ageCell(new Date(ts * 1000).toISOString());
    };
    const firstCell = o => {
      const ts = firstOf(o);
      return ts ? this.ageCell(new Date(ts * 1000).toISOString()) : `<span class="muted">${this.orphanLast?.busy || (this.orphanLastLoading && !this.orphanLast) ? this.t("loadingShort") : "–"}</span>`;
    };
    const rowsCell = o => { const n = rowsOf(o); return typeof n === "number" ? this.formatNumber(n) : `<span class="muted">${this.t("loadingShort")}</span>`; };
    const columns = [
      { key: "id", label: "utStatId", dir: "asc", headPrefix: () => this.purgeHeadBox(), cell: o => `<div class="statcell">${this.purgeBox(o)}<div>${this.nameCell(o.statistic_id, "", "div", this.statSuccessorText(o))}${this.statSuccessorLine(o)}</div></div>` },
      { key: "kind", label: "utKind", cell: o => this.esc(this.t(kind(o))) },
      { key: "unit", label: "utUnit", cell: o => this.esc(o.unit || "–") },
      { key: "first", label: "utFirst", dir: "asc", cell: firstCell },
      { key: "last", label: "utLast", dir: "desc", cell: lastCell },
      { key: "rows", label: "utRows", dir: "desc", cell: rowsCell },
      { key: "energy", label: "utEnergy", sortable: false, cell: o => (o.in_energy ? `<span class="pill warn">${this.t("inEnergy")}</span>` : "") },
    ];
    const empty = this.data.meta.recorder_available ? (all.length ? this.noMatches("orphanstats") : this.t("noOrphanStats")) : this.t("noRecorder");
    const table = rows.length ? this.listTable("orphanstats", columns, pg.rows, { cls: "stat", rowAttrs: () => 'class="static"' }) : `<div class="emptymsg"><ha-icon icon="mdi:chart-line-variant"></ha-icon>${empty}</div>`;
    return `<div class="stack">${this.unrefTabs()}<div class="panel"><p class="factnote">${this.t("orphanStatsHint")}</p>${this.purgeBar()}${bar}${table}${pg.footer}</div></div>`;
  }

  // Deleting the recorder data of entities that are gone: pick rows, confirm with a word; a backup comes first.
  purgeBox(o) {
    if (!this.data.meta.recorder_available || o.in_energy) return "";
    return `<input type="checkbox" class="selbox" data-psel="${this.esc(o.statistic_id)}" ${this.purgeSel.has(o.statistic_id) ? "checked" : ""} aria-label="${this.esc(o.statistic_id)}">`;
  }

  // Header box: ticks every selectable row of the shown page; half-ticked when only some are.
  purgeHeadBox() {
    if (!this.data.meta.recorder_available || !this._purgePage?.length) return "";
    const n = this._purgePage.filter(id => this.purgeSel.has(id)).length;
    return `<input type="checkbox" class="selbox" data-psel-all ${n === this._purgePage.length ? "checked" : ""} ${n && n < this._purgePage.length ? "data-partial" : ""} aria-label="${this.esc(this.t("selectPage"))}">`;
  }

  purgeBar() {
    if (!this.data.meta.recorder_available) return "";
    const n = this.purgeSel.size, r = this.purgeResult;
    const result = r ? `<p class="${r.error ? "error" : "factnote"}">${this.esc(r.error ? this.t("purgeNotDeleted", { reason: `${this.t(`purgeReason_${r.error}`)}${r.detail ? ` (${r.detail})` : ""}` }) : this.t("purgeDone", { n: r.removed.length, skipped: r.skipped.length }))}</p>` : "";
    const over = n > MAX_PLAN_ACTIONS;
    const open = this.purgeOpen && n ? `<div class="panel" role="group" aria-label="${this.esc(this.t("purgeTitle"))}"><div class="pad">
      <p><strong>${this.t("purgeTitle")}</strong></p><p class="factnote">${this.t("purgeWarn", { n })}</p>
      ${over ? `<p class="factnote">${this.t("purgeChunk", { max: MAX_PLAN_ACTIONS, n, rest: n - MAX_PLAN_ACTIONS })}</p>` : ""}
      <label><input type="checkbox" data-purge-states ${this.purgeStates ? "checked" : ""}> ${this.t("purgeStates")}</label>
      <div class="setrow planfoot"><small class="u-m0">${this.t("purgePlanHint")}</small>
      <button class="btn accent" data-purge-run ${!this.purgeBusy ? "" : "disabled"}>${this.purgeBusy ? this.t("purgeRunning") : this.t("purgePreview")} (${Math.min(n, MAX_PLAN_ACTIONS)})</button><button class="btn" data-purge-close>${this.t("cancelRun")}</button></div></div></div>` : "";
    return `${result}<div class="toolbar"><button class="btn quiet" data-purge-page>${this.t("selectPage")}</button><button class="btn quiet" data-purge-clear ${n ? "" : "disabled"}>${this.t("clearSelection")}</button>${this.selOnlyButton("orphanstats", n)}<span class="selcount" role="status">${this.t("selectedCount", { count: n })}</span><span class="toolgap"></span><button class="btn dangersoft" data-purge-open ${n ? "" : "disabled"}><ha-icon icon="mdi:delete-outline"></ha-icon>${n ? this.t("purgeOpenCount", { n: this.formatNumber(n) }) : this.t("purgeOpen")}</button>${this.viewCount(this._purgeTotal || 0)}</div>${open}`;
  }

  async purgeRun() {
    // The deletion is an ordinary plan: preview, confirmation of each ID, backup, verification. It is made here and run under Cleanup.
    this.purgeBusy = true; this.purgeResult = null; this.render();
    try {
      const chosen = [...this.purgeSel], now = chosen.slice(0, MAX_PLAN_ACTIONS);
      const actions = now.map(object_id => ({ kind: "purge_statistics", object_id, states: this.purgeStates }));
      const plan = await this._hass.callWS({ type: "ha_housekeeper/plan_create", actions });
      this.purgeSel = new Set(chosen.slice(MAX_PLAN_ACTIONS)); this.purgeOpen = false; this.purgeWord = "";
      this.openNewPlan(plan);
    } catch (err) { this.purgeResult = { removed: [], skipped: [], error: "failed", detail: this.errText(err) }; }
    this.purgeBusy = false;
    this.render();
  }

  unreferencedView() {
    if (this.unrefTab === "statistics") return this.orphanStatsView();
    const all = this.unreferencedRows();
    this.lvState("unreferenced", "name", "asc");
    const domainOf = o => o.object_id.split(".")[0];
    const deviceName = o => (o.device_id ? this.findObject(`device:${o.device_id}`)?.name : "") || "";
    const ts = v => (v ? Date.parse(v) || null : null);
    const sorts = [
      { key: "id", label: "sortId", dir: "asc", get: o => o.object_id },
      { key: "name", label: "sortName", dir: "asc", get: o => o.name },
      { key: "domain", label: "sortDomain", dir: "asc", get: domainOf },
      { key: "device", label: "sortDevice", dir: "asc", get: deviceName },
      { key: "area", label: "sortArea", dir: "asc", get: o => this.areaName(o) },
      { key: "platform", label: "sortIntegration", dir: "asc", get: o => o.platform },
      { key: "changed", label: "sortChanged", dir: "desc", get: o => ts(o.last_changed) },
      { key: "reported", label: "sortReported", dir: "desc", get: o => ts(o.last_reported || o.last_updated) },
      { key: "since", label: "sortSince", dir: "asc", get: o => ts(o.status_since) },
      { key: "stats", label: "sortStats", dir: "desc", get: o => (o.has_statistics ? 1 : 0) },
    ];
    const domains = [...new Set(all.map(domainOf))].sort();
    const areas = [...new Set(all.map(o => this.areaName(o)).filter(Boolean))].sort();
    const platforms = [...new Set(all.map(o => o.platform).filter(Boolean))].sort();
    const pickCols = ["domain", "device", "area", "platform", "changed", "reported", "since", "stats"].map(k => ({ key: k, label: { domain: "utDomain", device: "utDevice", area: "utArea", platform: "utIntegration", changed: "utChanged", reported: "utReported", since: "utSince", stats: "utStats" }[k] }));
    this.setExporter("unreferenced", "unused-entities", [this.t("utName"), "ID", this.t("utDomain"), this.t("utDevice"), this.t("utArea"), this.t("utIntegration"), this.t("utChanged"), this.t("utReported"), this.t("utSince"), this.t("utStats")], () => rows.map(o => [o.name, o.object_id, domainOf(o), deviceName(o), this.areaName(o), o.platform || "", o.last_changed || "", o.last_reported || o.last_updated || "", o.status_since || "", this.data.meta.recorder_available ? (o.has_statistics ? "yes" : "no") : ""]));
    const bar = this.listBar("unreferenced", { table: true, dense: true, columns: pickCols, sorts, filters: [
      { name: "domain", all: this.t("allDomains"), options: domains.map(d => [d, `${d} (${all.filter(o => domainOf(o) === d).length})`]) },
      { name: "area", all: this.t("allAreas"), options: areas.map(a => [a, a]) },
      { name: "platform", all: this.t("allIntegrations"), options: platforms.map(p => [p, p]) },
    ] });
    const rows = this.refine("unreferenced", all, {
      text: o => [o.name, o.object_id, this.areaName(o), deviceName(o), o.platform].join(" "),
      filters: { domain: (o, v) => domainOf(o) === v, area: (o, v) => this.areaName(o) === v, platform: (o, v) => o.platform === v }, sorts, tie: o => o.object_id,
    });
    const pg = this.paginate("unreferenced", rows);
    const dash = `<span class="muted">–</span>`;
    const columns = [
      { key: "name", label: "utName", dir: "asc", sortKeys: ["id"], headSuffix: () => `<button type="button" class="thbtn th-alt" data-lsort="unreferenced|id|asc">ID${this.lv.unreferenced.sort === "id" ? ` <span aria-hidden="true">${this.lv.unreferenced.dir === "desc" ? "↓" : "↑"}</span>` : ""}</button>`, cell: o => this.nameCell(o.name, o.object_id) },
      { key: "domain", label: "utDomain", cell: o => this.esc(domainOf(o)) },
      { key: "device", label: "utDevice", cell: o => this.esc(deviceName(o)) || dash },
      { key: "area", label: "utArea", cell: o => this.esc(this.areaName(o)) || dash },
      { key: "platform", label: "utIntegration", cell: o => this.esc(o.platform || "") || dash },
      { key: "changed", label: "utChanged", dir: "desc", cell: o => this.ageCell(o.last_changed) },
      { key: "reported", label: "utReported", dir: "desc", cell: o => this.ageCell(o.last_reported || o.last_updated) },
      { key: "since", label: "utSince", cell: o => this.ageCell(o.status_since) },
      { key: "stats", label: "utStats", dir: "desc", cell: o => (this.data.meta.recorder_available ? this.t(o.has_statistics ? "yes" : "no") : dash) },
    ];
    const table = rows.length ? this.listTable("unreferenced", columns, pg.rows, { cls: "unref", rowAttrs: o => `data-object="${this.esc(this.objectKey(o))}" tabindex="0" role="button" aria-label="${this.esc(o.name)}"` }) : `<div class="emptymsg"><ha-icon icon="mdi:link-variant"></ha-icon>${all.length ? this.noMatches("unreferenced") : this.t("noUnreferenced")}</div>`;
    return `<div class="stack">${this._embedUnref ? "" : this.unrefTiles()}${this.unrefTabs()}<div class="panel"><p class="factnote">${this.t("unreferencedHint")}</p>${bar}${table}${pg.footer}</div></div>`;
  }

  // A battery entity is mostly called "Battery"; the device is the name one recognises.
  batteryName(item) {
    const device = item.device_id ? this.findObject(`device:${item.device_id}`) : null;
    return { title: device?.name || item.name, entity: device?.name && device.name !== item.name ? item.name : "", device };
  }

  batterySorts() {
    return [
      // Low batteries first, then the lowest level.
      { key: "level", label: "sortLevel", dir: "asc", get: r => (r.low ? 0 : 1e6) + (r.volt ? 1000 : 0) + (r.level ?? -1) },
      { key: "name", label: "sortName", dir: "asc", get: r => this.batteryName(r.item).title },
      { key: "area", label: "sortArea", dir: "asc", get: r => this.areaName(r.item) },
    ];
  }

  // Percent sensors plus the batteries that report volts; the volts come with the trend data, which is loaded in the background.
  lowBatteries() { return this.data ? [...this.batteryRows(), ...this.batteryVoltRows()].filter(r => r.low) : []; }

  batteriesView() {
    const all = this.batteryTableRows(), low = all.filter(r => r.low);
    this.lvState("batteries", "left", "asc");
    const areas = [...new Set(all.map(r => this.areaName(r.item)).filter(Boolean))].sort();
    const types = [...new Set(all.map(r => r.type).filter(Boolean))].sort();
    const need = this.data.meta.low_battery_percent ?? 20;
    const bar = this.listBar("batteries", { table: true, dense: true, sorts: this.batteryTableSorts(), filters: [
      { name: "soon", all: this.t("batteryAll"), options: [["soon", this.t("btFilterSoon")], ["untyped", this.t("btFilterUntyped")]] },
      { name: "type", all: this.t("btAllTypes"), options: types.map(x => [x, x]) },
      { name: "area", all: this.t("allAreas"), options: areas.map(a => [a, a]) },
    ] });
    const list = this.refine("batteries", this.batteryFilter === "low" ? low : all, {
      text: r => [this.batteryName(r.item).title, r.item.name, r.item.object_id, this.areaName(r.item), r.type].join(" "),
      filters: { area: (r, v) => this.areaName(r.item) === v, type: (r, v) => r.type === v, soon: (r, v) => (v === "soon" ? r.low || (r.days !== null && r.days <= 30) : !r.type) },
      sorts: this.batteryTableSorts(), tie: r => r.item.object_id,
    });
    const lowest = all.filter(r => !r.volt && r.level !== null && r.level !== undefined).sort((x, y) => x.level - y.level)[0];
    const chips = this.sumTiles([
      { label: this.t("batteryAll"), value: this.formatNumber(all.length), tone: "mute", attr: ["data-battery-filter", "all"], active: this.batteryFilter !== "low" },
      { label: this.t("batteryLow"), value: this.formatNumber(low.length), sub: this.t("batterySumLimit", { n: need }), tone: low.length ? "red" : "ok", attr: ["data-battery-filter", "low"], active: this.batteryFilter === "low" },
      lowest ? { label: this.t("batterySumLowest"), value: `${this.formatNumber(lowest.level)} %`, sub: this.esc([this.batteryName(lowest.item).title, this.areaName(lowest.item)].filter(Boolean).join(" · ")), tone: lowest.low ? "warn" : "mute", attr: ["data-object", this.objectKey(lowest.item)] } : null,
    ]);
    const unknown = this.batteryTrend?.unknown;
    const notes = `${this.batteryTrend?.available && unknown !== undefined ? `<p class="factnote">${this.t("btTableNote", { unknown: this.formatNumber(unknown) })}</p>` : ""}${this.voltNote()}`;
    const head = `<div class="panelhead"><div><h2>${this.t("btTitle")}</h2><p>${this.t("btHint")}</p></div></div>`;
    const body = list.length ? this.batteryTable(list) : `<div class="emptymsg"><ha-icon icon="mdi:battery-check-outline"></ha-icon>${this.t(all.length ? "noMatches" : "noBatteries")}</div>`;
    this.ensureBatteryTrend();
    const bar2 = this.pageBar({ at: this.loadedAt("batteries"), loading: this.batteryTrendLoading, attr: "data-bt-refresh" });
    // One column: when which battery runs out (need and forecast together), the list, then the kinds that need a look.
    return `<div class="stack">${bar2}${chips}${this.batteryNeed(all)}<div class="panel">${head}${this.filterNote(this.batteryFilter === "low" ? [this.t("batteryLow")] : [], 'data-battery-filter="all"')}${bar}${body}${notes}</div>${this.batteryCustomTypes()}${this.batteryKindCard()}</div>`;
  }
}

// DiagnosisMixin: methods of the panel element, mixed into the class in 99-register.js.
class DiagnosisMixin {
  relTime(value) {
    if (!value) return "";
    const diff = (Date.now() - new Date(value).getTime()) / 1000;
    if (!(diff >= 0)) return "";
    const rtf = new Intl.RelativeTimeFormat(this.lang, { numeric: "auto" });
    for (const [unit, secs] of [["day", 86400], ["hour", 3600], ["minute", 60]]) {
      if (diff >= secs) return rtf.format(-Math.floor(diff / secs), unit);
    }
    return rtf.format(0, "second");
  }

  integrationCheck(entryId) {
    const entry = this.findObject(`config_entry:${entryId}`), label = this.t("integration");
    if (!entry) return { row: this.check(label, "red", entryId, this.t("missing")), entry };
    if (entry.disabled_by) return { row: this.check(label, "mute", entry.name, this.t("disabled")), entry };
    const state = entry.state || "not_loaded";
    const tone = state === "loaded" ? "ok" : ["setup_error", "migration_error", "failed_unload"].includes(state) ? "red" : "warn";
    return { row: this.check(label, tone, entry.name, this.t(`cs_${state}`)), entry, broken: state !== "loaded", state };
  }

  // Builds the check list and the plain-language cause for one object. Returns null when nothing is worth explaining.
  diagnose(item) {
    const t = (k, v) => this.t(k, v);
    const rows = [];
    let cause = "", hint = "", tone = this.tone(item.status);
    if (tone === "blue") tone = "ok";

    if (item.object_type === "entity") {
      const integ = item.config_entry_id ? this.integrationCheck(item.config_entry_id) : null;
      if (integ) rows.push(integ.row);
      const device = item.device_id ? this.findObject(`device:${item.device_id}`) : null;
      if (item.device_id) {
        rows.push(!device ? this.check(t("device"), "red", item.device_id, t("missing"))
          : device.status === "disabled" ? this.check(t("device"), "mute", device.name, t("disabled"))
          : this.check(t("device"), "ok", device.name, t("active")));
      }
      if (item.disabled_by) rows.push(this.check(t("entity"), "mute", t("entity_disabled"), t("disabled")));
      const state = item.state;
      if (state === null || state === undefined) {
        rows.push(this.check(t("runtimeState"), item.disabled_by ? "mute" : "red", t("noState"), item.disabled_by ? t("notExpected") : t("missing")));
      } else if (state === "unavailable") rows.push(this.check(t("runtimeState"), "red", state, t("unavailable")));
      else if (state === "unknown") rows.push(this.check(t("runtimeState"), "violet", state, t("unknown")));
      else rows.push(this.check(t("runtimeState"), "ok", item.unit ? `${state} ${item.unit}` : state, t("available")));

      const stable = this.stabilityOf(item);
      if (stable?.info) {
        const flap = stable.info.level === "flapping";
        rows.push(this.check(t("stability"), flap ? "red" : "warn", this.unstableLines(stable.info, stable.r.window_days)[0], t(flap ? "relFlapping" : "relUnstable")));
      }
      const broken = integ?.broken ? { state: t(`cs_${integ.state}`) } : null;
      const logged = ["unavailable", null, undefined].includes(item.state) && !item.disabled_by ? this.data.objects.find(o => o.object_type === "config_entry" && o.object_id === item.config_entry_id)?.log : null;
      if (logged) rows.push(this.check(t("logTitle"), logged.level === "warning" ? "warn" : "red", this.logLine(logged), ""));
      switch (item.reason) {
        case "state_available": cause = t("cause_ok"); break;
        case "entity_disabled": case "device_disabled": case "integration_disabled": case "device_missing": case "config_entry_missing":
          cause = t(`cause_${item.reason}`); break;
        case "state_missing": cause = broken ? t("cause_state_missing_integration", broken) : t("cause_state_missing"); break;
        case "state_unavailable": cause = broken ? t("cause_state_unavailable_integration", broken) : t("cause_state_unavailable"); break;
        case "state_unknown": cause = t("cause_state_unknown"); break;
        default: cause = item.reason ? t(item.reason) : "";
      }
      const brokenMembers = this.data.findings.filter(f => f.rule_id === "entity.missing_member" && f.object_id === item.object_id);
      brokenMembers.forEach(f => rows.push(this.check(t("missing_member"), "red", f.affected_object, t("missing"))));
      if (item.duplicate_of) {
        rows.push(this.check(t("duplicateTwin"), "violet", item.duplicate_of, t("possible_duplicate")));
        cause = `${t("cause_duplicate", { twin: item.duplicate_of })} ${cause}`;
      }
      if (item.reason === "state_unavailable") hint = broken ? t("hint_integration") : t("hint_state_unavailable");
      else if (item.reason === "state_unknown") hint = t("hint_state_unknown");
      else if (item.reason === "state_missing" && broken) hint = t("hint_integration");
      else if (["state_missing", "device_missing", "config_entry_missing"].includes(item.reason)) hint = t("hint_orphan");
      if (item.duplicate_of) hint = t("hint_duplicate");
      if (stable?.info) {
        cause = `${t("cause_unstable", { level: t(stable.info.level === "flapping" ? "relFlapping" : "relUnstable") })} ${cause}`;
        if (tone === "ok") tone = stable.info.level === "flapping" ? "red" : "warn";
        if (!hint) hint = t("hint_unstable");
      }
      if (brokenMembers.length) {
        cause = `${t("cause_group_broken", { count: brokenMembers.length })} ${cause}`;
        hint = t("hint_group_broken");
        tone = "red";
      }
    } else if (item.object_type === "device") {
      const ids = item.config_entry_ids || [];
      ids.forEach(id => rows.push(this.integrationCheck(id).row));
      rows.push(this.check(t("entities"), item.entity_count ? "ok" : "warn", this.formatNumber(item.entity_count), item.entity_count ? t("present") : t("empty")));
      cause = item.status === "disabled" ? t("cause_device_off") : item.status === "empty" ? t("cause_device_empty") : t("cause_device_active");
    } else if (item.object_type === "config_entry") {
      const state = item.state || "not_loaded";
      if (item.disabled_by) { rows.push(this.check(t("status"), "mute", item.name, t("disabled"))); cause = t("cause_entry_off"); }
      else if (item.source === "ignore") { rows.push(this.check(t("status"), "mute", item.name, t("ignored"))); cause = t("cause_entry_ignored"); hint = t("hint_entry_ignored"); tone = "ok"; }
      else if (state === "loaded") { rows.push(this.check(t("status"), "ok", item.name, t("cs_loaded"))); cause = t("cause_entry_ok"); }
      else {
        rows.push(this.check(t("status"), tone, item.name, t(`cs_${state}`)));
        if (item.error) rows.push(this.check(t("entryError"), tone, item.error, ""));
        cause = t(item.error ? "cause_entry_problem_error" : "cause_entry_problem", { state: t(`cs_${state}`), error: item.error || "" }); hint = t("hint_integration");
      }
      const helperBroken = this.data.findings.filter(f => f.rule_id === "config_entry.missing_entity" && f.object_id === item.object_id);
      helperBroken.forEach(f => rows.push(this.check(t("missing_entity"), "red", [f.affected_object, this.placeText(f), this.suggestText(f)].filter(Boolean).join(" · "), t("missing"))));
      if (helperBroken.length) { cause = t("cause_helper_broken", { count: helperBroken.length }); hint = t("hint_helper_broken"); tone = "red"; }
    } else if (["automation", "script", "scene", "dashboard"].includes(item.object_type)) {
      const key = this.objectKey(item);
      const broken = this.data.findings.filter(f => this.findingKey(f) === key && f.rule_id.includes(".missing_"));
      const grouped = this.groupBroken(broken);
      grouped.forEach(g => rows.push(g.members ? this.brokenGroupRow(g) : this.check(t(g.rule_id.split(".")[1]), "red", [g.affected_object, this.placeText(g), this.suggestText(g)].filter(Boolean).join(" · "), t("missing"))));
      if (item.object_type === "automation" && item.status === "disabled") rows.push(this.check(t("status"), "mute", t("automationOff"), t("disabled")));
      if (!broken.length) rows.push(this.check(t("dependencies"), "ok", t("refsResolved"), t("present")));
      const unused = item.object_type === "automation" ? this.data.findings.find(f => this.findingKey(f) === key && f.classification === "unused") : null;
      if (item.object_type === "automation") {
        rows.push(this.check(t("lastTriggered"), unused ? "warn" : "ok", item.last_triggered ? this.formatDate(item.last_triggered) : t("never"), unused ? t("unused") : t("available")));
      }
      const runRow = this.runsRow(item), runWarn = (runRow?.findings || []).filter(f => f.level !== "info");
      runWarn.forEach(f => rows.push(this.check(t("knownRuns"), f.level, this.runFindingText(f).replace(/<[^>]+>/g, ""), t((RUN_FINDINGS[f.kind] || ["rfLabelFailing"])[0]))));
      const gone = [...new Set(broken.map(f => f.affected_object).filter(Boolean))];
      cause = broken.length ? (gone.length === 1 ? t("cause_broken_one", { name: item.name || item.object_id, target: gone[0] }) : t("cause_automation_broken", { count: broken.length })) : unused ? t(`cause_${unused.rule_id.split(".")[1]}`, { days: unused.evidence?.[0]?.days ?? "" }) : runWarn.length ? this.runFindingText(runWarn[0]).replace(/<[^>]+>/g, "") : t("cause_automation_ok");
      if (runWarn.length && !broken.length && !unused) { hint = t(`rfHint_${runWarn[0].kind}`); tone = "warn"; }
      if (unused && !broken.length) { hint = t("hint_unused"); tone = "warn"; }
      if (broken.length) { hint = t("hint_automation_broken"); tone = "red"; }
      const orphan = grouped.find(g => g.members && this.isOrphan(g.members[0].evidence[0].place));
      if (orphan) { const p = orphan.members[0].evidence[0].place; hint = t("brokenOrphanHint", { card: p.card, view: p.view ?? "", missing: p.card_missing, total: p.card_refs }); }
    } else return null;
    return { rows, cause, hint, tone };
  }

  diagnosisCard(item) {
    const d = this.diagnose(item);
    if (!d) return "";
    const icon = { ok: "mdi:check-circle", warn: "mdi:alert-circle", red: "mdi:close-circle", mute: "mdi:minus-circle", violet: "mdi:help-circle" };
    const rows = d.rows.map(r => `<div class="check ${r.tone}"><ha-icon icon="${icon[r.tone] || icon.ok}"></ha-icon><b>${this.esc(r.label)}</b><span class="val">${this.esc(r.value)}</span><i class="pill ${r.tone}">${this.esc(r.badge)}</i></div>`).join("");
    return `<section class="panel"><div class="panelhead"><div><h2>${this.t("diagnosis")}</h2></div></div>
      <div class="diagcard">${this.ratingBlock(item, this.objectKey(item))}<div class="checks">${rows}</div>
      ${d.cause ? `<div class="cause ${d.tone}"><ha-icon icon="mdi:text-search"></ha-icon><div><strong>${this.t("causeLabel")}</strong><p>${this.esc(d.cause)}</p></div></div>` : ""}
      ${d.hint ? `<div class="hintbox"><ha-icon icon="mdi:lightbulb-on-outline"></ha-icon><div><strong>${this.t("hintLabel")}</strong><p>${this.esc(d.hint)}</p></div></div>` : ""}</div></section>`;
  }

  // Read-only what-if: which automations would lose a reference if this object (and what it owns) were removed.
  impact(item, key) {
    if (["automation", "script", "scene", "dashboard"].includes(item.object_type)) return null;
    const OWNED = ["PROVIDES", "OWNS"], USAGE = USAGE_RELATIONS;
    const scope = new Set([key]);
    for (const member of scope) { // grows while iterating: what the object owns, and what that owns
      for (const e of this.edgesFrom(member)) if (OWNED.includes(e.relation)) scope.add(e.target);
    }
    const { order } = this.edgeIndex();
    const byAutomation = new Map();
    const used = [];
    for (const member of scope) used.push(...this.edgesTo(member));
    used.sort((a, b) => order.get(a) - order.get(b)); // the order of the edges as scanned
    for (const e of used) {
      if (!USAGE.includes(e.relation) || !scope.has(e.target) || scope.has(e.source) || !(/^(automation|script|scene|dashboard|config_entry):/.test(e.source) || e.relation === "INCLUDES")) continue;
      const hit = byAutomation.get(e.source) || { key: e.source, certain: false, places: [] };
      if (e.confidence === "certain") hit.certain = true;
      if (e.location && e.location !== "runtime_extraction") hit.places.push(e.location);
      byAutomation.set(e.source, hit);
    }
    const hits = [...byAutomation.values()].sort((a, b) => Number(b.certain) - Number(a.certain));
    const certain = hits.filter(h => h.certain).length;
    const tone = certain ? "red" : hits.length ? "warn" : "ok";
    return { hits, certain, probable: hits.length - certain, tone, related: scope.size - 1 };
  }

  impactCard(item, key) {
    const m = this.impact(item, key);
    if (!m) return "";
    const title = m.certain ? "impactCertain" : m.hits.length ? "impactProbable" : "impactNone";
    const text = m.certain ? this.t("impactCertainText", { count: m.certain }) : m.hits.length ? this.t("impactProbableText", { count: m.probable }) : this.t("impactNoneText");
    const icon = { ok: "mdi:check-circle", warn: "mdi:alert-circle", red: "mdi:alert-octagon" }[m.tone];
    const hitRows = m.hits.map(h => {
      const obj = this.findObject(h.key);
      const note = `${this.t(h.certain ? "certain" : "probable")}${h.places.length ? ` · ${h.places.slice(0, 2).join(", ")}` : ""}`;
      return `<button class="row rel" data-object="${this.esc(h.key)}">${this.tile(h.key.split(":")[0], h.certain ? "red" : "warn")}<span class="row-text"><strong>${this.esc(obj?.name || h.key.split(":").slice(1).join(":"))}</strong><small>${this.esc(note)}</small></span>${obj ? this.pill(obj.status) : ""}</button>`;
    });
    const hitPage = this.paginate(`impact-${key}`, hitRows), rows = hitPage.rows.join("") + hitPage.footer;
    return `<section class="panel"><div class="panelhead"><div><h2>${this.t("impactTitle")}</h2><p>${this.t("impactSubtitle")}</p></div></div>
      <div class="diagcard"><div class="cause ${m.tone}"><ha-icon icon="${icon}"></ha-icon><div><strong>${this.t(title)}</strong><p>${this.esc(text)}</p></div></div></div>${rows}
      ${item.object_type === "entity" && item.has_statistics ? `<p class="factnote">${this.t("statsNote")}</p>` : ""}
      <p class="factnote">${m.related ? this.t("impactScope", { count: m.related }) : this.t("impactScopeOne")} ${this.t("impactLimits")}</p></section>`;
  }

  // The newest long-term row of an entity, asked once per entity when its details open.
  ensureStatLast(id) {
    const asked = (this._statLastAsked ||= new Set());
    if (asked.has(id)) return;
    asked.add(id);
    setTimeout(async () => {
      try {
        const r = await this._hass.callWS({ type: "ha_housekeeper/statistics_last", ids: [id] });
        if (r?.busy) { asked.delete(id); return; }
        (this.statLast ||= {})[id] = r?.last?.[id] ?? 0; (this.statSpan ||= {})[id] = { first: r?.first?.[id] ?? 0, rows: r?.rows?.[id] ?? 0 };
      } catch (_) { return; }
      if (this.selected?.object_id === id) this.render();
    }, 0);
  }

  factsCard(item, key) {
    const finding = this.data.findings.find(f => this.findingKey(f) === key);
    const info = this.data.meta.outage_info_minutes || 0;
    const facts = [];
    if (item.status_since) facts.push([this.t("since"), `${this.formatDate(item.status_since)}<small>${this.esc(this.relTime(item.status_since))} · ${this.t("firstSeenNote")}</small>`]);
    if (["entity", "automation", "script", "scene", "dashboard"].includes(item.object_type)) {
      facts.push([this.t("finding"), finding ? `${this.pill(finding.classification)}<small>${this.t("certainty")}: ${Math.round(finding.confidence * 100)} %</small>` : this.t("noFinding")]);
    }
    const quarantined = ["entity", "device"].includes(item.object_type) ? this.quarantineOf(item.object_id) : null;
    if (quarantined) facts.push([this.t("quarantine"), `${this.t("quarantineFact", { date: this.formatDate(quarantined.since), days: this.daysSince(quarantined.since) })}<span class="factaction">${this.releaseControl(quarantined)}</span>`]);
    const outage = finding && OUTAGE_RULES.includes(finding.rule_id) ? this.outageLineOf(finding) : "";
    if (outage) facts.push([this.t("chip_outage"), this.esc(outage)]);
    const note = item.status === "unavailable" && !finding && info > 0 ? `<p class="factnote">${this.t("belowThreshold", { span: `${info} ${this.t("unitMin")}` })}</p>` : "";
    return `<section class="panel"><div class="panelhead"><h2>${this.t("facts")}</h2></div><div class="facts">${facts.map(([k, v]) => `<div class="fact"><span>${k}</span><b>${v}</b></div>`).join("")}</div>${note}</section>`;
  }

  // One row per object and kind of relation: a blueprint automation names the same entity at many
  // places, and a list with a row for each of them reads like that many different dependencies.
  mergePlaces(list) {
    const rows = new Map();
    for (const x of list) {
      const place = x.edge.location && x.edge.location !== "runtime_extraction" ? x.edge.location : "";
      const known = rows.get(`${x.other}|${x.label}`);
      if (known) known.places.push(place); else rows.set(`${x.other}|${x.label}`, { ...x, places: [place] });
    }
    return [...rows.values()];
  }

  relationsCard(key) {
    const USAGE = USAGE_RELATIONS;
    const incoming = this.edgesTo(key), outgoing = this.edgesFrom(key);
    const groups = [
      [this.t("origin"), incoming.filter(e => !USAGE.includes(e.relation)).map(e => ({ other: e.source, label: this.t(e.relation), edge: e }))],
      [this.t("usage"), [
        ...incoming.filter(e => USAGE.includes(e.relation)).map(e => ({ other: e.source, label: `${this.t("usedBy")} · ${this.t(e.relation)}`, edge: e })),
        ...outgoing.map(e => ({ other: e.target, label: this.t(e.relation), edge: e })),
      ]],
    ].map(([title, list]) => [title, this.mergePlaces(list)]).filter(([, list]) => list.length);
    // A target without an inventory object is missing only where a finding says so; helpers and
    // built-in entities such as sun.sun exist without a registry entry.
    const gone = new Set((this.data.findings || []).filter(f => f.classification === "broken_reference").map(f => f.affected_object));
    const items = groups.flatMap(([title, list], i) => list.map(x => ({ ...x, group: i ? "usage" : "origin", groupName: title })));
    const nameOf = x => this.findObject(x.other)?.name || x.other.split(":").slice(1).join(":");
    const typeOf = x => this.findObject(x.other)?.object_type || x.other.split(":")[0];
    const note = x => (x.places.length > 1 ? `${x.label} · ${this.t("relPlaces", { n: x.places.length })}` : `${x.label}${x.places[0] ? ` · ${x.places[0]}` : ""}`);
    const goneLabel = x => (gone.has(x.other.split(":").slice(1).join(":")) ? this.t("missing") : this.t("notInInventory"));
    const table = items.length ? this.sysList("relations", items, {
      sort: "name", dir: "asc", cls: "rel", tie: x => `${x.other}|${x.label}`, exportName: "relations",
      sorts: [{ key: "name", label: "relColObject", dir: "asc", get: nameOf }, { key: "type", label: "relColType", dir: "asc", get: typeOf }, { key: "relation", label: "relColRelation", dir: "asc", get: x => x.label }],
      text: x => `${nameOf(x)} ${x.other} ${x.label}`,
      filters: [{ name: "group", all: this.t("relAllGroups"), options: [["origin", this.t("origin")], ["usage", this.t("usage")]] }],
      filterFns: { group: (x, v) => x.group === v },
      rowAttrs: x => (this.findObject(x.other) ? `data-object="${this.esc(x.other)}" tabindex="0" role="button" aria-label="${this.esc(nameOf(x))}"${x.places.length > 1 ? ` title="${this.esc(x.places.filter(Boolean).join("\n"))}"` : ""}` : 'class="static"'),
      columns: [
        { key: "name", label: "relColObject", dir: "asc", cell: x => { const obj = this.findObject(x.other); return `<div class="statcell">${this.tile(typeOf(x), obj ? (this.tone(obj.status) === "ok" ? "" : this.tone(obj.status)) : gone.has(x.other.split(":").slice(1).join(":")) ? "red" : "")}<div>${this.nameCell(nameOf(x), x.other)}</div></div>`; } },
        { key: "type", label: "relColType", dir: "asc", cell: x => this.esc(this.t(typeOf(x))) },
        { key: "relation", label: "relColRelation", dir: "asc", cell: x => this.esc(note(x)) },
        { key: "group", label: "relColKind", sortable: false, cell: x => this.esc(x.groupName) },
        { key: "status", label: "relColStatus", sortable: false, cell: x => { const obj = this.findObject(x.other); return obj ? this.pill(obj.status) : `<span class="pill ${gone.has(x.other.split(":").slice(1).join(":")) ? "red" : ""}">${this.esc(goneLabel(x))}</span>`; } },
      ],
      header: [this.t("relColObject"), "ID", this.t("relColType"), this.t("relColRelation"), this.t("relColKind")], rows: x => [nameOf(x), x.other, this.t(typeOf(x)), note(x), x.groupName],
    }) : "";
    return `<section class="panel"><div class="panelhead"><h2>${this.t("relations")} (${incoming.length + outgoing.length})</h2></div>${table || `<p class="factnote">${this.t("noRelations")}</p>`}</section>`;
  }

  entrySourceLabel(source) {
    const known = ["user", "import", "ignore", "system", "reauth", "reconfigure"];
    return known.includes(source) ? this.t(`src_${source}`) : this.t("src_discovery", { source });
  }

  // Everything that says which integration an entry belongs to and where it comes from.
  integrationCard(item) {
    if (item.object_type !== "config_entry") return "";
    const state = item.state || "not_loaded";
    const path = this.haPath(item);
    const origin = item.custom ? this.t("originCustom", { path: item.integration_dir || item.domain, version: item.integration_version ? ` · v${item.integration_version}` : "" }) : this.t("originBuiltIn");
    const link = (href, text) => `<a href="${this.esc(href)}" target="_blank" rel="noopener noreferrer">${this.esc(text)}</a>`;
    const rows = [
      [this.t("integrationName"), `${this.esc(item.integration_name || item.domain)} <small>(${this.esc(item.domain)})</small>`],
      [this.t("origin"), this.esc(origin)],
      [this.t("entrySource"), `${this.esc(this.entrySourceLabel(item.source))} <small>(${this.esc(item.source)})</small>`],
      [this.t("status"), `${this.esc(item.disabled_by ? this.t("disabled") : this.t(`cs_${state}`))}${item.disabled_by ? ` <small>(${this.esc(item.disabled_by)})</small>` : ""}`],
      item.error ? [this.t("entryError"), this.esc(item.error)] : null,
      [this.t("entryEntities"), this.formatNumber(item.entity_count ?? 0)],
      [this.t("entryDevices"), this.formatNumber(item.device_count ?? 0)],
      [this.t("entryId"), `<code>${this.esc(item.object_id)}</code>`],
      item.unique_id ? [this.t("entryUniqueId"), `<code>${this.esc(item.unique_id)}</code>`] : null,
      item.created_at ? [this.t("entryCreated"), this.esc(this.formatDate(item.created_at))] : null,
      item.modified_at ? [this.t("entryModified"), this.esc(this.formatDate(item.modified_at))] : null,
      path ? [this.t("entryHaPath"), `<code>${this.esc(path)}</code>`] : null,
      item.documentation ? [this.t("entryDocs"), link(item.documentation, item.documentation)] : null,
    ].filter(Boolean);
    return `<section class="panel"><div class="panelhead"><h2>${this.t("integrationCard")}</h2></div><div class="pad"><dl class="kv">${rows.map(([k, v]) => `<dt>${this.esc(k)}</dt><dd>${v}</dd>`).join("")}</dl></div></section>`;
  }

  // The always-visible summary under the title: status, cause, since when, integration, device, area, risk.
  detailSummary(item, key) {
    if (item.object_type === "integration") return this.intSummary(item);
    const device = item.device_id ? this.findObject(`device:${item.device_id}`) : null;
    const areaId = item.area_id || device?.area_id, area = areaId ? this.findObject(`area:${areaId}`) : null;
    const integration = item.object_type === "entity" ? item.platform : item.object_type === "config_entry" ? (item.integration_name || item.domain) : null;
    const impact = this.impact(item, key);
    const risk = impact ? { tone: impact.tone, text: impact.hits.length ? this.t("riskHits", { n: impact.hits.length, c: impact.certain }) : this.t("riskNone") } : null;
    return [
      item.reason ? [this.t("sumCause"), this.esc(this.t(item.reason))] : null,
      item.status_since ? [this.t("since"), this.esc(this.formatDate(item.status_since))] : null,
      integration ? [this.t("sumIntegration"), item.object_type === "config_entry" && this.findObject(`integration:${item.domain}`) ? `<button class="link" data-object="${this.esc(`integration:${item.domain}`)}" title="${this.esc(this.t("intToIntegration"))}">${this.esc(integration)}</button>` : this.esc(integration)] : null,
      device ? [this.t("sumDevice"), this.esc(device.name)] : null,
      area ? [this.t("sumArea"), this.esc(area.name)] : null,
      risk ? [this.t("sumRisk"), `<span class="pill ${risk.tone}">${this.esc(risk.text)}</span>`] : null,
    ].filter(Boolean);
  }

  // Tabs offered for one object; "attributes" only when it has some, so an empty tab never shows.
  detailTabs(item, key) {
    if (item.object_type === "integration") return this.intTabs(item);
    // An app has only the mark as an action; its rights and its load come from the two system reports, its relations are the integrations that seem to use it.
    if (item.object_type === "app") return [["overview", "tabOverview"], ...(this.hasActionsTab(item, key) ? [["actions", "tabActions", 0]] : []), ...(this.edgesTo(key).length ? [["relations", "tabRelations", this.edgesTo(key).length]] : []), ["access", "accAppTab", null, this.appAccessTone(item)], ["storage", "accAppLoad"], ["technical", "tabTechnical"]];
    const tabs = [["overview", "tabOverview"], ["relations", "tabRelations", this.edgesTo(key).length + this.edgesFrom(key).length], ["technical", "tabTechnical"]];
    if (this.hasActionsTab(item, key)) tabs.splice(1, 0, ["actions", "tabActions", this.fixItems(item, key).items.length]);
    if (item.attributes && Object.keys(item.attributes).length) tabs.push(["attributes", "tabAttributes"]);
    if (["automation", "script"].includes(item.object_type) && (item.actions?.length || item.triggers?.length)) tabs.push(["flow", "flowTab"]);
    if (NOTE_TYPES.includes(item.object_type)) tabs.push(["history", "tabHistory", this.historyCount(item)]);
    if (this.runsRow(item)) tabs.push(["runs", "runsTab"]);
    if (this.reliabilityRow(item)) tabs.push(["reliability", "relTab"]);
    if (this.diagRow(item)) tabs.splice(tabs.findIndex(([id]) => id === "technical"), 0, ["diagnosis", "diagTab"]);
    if (item.object_type === "config_entry") tabs.push(["access", "accTab", null, this.accessTone(item)]);
    return tabs;
  }

  detail() {
    const base = this.selected;
    const item = { ...base, ...(this.details.get(this.objectKey(base)) || {}) };
    const key = this.objectKey(item);
    if (["automation", "script"].includes(item.object_type)) { this.ensureRuns(); this.ensureQuality(); }
    if (item.object_type === "config_entry" || item.object_type === "integration") this.ensureReliability();
    if (item.object_type === "integration" && item.custom && this.detailTab === "overview") this.sysEnsure("storage"); // the folder size
    if (item.object_type === "integration" && this.detailTab === "access") { this.sysEnsure("dataflow"); this.sysEnsure("secrets"); }
    // The reports of Access & data flow and Credentials are read when their tab is opened, not with the page.
    if (item.object_type === "config_entry" && this.detailTab === "access") { this.sysEnsure("dataflow"); this.sysEnsure("secrets"); }
    if (item.object_type === "app" && this.detailTab === "access") this.sysEnsure("dataflow");
    if (item.object_type === "app" && this.detailTab === "storage") this.sysEnsure("storage");
    if (item.object_type === "entity") this.ensureStability();
    if (item.object_type === "device") this.ensureLifecycle(item.object_id);
    if (NOTE_TYPES.includes(item.object_type)) this.ensureJournal();
    this.ensureCorrelations();
    const tabs = this.detailTabs(item, key);
    const tab = tabs.some(([id]) => id === this.detailTab) ? this.detailTab : "overview";
    const path = this.haPath(item), tone = this.tone(item.status) === "ok" ? "" : this.tone(item.status);
    const back = this.trail.length ? this.trail[this.trail.length - 1].name : this.t(this.view);
    const summary = this.detailSummary(item, key).map(([label, value]) => `<span><small>${label}</small><b>${value}</b></span>`).join("");
    const tablist = tabs.map(([id, label, count, tone]) => `<button class="tab" role="tab" id="hk-tab-${id}" aria-selected="${id === tab}" aria-controls="hk-tabpanel" tabindex="${id === tab ? 0 : -1}" data-detail-tab="${id}">${this.t(label)}${count ? ` <em>${this.formatNumber(count)}</em>` : ""}${tone ? `<i class="tabdot ${tone}" aria-hidden="true"></i>` : ""}</button>`).join("");
    return `<div class="crumbs"><button class="btn" data-action="back"><ha-icon icon="mdi:arrow-left"></ha-icon>${this.t("backTo")} ${this.esc(back)}</button><span class="trail">${this.t(this.view)} › ${this.t(item.object_type)}</span></div>
      <div class="panel detailhead">${this.tile(item.object_type, tone)}<div><div class="headpills">${this.pill(item.status)}<span class="pill mute">${this.t(item.object_type)}</span></div><h1>${this.esc(item.name)}</h1><span class="id">${this.esc(item.object_id)}</span></div>
      <div class="actions">${path ? `<button class="btn" data-ha-path="${this.esc(path)}"><ha-icon icon="mdi:open-in-new"></ha-icon>${this.t("openInHA")}</button>` : ""}<button class="btn" data-graph-open="${this.esc(item.object_type === "integration" ? this.objectKey(item.entries[0]) : key)}"><ha-icon icon="mdi:source-fork"></ha-icon>${this.t("showInGraph")}</button>${["entity", "device", "area", "automation", "script", "scene", "dashboard"].includes(item.object_type) ? `<button class="btn" data-xp-from="${this.esc(key)}"><ha-icon icon="mdi:export-variant"></ha-icon>${this.t("xpButton")}</button>` : ""}</div></div>
      <div class="panel sumline">${summary}</div>
      ${this.statusBand(item, key)}
      <div class="tabs" role="tablist" aria-label="${this.esc(this.t("tabsLabel"))}">${tablist}</div>
      <div role="tabpanel" id="hk-tabpanel" aria-labelledby="hk-tab-${tab}" tabindex="0">${tab === "overview" ? this.accessAlert(item) : ""}${this.detailPanel(tab, item, key)}</div>`;
  }

  // Only the open tab is built, so large attributes and relations cost nothing until they are asked for.
  detailPanel(tab, item, key) {
    if (item.object_type === "integration") return this.intPanel(tab, item);
    if (tab === "actions") return this.actionsTab(item, key);
    if (tab === "relations") return `<div class="stack">${this.relationsCard(key)}</div>`;
    if (tab === "flow") return this.flowCard(item, key);
    if (tab === "history") return this.historyTab(item);
    if (tab === "diagnosis") return this.diagTab(item);
    if (tab === "runs") return this.runsDetailCard(this.runsRow(item));
    if (tab === "reliability") return this.reliabilityDetailCard(this.reliabilityRow(item));
    if (tab === "access") return item.object_type === "app" ? this.appAccessCard(item) : this.accessDetailCard(item);
    if (tab === "storage") return this.appLoadCard(item);
    if (tab === "overview" && item.object_type === "app") return this.appOverview(item);
    if (tab === "attributes") {
      return `<section class="panel"><div class="panelhead"><h2>${this.t("state")}</h2></div><div class="pad"><div class="code">${this.esc(JSON.stringify(item.attributes, null, 2))}</div></div></section>`;
    }
    if (tab === "technical") {
      const skip = new Set(["attributes", "references", "name", "object_id", "object_type", "status", "reason", "state", "status_since", "status_since_source", "triggers", "conditions", "actions"]);
      if (item.object_type === "config_entry") ["domain", "integration_name", "custom", "integration_dir", "integration_version", "documentation", "source", "error", "unique_id", "entity_count", "device_count", "created_at", "modified_at", "disabled_by"].forEach(k => skip.add(k));
      const fields = Object.entries(item).filter(([k, v]) => !skip.has(k) && v !== null && v !== undefined && (typeof v !== "object" || Array.isArray(v)));
      const automation = ["automation", "script"].includes(item.object_type) && !this.detailLoading
        ? `<section class="panel"><div class="panelhead"><h2>${this.t("automationStructure")}</h2></div><div class="pad">${(item.object_type === "script" ? ["actions"] : ["triggers", "conditions", "actions"]).map(part => `<h4>${this.t(part)} (${item[part]?.length || 0})</h4><div class="code">${this.esc(JSON.stringify(item[part] || [], null, 2))}</div>`).join("")}</div></section>` : "";
      const cards = this.propertyCards(item);
      const labelOnly = ["automation", "script", "scene", "area"].includes(item.object_type);
      return `<div class="stack">${cards ? `<div class="propgrid">${cards}</div>` : ""}${cards && !labelOnly ? "" : `<section class="panel"><div class="panelhead"><h2>${this.t("registry")}</h2></div><div class="pad"><dl class="kv"><dt>${this.t("type")}</dt><dd>${this.t(item.object_type)}</dd>${fields.map(([k, v]) => `<dt>${this.esc(k)}</dt><dd>${this.esc(Array.isArray(v) ? v.join(", ") : v)}</dd>`).join("")}</dl></div></section>`}${automation}${this.detailLoading ? `<p class="sub">${this.t("loading")}</p>` : ""}</div>`;
    }
    if (ACTION_TYPES.includes(item.object_type)) return `<div class="detailgrid"><div class="stack">${this.diagnosisCard(item)}${this.polObjectCard(item)}${this.nextStepBand(item, key)}${this.impactCard(item, key)}</div><div class="stack">${KNOWN_TYPES.includes(item.object_type) ? this.knownCard(item, key) : this.factsCard(item, key)}${this.entityRecorderCard(item)}</div></div>`;
    return `<div class="detailgrid"><div class="stack">${this.diagnosisCard(item)}${this.polObjectCard(item)}${this.actionsCard(item, key)}${this.detailEditCard(item)}${this.impactCard(item, key)}</div><div class="stack">${this.factsCard(item, key)}${this.entityRecorderCard(item)}${this.entityTrimCard(item)}${this.staleCard(item)}</div></div>`;
  }
}

// PropertiesMixin: property cards for entity and device pages (assignment, properties, technical data, times).
class PropertiesMixin {
  propLink(key, text, sub = "") {
    const obj = this.findObject(key);
    if (!obj) return this.esc(text);
    return `<button class="link" data-object="${this.esc(key)}">${this.esc(text)}</button>${sub ? ` <small>${this.esc(sub)}</small>` : ""}`;
  }

  propChips(names) { return names.length ? `<span class="chips bare">${names.map(n => `<span class="chip">${this.esc(n)}</span>`).join("")}</span>` : ""; }

  // The registry gives 1970 for objects created before it recorded the time; that is "unknown", not a date.
  realTime(value) { return value && Date.parse(value) >= Date.UTC(2000, 0, 1) ? value : ""; }

  propTime(value) { return this.realTime(value) ? `${this.esc(this.formatDate(value))} <span class="rel">· ${this.esc(this.relTime(value))}</span>` : ""; }

  propCard(title, icon, rows) {
    const shown = rows.filter(r => r && r[1] !== "" && r[1] !== null && r[1] !== undefined);
    if (!shown.length) return "";
    return `<section class="panel"><div class="panelhead"><h2 class="proph"><ha-icon icon="${icon}"></ha-icon>${this.esc(title)}</h2></div><div class="pad"><dl class="kv">${shown.map(([k, v, tip]) => `<dt${tip ? ` title="${this.esc(tip)}"` : ""}>${this.esc(k)}</dt><dd>${v}</dd>`).join("")}</dl></div></section>`;
  }

  propCode(value) { return value ? `<code>${this.esc(value)}</code>` : ""; }

  propArea(areaId, deviceAreaId) {
    const name = id => this.findObject(`area:${id}`)?.name || id;
    if (areaId) return this.propLink(`area:${areaId}`, name(areaId));
    return deviceAreaId ? this.t("propAreaInherited", { area: this.esc(name(deviceAreaId)) }) : "";
  }

  propLabels(ids) { return this.propChips((ids || []).map(id => this.findObject(`label:${id}`)?.name || id)); }

  // The labels of an object, always as a row: its own, or a note that there are none.
  labelRows(item) {
    return [[this.t("propLabels"), this.propLabels(item.labels) || `<span class="muted">${this.esc(this.t("propLabelsNone"))}</span>`]];
  }

  // Automations, scripts, scenes and areas have no property cards; their labels still get their place.
  labelCard(item) { return this.propCard(this.t("propAssignment"), "mdi:link-variant", this.labelRows(item)); }

  propBy(value) { return value ? this.t(`by_${value}`) : ""; }

  entityCards(item) {
    const t = k => this.t(k), device = item.device_id ? this.findObject(`device:${item.device_id}`) : null;
    const entry = item.config_entry_id ? this.findObject(`config_entry:${item.config_entry_id}`) : null;
    const integration = entry ? this.propLink(`config_entry:${entry.object_id}`, entry.integration_name || entry.name, entry.integration_name ? `(${entry.domain})` : "") : this.esc(item.platform || "");
    const deviceSub = device ? [device.manufacturer, device.model].filter(Boolean).join(" ") : "";
    const assignment = this.propCard(t("propAssignment"), "mdi:link-variant", [
      [t("propIntegration"), integration],
      [t("propDeviceOf"), device ? this.propLink(`device:${device.object_id}`, device.name, deviceSub) : ""],
      [t("propArea"), this.propArea(item.area_id, device?.area_id)],
      ...this.labelRows(item),
    ]);
    const properties = this.propCard(t("propProperties"), "mdi:tune-variant", [
      [t("propDomain"), this.esc(item.object_id.split(".")[0])],
      [t("propDeviceClass"), this.esc(item.device_class || "")],
      [t("propStateClass"), this.esc(item.state_class || item.attributes?.state_class || "")],
      [t("propUnit"), this.esc(item.unit || "")],
      [t("propCategory"), item.entity_category ? this.esc(this.t(`cat_${item.entity_category}`)) : ""],
      [t("propOriginalName"), item.original_name && item.original_name !== item.name ? this.esc(item.original_name) : ""],
      [t("propAliases"), this.propChips(item.aliases || [])],
      [t("propIcon"), item.icon ? this.propCode(item.icon) : ""],
      [t("propDisabledBy"), this.esc(this.propBy(item.disabled_by))],
      [t("propHiddenBy"), this.esc(this.propBy(item.hidden_by))],
    ]);
    const technical = this.propCard(t("propTechnical"), "mdi:identifier", [
      [t("propEntityId"), this.propCode(item.object_id)], [t("propUniqueId"), this.propCode(item.unique_id)], [t("propPlatform"), this.propCode(item.platform)],
    ]);
    const times = this.propCard(t("propTimes"), "mdi:clock-outline", [
      [t("propCreated"), this.propTime(item.created_at)], [t("propModified"), this.propTime(item.modified_at)],
      [t("propLastChangedShort"), this.propTime(item.last_changed), t("propLastChanged")], [t("propLastUpdatedShort"), this.propTime(item.last_updated), t("propLastUpdated")],
    ]);
    // Two columns, each card as high as its content: assignment and ids on the left, properties and times on the right.
    return `<div class="propcol">${assignment}${technical}</div><div class="propcol">${properties}${times}</div>`;
  }

  deviceCards(item) {
    const t = k => this.t(k);
    const via = item.via_device_id ? this.findObject(`device:${item.via_device_id}`) : null;
    const parent = item.parent_device_id ? this.findObject(`device:${item.parent_device_id}`) : null;
    const children = this.data.objects.filter(o => o.object_type === "device" && (o.via_device_id === item.object_id || o.parent_device_id === item.object_id));
    const isChild = item.device_kind === "child";
    // The same two structural reasons that block a cleanup plan (see cleanup.py), so the page explains the block before a plan is made.
    const blocks = [isChild ? "reason_child_device" : "", children.length ? "reason_has_children" : ""].filter(Boolean).map(k => this.esc(this.t(k))).join("<br>");
    const entries = (item.config_entry_ids || []).map(id => this.findObject(`config_entry:${id}`)).filter(Boolean);
    const info = this.propCard(t("propDevice"), "mdi:devices", [
      [t("propManufacturer"), this.esc(item.manufacturer || "")],
      [t("propModel"), this.esc([item.model, item.model_id && item.model_id !== item.model ? `(${item.model_id})` : ""].filter(Boolean).join(" "))],
      [t("propSerial"), this.propCode(item.serial_number)],
      [t("propFirmware"), this.esc(item.sw_version || "")],
      [t("propHardware"), this.esc(item.hw_version || "")],
      [t("propEntryType"), item.entry_type ? this.esc(this.t(`type_${item.entry_type}`) === `type_${item.entry_type}` ? item.entry_type : this.t(`type_${item.entry_type}`)) : ""],
      [t("propUserName"), item.original_name ? this.esc(item.name) : ""],
      [t("propOriginalDeviceName"), this.esc(item.original_name || "")],
    ]);
    const assignment = this.propCard(t("propAssignment"), "mdi:link-variant", [
      [t("propIntegration"), entries.map(e => this.propLink(`config_entry:${e.object_id}`, e.integration_name || e.name, e.integration_name ? `(${e.domain})` : "")).join("<br>")],
      [t("propArea"), this.propArea(item.area_id, null)],
      [t("propKind"), isChild ? t("propKindChild") : ""],
      [t("propParent"), parent ? this.propLink(`device:${parent.object_id}`, parent.name) : ""],
      [t("propVia"), via ? this.propLink(`device:${via.object_id}`, via.name) : ""],
      [t("propChildren"), children.length ? this.t("propChildrenCount", { count: children.length }) : ""],
      [t("propCleanupBlock"), blocks],
      ...this.labelRows(item),
      [t("propConfigUrl"), /^https?:\/\//i.test(item.configuration_url || "") ? `<a href="${this.esc(item.configuration_url)}" target="_blank" rel="noopener noreferrer">${this.esc(item.configuration_url)}</a>` : this.esc(item.configuration_url || "")],
    ]);
    const members = this.data.objects.filter(o => o.object_type === "entity" && o.device_id === item.object_id).sort((a, b) => a.name.localeCompare(b.name));
    const memberRows = this.objectTable(`members-${item.object_id}`, members.map(m => ({ key: `entity:${m.object_id}`, type: "entity", name: m.name, sub: m.object_id, tone: this.tone(m.status), state: m.status, stateLabel: this.statusLabel(m.status), pill: this.pill(m.status), value: m.state === null || m.state === undefined ? "" : `${m.state}${m.unit ? ` ${m.unit}` : ""}` })), {
      extras: [{ key: "value", label: "objColState", get: r => r.value, cell: r => r.value ? this.esc(r.value) : `<span class="muted">—</span>` }], empty: t("propNoEntities"),
    });
    const entities = `<section class="panel wide"><div class="panelhead"><h2><ha-icon icon="mdi:shape-outline" class="propicon"></ha-icon>${t("propEntities")} (${members.length})</h2></div>${memberRows}</section>`;
    const technical = this.propCard(t("propTechnical"), "mdi:identifier", [
      [t("propDeviceId"), this.propCode(item.object_id)],
      [t("propIdentifiers"), (item.identifiers || []).map(v => this.propCode(v)).join("<br>")],
      [t("propConnections"), (item.connections || []).map(v => this.propCode(v)).join("<br>")],
    ]);
    const times = this.propCard(t("propTimes"), "mdi:clock-outline", [[t("propCreated"), this.propTime(item.created_at)], [t("propModified"), this.propTime(item.modified_at)]]);
    return info + assignment + entities + technical + times;
  }

  propertyCards(item) {
    if (item.object_type === "entity") return this.entityCards(item);
    if (item.object_type === "device") return this.deviceCards(item);
    if (item.object_type === "config_entry") return this.integrationCard(item);
    if (["automation", "script", "scene", "area"].includes(item.object_type)) return `<div class="propcol">${this.labelCard(item)}</div>`;
    return "";
  }
}

// MaintenanceMixin: recorder costs and the update preflight; mixed into the panel in 99-register.js.
class MaintenanceMixin {
  async loadCosts(refresh = false) {
    this.costsLoading = true; this.costsError = ""; this.render();
    try { this.costs = await this._hass.callWS({ type: "ha_housekeeper/recorder_costs", ...(refresh ? { refresh: true } : {}) }); this.markLoaded("costs"); } catch (err) { this.costs = null; this.costsError = this.errText(err); }
    this.costsLoading = false; this.render();
    this.followUp("costs", "recorder", this.costs, r => this.loadCosts(r), refresh);
  }

  // Opening the costs tab starts the analysis once; the backend answers with the last result at once.
  ensureCosts() {
    if (this.costsLoading || this._costsRequested) return;
    this._costsRequested = true;
    setTimeout(() => this.loadCosts(), 0);
  }

  async loadPreflight() {
    this.preflightLoading = true; this.preflightError = ""; this.render();
    try {
      this.preflight = await this._hass.callWS({ type: "ha_housekeeper/preflight" });
      this.markLoaded("preflight");
    } catch (err) { this.preflightError = this.errText(err); }
    this.preflightLoading = false; this.render();
  }

  formatBytes(bytes) {
    if (bytes === null || bytes === undefined) return this.t("recorderSizeUnknown");
    const units = ["B", "KB", "MB", "GB", "TB"];
    let value = bytes, i = 0;
    while (value >= 1024 && i < units.length - 1) { value /= 1024; i += 1; }
    return `${this.formatNumber(Math.round(value * 10) / 10)} ${units[i]}`;
  }

  suggestedExclusions() { return (this.costs?.entities || []).filter(e => e.suggest_exclude && !e.excluded).map(e => e.entity_id); }

  recorderCard() {
    this.ensureCosts();
    const c = this.costs;
    const bar = (extra = "", attr = "", exportId = "") => this.pageBar({ left: extra, at: this.isoOf(c?.computed_at) || this.loadedAt("costs"), loading: this.costsLoading, attr, refresh: Boolean(attr), exportId });
    const head = (extra = "", attr = "") => `${bar(extra, attr)}<div class="panel">`; // the states without a list: the card holds the message
    if (this.costsLoading) return `<div class="stack">${head("", "data-costs-load")}${this.skeleton("recorderLoading")}</div></div>`;
    if (this.costsError) return `<div class="stack">${head("", "data-costs-load")}<div class="error">${this.esc(this.costsError)}</div></div></div>`;
    if (!c) return `<div class="stack">${head(`<button class="btn primary" data-costs-load>${this.t("recorderLoad")}</button>`)}</div></div>`;
    if (c.busy) return `<div class="stack">${head("", "data-costs-load")}<p class="factnote">${this.t("relBusy")}</p></div></div>`;
    if (!c.available) return `<div class="stack">${head()}<div class="emptymsg"><ha-icon icon="mdi:database-off-outline"></ha-icon>${this.t("recorderUnavailable")}</div></div></div>`;
    const took = c.computed_at && (c.stale || c.age_seconds >= 60) ? this.tookNote(c) : c.took_ms === null || c.took_ms === undefined ? "" : ` · ${this.t(c.cached ? "recorderCached" : "recorderTook", { ms: this.formatNumber(c.took_ms) })}`;
    const summary = this.t("recorderSummary", { states: this.formatNumber(c.total_states), size: this.formatBytes(c.size_bytes), days: c.keep_days ?? "—", stats: this.formatNumber(c.statistics_total) }) + took;
    const all = c.entities || [], max = Math.max(...all.map(e => e.share), 0.1); // the bars are scaled to the largest entry
    const sug = e => e.suggest_exclude && !e.excluded;
    const num = v => this.esc(this.formatNumber(v ?? 0));
    const avg = e => e.per_day_avg ?? e.per_day ?? 0;
    const columns = [
      { key: "sel", label: "stormColSelect", sortable: false, narrow: true, allBox: rows => this.excludeAllBox(rows.map(e => e.entity_id)), cell: e => this.excludeBox(e.entity_id) },
      { key: "name", label: "utName", cell: e => this.nameCell(e.name, e.entity_id) },
      { key: "share", label: "recorderColShare", dir: "desc", cell: e => `<span class="costshare">${this.sysShare(e.share, max)}<span>${this.esc(this.formatNumber(e.share))} %</span></span>` },
      { key: "states", label: "recorderColTotal", dir: "desc", cell: e => num(e.states) },
      { key: "d1", label: "recorderCol24h", dir: "desc", cell: e => num(e.states_24h) },
      { key: "d7", label: "recorderCol7d", dir: "desc", cell: e => num(e.states_7d) },
      { key: "avg", label: "recorderColAvg", dir: "desc", cell: e => num(Math.round(avg(e))) },
      { key: "mark", label: "recorderColMark", sortable: false, cell: e => (e.excluded ? `<span class="pill ok">${this.t("recorderExcluded")}</span>` : sug(e) ? `<span class="pill warn">${this.t("recorderSuggest")}</span>` : `<span class="pill ${e.used ? "mute" : "blue"}">${e.used ? this.t("recorderUsed", { count: e.used }) : this.t("recorderUnused")}</span>`) },
    ];
    this.setPageExporter("reccost", "recorder-costs", `${this.t("recorder")} · ${this.t("recorderTitle")}`, [
      { name: "entities", title: this.t("recorderTitle"), header: [this.t("utName"), "ID", this.t("recorderColShare"), this.t("recorderColTotal"), this.t("recorderCol24h"), this.t("recorderCol7d"), this.t("recorderColAvg")], rows: () => all.map(e => [e.name, e.entity_id, e.share, e.states, e.states_24h ?? "", e.states_7d ?? "", Math.round(avg(e))]) },
      { name: "statistics", title: this.t("recorderStats"), header: [this.t("recorderColStat"), this.t("recorderColRows")], rows: () => (c.statistics || []).map(x => [x.statistic_id, x.rows ?? ""]) },
    ].filter(sec => sec.rows().length));
    const list = this.sysList("costlist", all, {
      sort: "d1", dir: "desc",
      sorts: [
        { key: "d1", label: "recorderCol24h", dir: "desc", get: e => e.states_24h ?? 0 },
        { key: "d7", label: "recorderCol7d", dir: "desc", get: e => e.states_7d ?? 0 },
        { key: "states", label: "recorderColTotal", dir: "desc", get: e => e.states },
        { key: "avg", label: "recorderColAvg", dir: "desc", get: avg },
        { key: "share", label: "recorderColShare", dir: "desc", get: e => e.share },
        { key: "name", label: "utName", dir: "asc", get: e => e.name },
      ],
      filters: [{ name: "state", all: this.t("recorderFilterAll"), options: [["suggest", this.t("recorderSumSuggest")], ["excluded", this.t("recorderSumExcluded")], ["unused", this.t("recorderSumUnused")]] }],
      filterFns: { state: (e, v) => (v === "suggest" ? sug(e) : v === "excluded" ? e.excluded : !e.used) },
      text: e => `${e.name} ${e.entity_id}`, tie: e => e.entity_id, empty: "recorderNone", columns,
      rowAttrs: e => `${this.findObject(`entity:${e.entity_id}`) ? `data-object="${this.esc(`entity:${e.entity_id}`)}" tabindex="0" role="button" aria-label="${this.esc(e.name)}" ` : ""}class="${[e.excluded ? "exdone" : "", sug(e) ? "exsug" : "", this.findObject(`entity:${e.entity_id}`) ? "" : "static"].filter(Boolean).join(" ")}"`,
    });
    const tiles = all.length ? this.sumTiles([
      { label: this.t("recorderSumAll"), value: this.formatNumber(all.length), tone: "mute", lf: ["costlist", "", ""] },
      { label: this.t("recorderSumSuggest"), value: this.formatNumber(all.filter(sug).length), tone: all.some(sug) ? "warn" : "ok", lf: ["costlist", "state", "suggest"] },
      { label: this.t("recorderSumExcluded"), value: this.formatNumber(all.filter(e => e.excluded).length), tone: "mute", lf: ["costlist", "state", "excluded"] },
      { label: this.t("recorderSumUnused"), value: this.formatNumber(all.filter(e => !e.used).length), tone: "mute", lf: ["costlist", "state", "unused"] },
    ]) : "";
    const stats = (c.statistics || []).length ? this.sysList("recorder_stats", c.statistics, {
      sort: "rows", dir: "desc", tie: x => x.statistic_id, empty: "recorderNone",
      sorts: [{ key: "rows", label: "recorderColRows", dir: "desc", get: x => x.rows ?? 0 }, { key: "id", label: "recorderColStat", dir: "asc", get: x => x.statistic_id }],
      text: x => x.statistic_id,
      rowAttrs: x => (this.findObject(`entity:${x.statistic_id}`) ? `data-object="${this.esc(`entity:${x.statistic_id}`)}" tabindex="0" role="button" aria-label="${this.esc(x.statistic_id)}"` : 'class="static"'),
      columns: [
        { key: "id", label: "recorderColStat", dir: "asc", cell: x => this.nameCell(x.statistic_id, "") },
        { key: "rows", label: "recorderColRows", dir: "desc", cell: x => this.esc(this.formatNumber(x.rows)) },
      ],
    }) : "";
    const snippet = this.excludeCard(this.suggestedExclusions(), { only: false });
    // The key figures stand free above the card of the list, with the usual gap.
    return `<div class="stack">${bar("", "data-costs-load data-refresh", "reccost")}${tiles}<div class="panel"><p class="factnote">${this.esc(summary)}</p>${snippet}${list}${stats ? this.fold("recorder_stats", { title: this.t("recorderStats"), pill: this.formatNumber((c.statistics || []).length) }, stats, false) : ""}</div></div>`;
  }

  // One line per check; `level` decides the colour.
  preflightRows(state, checks) {
    const detail = {
      backup: () => {
        const b = state.backup || {};
        if (!b.available) return this.t("pf_backup_unavailable");
        if (!b.configured || b.newest === null) return this.t("pf_backup_none");
        return this.t(b.age_hours > 48 ? "pf_backup_old" : "pf_backup_ok", { hours: Math.round(b.age_hours) });
      },
    };
    return checks.map(c => {
      const items = { repairs: state.repairs, failed_entries: state.failed_entries, broken: state.broken }[c.check];
      const names = (items || []).slice(0, 5).map(i => i.title || i.name || i.issue_id || i.object_id).filter(Boolean).map(n => this.esc(n)).join(", ");
      const text = c.check === "backup" ? detail.backup() : c.count ? `${c.count}${names ? ` · ${names}` : ""}` : this.t("pf_count_none");
      const tone = { ok: "ok", warn: "warn", red: "red" }[c.level] || "mute";
      const icon = c.level === "ok" ? "mdi:check" : c.level === "red" ? "mdi:close-octagon-outline" : "mdi:alert-outline";
      return `<div class="row rel"><span class="tile ${tone}"><ha-icon icon="${icon}"></ha-icon></span><span class="row-text"><strong>${this.t(`pf_${c.check}`)}</strong><small>${text}</small></span></div>`;
    }).join("");
  }

  // What follows an update: the watch (on, running, or off), with the way to its results.
  preflightAfter(watch) {
    if (!watch) return "";
    const active = watch.active;
    const text = !(watch.hours > 0) ? this.t("pfAfterOff")
      : active ? this.t("pfAfterRunning", { what: this.watchWhat(active), hours: Math.max(0, Math.ceil((Date.parse(active.until) - Date.now()) / 3600000)), n: this.formatNumber(active.new) })
      : this.t("pfAfterOn", { hours: watch.hours });
    const go = active ? ` <button class="btn" data-watch-go="${this.esc(active.id || "")}">${this.t("watchGo")}</button>` : "";
    return `<div class="panelhead topline"><div><h3>${this.t("pfAfterTitle")}</h3></div></div><p class="factnote">${text}${go}</p>`;
  }

  preflightCard() {
    const p = this.preflight;
    const head = this.pageBar({ at: this.loadedAt("preflight"), loading: this.preflightLoading, attr: "data-pf-refresh" });
    if (this.preflightError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.preflightError)}</div></div></div>`;
    if (!p) return `<div class="stack">${head}<div class="panel">${this.skeleton("preflightLoading")}</div></div>`;
    const updates = p.state.pending_updates || [];
    const updateRow = `<div class="row rel"><span class="tile ${updates.length ? "warn" : "ok"}"><ha-icon icon="mdi:package-up"></ha-icon></span><span class="row-text"><strong>${this.t("pf_updates")}</strong><small>${updates.length ? updates.slice(0, 6).map(u => `${this.esc(u.name)} ${this.esc(u.installed ?? "")} → ${this.esc(u.latest ?? "")}`).join(" · ") : this.t("pf_updates_none")}</small></span></div>`;
    return `<div class="stack">${head}<div class="panel">${this.preflightRows(p.state, p.checks)}${updateRow}${this.preflightAfter(p.watch)}</div></div>`;
  }

  maintenanceView() {
    if (!this.preflight && !this.preflightLoading && !this._pfRequested) { this._pfRequested = true; setTimeout(() => this.loadPreflight(), 0); }
    this.ensureBackup();
    const checks = this.backup?.available ? this.backup.checks || [] : [];
    const problems = checks.filter(c => c.level === "problem").length, notes = checks.filter(c => c.level === "note").length;
    const pf = this.preflight, pfChecks = pf?.checks || [];
    const pfRed = pfChecks.filter(c => c.level === "red").length, pfWarn = pfChecks.filter(c => c.level === "warn").length;
    const updates = pf?.state?.pending_updates?.length || 0;
    const backupTone = !this.backup?.available ? "mute" : problems ? "red" : notes ? "warn" : "ok";
    const pfTone = !pf ? "mute" : pfRed ? "red" : pfWarn ? "warn" : "ok";
    const goalsMissed = (this.goals?.goals || []).filter(g => g.state === "missed").length;
    this.ensureGoals();
    const bp = this.blueprints, bpBad = bp ? (bp.missing || 0) + (bp.broken || 0) : 0;
    const tabs = [
      { id: "backup", icon: "mdi:backup-restore", label: this.t("backupTitle"), hint: "maintHintBackup", pill: !this.backup?.available ? "" : problems ? this.t("mtProblems", { n: problems }) : notes ? this.t("mtNotes", { n: notes }) : this.t("bhLevel_ok"), tone: backupTone },
      { id: "backups", icon: "mdi:delete-sweep-outline", label: this.t("bkcTab"), hint: "maintHintBkc", pill: this.bkc?.available && this.bkc.rows?.length ? this.formatNumber(this.bkc.rows.length) : "", tone: "mute" },
      { id: "preflight", icon: "mdi:rocket-launch-outline", label: this.t("preflightTitle"), hint: "maintHintPreflight", pill: !pf ? "" : pfRed || pfWarn ? this.t("mtOpen", { n: pfRed + pfWarn }) : this.t("bhLevel_ok"), tone: pfTone },
      { id: "blueprints", icon: "mdi:file-code-outline", label: this.t("bpTab"), hint: "maintHintBlueprints", pill: bpBad ? this.t("mtOpen", { n: bpBad }) : "", tone: "warn" },
      { id: "devices", icon: "mdi:devices", label: this.t("lifeRemovedTab"), hint: "maintHintDevices", pill: this.removed?.length ? this.formatNumber(this.removed.length) : "", tone: "mute" },
      { id: "goals", icon: "mdi:target", label: this.t("goalsTitle"), hint: "maintHintGoals", pill: goalsMissed ? this.t("tilesMissed", { count: goalsMissed }) : "", tone: "red" },
    ];
    this.ensureBackupCleanup();
    const open = this.viewTabOf("maintenance", tabs, "backup");
    const grid = this.navTiles("maintenance", tabs.map(tab => ({ ...tab, hint: this.t(tab.hint), tone: tab.pill ? tab.tone : "ok" })), open, this.t("maintenance"), true);
    return `<div class="stack">${grid}${open === "goals" ? this.goalsCard() : open === "preflight" ? this.preflightCard() : open === "devices" ? this.removedCard() : open === "blueprints" ? this.blueprintsCard() : open === "backups" ? this.backupCleanupCard() : this.backupCard()}</div>`;
  }
}

// BackupMixin: the backup protection card in Maintenance; mixed into the panel in 99-register.js.
class BackupMixin {
  // `call` is the attest command or nothing (just read). Every reply is the full report.
  async loadBackup(call) {
    if (call) this.bhForm = null;
    this.backupLoading = true; this.backupError = ""; this.render();
    try { this.backup = await this._hass.callWS(call || { type: "ha_housekeeper/backup_health" }); this.markLoaded("backup"); }
    catch (err) { this.backupError = this.errText(err); }
    this.backupLoading = false; this.render();
  }

  // Loads once, and again after every new scan, so the overview and Maintenance never show an old report.
  ensureBackup() {
    const key = this.data?.meta?.scanned_at || "";
    if (this.backupLoading || (this._bhKey === key && this._bhRequested)) return;
    this._bhRequested = true; this._bhKey = key;
    setTimeout(() => this.loadBackup(), 0);
  }

  bhAge(hours) { return hours >= 48 ? this.t("bhAgeDays", { n: Math.round(hours / 24) }) : this.t("bhAgeHours", { n: Math.max(1, Math.round(hours)) }); }

  bhDay(iso) {
    if (!iso) return "—";
    try { return new Intl.DateTimeFormat(this.lang, { dateStyle: "medium", timeZone: "UTC" }).format(new Date(iso)); } catch (_) { return iso; }
  }

  bhList(items) { return items?.length ? items.map(i => this.esc(i)).join(", ") : this.t("bhNone"); }

  // The sentence for one check; the backend sends numbers and ids only.
  bhText(c) {
    const v = c.values || {}, t = (k, vars) => this.t(k, vars);
    switch (c.id) {
      case "setup":
        if (c.level === "problem") return t("bhSetupProblem");
        if (c.level === "note") return t("bhSetupNote");
        return t("bhSetupOk", { agents: this.bhList(v.agents), recurrence: t(`bhRec_${v.recurrence}`) });
      case "newest":
        return v.age_hours === null || v.age_hours === undefined ? t("bhNewestNone") : t("bhNewestText", { age: this.bhAge(v.age_hours), limit: this.bhAge(v.limit_hours) });
      case "last_run": {
        if (c.level === "unknown") return t("bhRunUnknown");
        const parts = [];
        if (v.failed_attempt) parts.push(t("bhRunFailed", { attempted: this.formatDate(v.attempted), completed: v.completed ? this.formatDate(v.completed) : t("bhNever") }));
        if (v.failed_agents?.length) parts.push(t("bhRunAgents", { agents: this.bhList(v.failed_agents) }));
        return parts.length ? parts.join(" ") : t("bhRunOk", { completed: this.formatDate(v.completed) });
      }
      case "targets":
        if (v.at && !v.remote?.length) return t("bhTargetsConfirmed", { local: this.bhList(v.local), date: this.bhDay(v.at) });
        if (v.at) return t("bhTargetsOkConfirmed", { local: this.bhList(v.local), remote: this.bhList(v.remote), date: this.bhDay(v.at) });
        return c.level === "ok" ? t("bhTargetsOk", { local: this.bhList(v.local), remote: this.bhList(v.remote) }) : c.level === "note" ? t("bhTargetsNote", { local: this.bhList(v.local) }) : "";
      case "size":
        if (c.level === "unknown") return t("bhSizeUnknown");
        return t(c.level === "ok" ? "bhSizeOk" : "bhSizeNote", { size: this.formatBytes(v.size), expected: this.formatBytes(v.expected), percent: Math.round(v.ratio * 100) });
      case "retention": {
        if (c.level === "note") return t("bhRetentionNote", { count: v.count });
        const limit = [v.copies !== null && v.copies !== undefined ? t("bhRetCopies", { n: v.copies }) : "", v.days !== null && v.days !== undefined ? t("bhRetDays", { n: v.days }) : ""].filter(Boolean).join(" · ");
        return t("bhRetentionOk", { limit, count: v.count, oldest: v.oldest_days === null ? "—" : Math.round(v.oldest_days) });
      }
      case "encryption":
        if (c.level === "ok") return t("bhEncOk");
        return t(v.configured ? "bhEncNotProtected" : "bhEncNoPassword");
      case "emergency_kit":
        return v.at ? t("bhKitOk", { date: this.bhDay(v.at) }) : t("bhKitNone");
      case "restore_test":
        if (!v.at) return t("bhRestoreNone");
        return t(c.level === "ok" ? "bhRestoreOk" : "bhRestoreOld", { date: this.bhDay(v.at), days: v.age_days, limit: 180 });
      case "own_backups":
        return t("bhOwnNote", { count: v.count, size: this.formatBytes(v.size) });
      case "plan_backups":
        return c.level === "ok" ? t("bhPlansOk", v) : t("bhPlansNote", v);
      default:
        return "";
    }
  }

  bhRow(c) {
    const tone = { ok: "ok", note: "warn", problem: "red", unknown: "mute" }[c.level] || "mute";
    const icon = { ok: "mdi:check", note: "mdi:alert-outline", problem: "mdi:close-octagon-outline", unknown: "mdi:help-circle-outline" }[c.level] || "mdi:help-circle-outline";
    const attest = c.id === "targets" || c.id === "emergency_kit" || c.id === "restore_test";
    const open = attest && c.level !== "unknown" && this.bhForm === c.id;
    const opener = attest && c.level !== "unknown" ? `<button class="bhopen" data-bh-open="${c.id}" aria-expanded="${open}">${this.t(c.values?.at ? "bhAttestAgain" : c.id === "targets" ? "bhAttestTargets" : "bhAttestMark")}</button>` : "";
    const row = `<div class="row rel bh${open ? " open" : ""}"><span class="tile ${tone}"><ha-icon icon="${icon}"></ha-icon></span><span class="row-text"><strong>${this.t(`bh_${c.id}`)}</strong><small>${this.bhText(c)}</small></span><span class="bhactions">${opener}<span class="pill ${tone}">${this.t(`bhLevel_${c.level}`)}</span></span></div>`;
    if (!open) return row;
    const today = new Date().toISOString().slice(0, 10);
    const clear = c.values?.at ? `<button class="bhtake" data-bh-clear="${c.id}">${this.t("bhAttestClear")}</button>` : "";
    return `${row}<div class="bhattest"><label>${this.t("bhAttestDate")} <input type="date" data-bh-date="${c.id}" value="${today}" max="${today}"></label><button class="btn small primary" data-bh-save="${c.id}">${this.t("bhAttestSave")}</button><button class="bhcancel" data-bh-cancel>${this.t("bhAttestCancel")}</button>${clear}</div>`;
  }

  // What a backup is: Housekeeper's own safety copy, one HA made on its schedule, or a manual one.
  bhKind(b) { return b.own ? "own" : b.automatic ? "auto" : "manual"; }

  bhKey(b) { return b.id || b.date || ""; }

  bhContent(b) { return b.partial ? "config" : b.ha_included === false ? "apps" : "full"; }

  bhFailed(b) { return [...(b.failed_agents || []), ...(b.failed_apps || []), ...(b.failed_folders || [])]; }

  // The row under an open backup: name, version, what it holds, size per target, failures.
  bhDetail(b) {
    if (!(this.bhOpen || []).includes(this.bhKey(b))) return "";
    const t = (k, v) => this.t(k, v), field = (label, value, cls = "") => `<div${cls ? ` class="${cls}"` : ""}><small>${t(label)}</small>${value}</div>`;
    const dash = "–", list = items => (items?.length ? items.map(i => this.esc(i)).join(", ") : dash);
    const sizes = Object.entries(b.agent_sizes || {}).map(([agent, size]) => `${this.esc(agent)} ${this.esc(this.formatBytes(size))}`).join(" · ") || dash;
    const db = b.database === null || b.database === undefined ? dash : t(b.database ? "bhYes" : "bhNo");
    return `<tr class="static remhist"><td colspan="6"><div class="bhgrid">${field("bhName", this.esc(b.name || dash))}${field("bhVersion", this.esc(b.version || dash))}${field("bhDatabase", db)}${field("bhApps", list(b.apps), "wide")}${field("bhFolders", list(b.folders))}${field("bhSizes", sizes)}${field("bhFailed", list(this.bhFailed(b)))}${field("bhId", this.esc(b.id || dash))}</div></td></tr>`;
  }

  bhBackups(list) {
    if (!list?.length) return "";
    const id = "bhbackups";
    this.lvState(id, "date", "desc");
    const sorts = [
      { key: "date", label: "bhColDate", dir: "desc", get: b => b.date },
      { key: "size", label: "bhColSize", dir: "desc", get: b => b.size },
      { key: "protected", label: "bhColProtected", dir: "desc", get: b => (b.protected ? 1 : 0) },
    ];
    const bar = this.listBar(id, { table: true, dense: true, sorts, filters: [
      { name: "kind", all: this.t("bhAllKinds"), options: ["auto", "manual", "own"].map(k => [k, this.t(`bhKind_${k}`)]) },
      { name: "protected", all: this.t("bhAllProtected"), options: [["yes", this.t("bhYes")], ["no", this.t("bhNo")]] },
    ] });
    const rows = this.refine(id, list, { text: b => [this.formatDate(b.date), b.name, ...(b.agents || [])].join(" "), filters: { kind: (b, v) => this.bhKind(b) === v, protected: (b, v) => Boolean(b.protected) === (v === "yes") }, sorts, tie: b => b.date });
    const pg = this.paginate(id, rows, [10, 20]);
    const open = b => (this.bhOpen || []).includes(this.bhKey(b));
    const columns = [
      { key: "date", label: "bhColDate", dir: "desc", cell: b => `<div class="statcell">${this.expandBtn("data-bh-more", this.bhKey(b), open(b), this.t(open(b) ? "bhClose" : "bhOpen"))}<div>${this.esc(this.formatDate(b.date))}</div></div>` },
      { key: "kind", label: "bhColKind", sortable: false, cell: b => `<span class="pill ${b.own ? "warn" : "mute"}">${this.t(`bhKind_${this.bhKind(b)}`)}</span>` },
      { key: "content", label: "bhColContent", sortable: false, cell: b => `<span class="pill ${this.bhContent(b) === "full" ? "ok" : "mute"}">${this.t(`bhContent_${this.bhContent(b)}`)}</span>${this.bhFailed(b).length ? `<span class="pill red bhfail">${this.t("bhFailedPill")}</span>` : ""}` },
      { key: "size", label: "bhColSize", dir: "desc", cell: b => this.esc(this.formatBytes(b.size)) },
      { key: "targets", label: "bhColTargets", sortable: false, cell: b => this.bhList(b.agents) },
      { key: "protected", label: "bhColProtected", dir: "desc", cell: b => this.t(b.protected ? "bhYes" : "bhNo") },
    ];
    const table = rows.length ? this.listTable(id, columns, pg.rows, { cls: "bh", rowAttrs: b => `data-bh-row="${this.esc(this.bhKey(b))}" tabindex="0" role="button" aria-expanded="${open(b)}"`, after: b => this.bhDetail(b) }) : `<div class="emptymsg">${this.noMatches(id)}</div>`;
    return `<div class="panel"><div class="sectionlabel">${this.t("bhListTitle")}</div>${bar}${table}${pg.footer}</div>`;
  }

  backupCard() {
    const head = this.pageBar({ at: this.loadedAt("backup"), loading: this.backupLoading, attr: "data-bh-refresh" });
    if (this.backupError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.backupError)}</div></div></div>`;
    const b = this.backup;
    if (!b) return `<div class="stack">${head}<div class="panel">${this.skeleton("backupLoading")}</div></div>`;
    if (!b.available) return `<div class="stack">${head}<div class="panel"><div class="emptymsg">${this.t("backupUnavailable")}</div></div></div>`;
    const guide = `<details class="bhguide"><summary>${this.t("bhGuideTitle")}</summary><p class="factnote">${this.t("bhGuideSteps")}</p></details>`;
    return `<div class="stack">${head}<div class="panel">${b.checks.map(c => this.bhRow(c)).join("")}${guide}</div>${this.bhBackups(b.backups)}</div>`;
  }
}

// ReliabilityMixin: the reliability view; mixed into the panel in 99-register.js.
class ReliabilityMixin {
  // Slow recorder views: an old reply is shown at once and renewed once; when another calculation holds the
  // query lock, the panel asks again by itself a few times instead of asking the user to click.
  followUp(name, view, result, reload, refresh) {
    if (!result) return;
    if (!refresh && result.stale) { reload(true); return; }
    this._busyTries = this._busyTries || {};
    if (!result.busy) { this._busyTries[name] = 0; return; }
    this._busyTries[name] = (this._busyTries[name] || 0) + 1;
    if (this._busyTries[name] <= BUSY_RETRIES) setTimeout(() => { if (this.view === view) reload(refresh); }, BUSY_WAIT_MS);
  }

  // " · calculated in 2.8 s", or the age of an old reply.
  tookNote(r) {
    if (!r || !r.available) return "";
    if (r.computed_at && (r.stale || r.age_seconds >= 60)) return ` · ${this.t("relAgeNote", { when: this.relTime(new Date(r.computed_at * 1000).toISOString()) })}`;
    if (r.took_ms === null || r.took_ms === undefined) return "";
    return ` · ${this.t(r.cached ? "relCached" : "relTook", { s: this.formatNumber(Math.round(r.took_ms / 100) / 10) })}`;
  }

  async loadReliability(refresh = false) {
    this.relLoading = true; this.relError = ""; this.render();
    try { this.reliability = await this._hass.callWS({ type: "ha_housekeeper/reliability", window_days: this.relWindow, refresh, ...(this.relCompare ? { compare: true } : {}) }); }
    catch (err) { this.relError = this.errText(err); }
    this.relLoading = false; this.render();
    this.followUp("reliability", "reliability", this.reliability, r => this.loadReliability(r), refresh);
  }

  // The first visit and every change of the window load once; the backend keeps the result for a few minutes.
  ensureReliability() {
    if (this.relLoading || this._relRequested === this.relWindow) return;
    this._relRequested = this.relWindow;
    setTimeout(() => this.loadReliability(), 0);
  }

  relDuration(seconds) {
    if (seconds >= 86400) return this.t("relDays", { n: Math.round(seconds / 86400) });
    if (seconds >= 7200) return this.t("relHours", { n: Math.round(seconds / 3600) });
    return this.t("relMinutes", { n: Math.max(1, Math.round(seconds / 60)) });
  }

  relSorts() {
    return [
      { key: "avail", label: "relSortAvail", dir: "asc", get: e => e.availability },
      { key: "title", label: "sortName", dir: "asc", get: e => e.title },
      { key: "outages", label: "relSortOutages", dir: "desc", get: e => e.shared_outages },
    ];
  }

  relRowBody(item) {
    const percent = item.availability;
    const tone = percent === null ? "mute" : percent >= 99.5 ? "ok" : percent >= 95 ? "warn" : "red";
    const lines = [`${this.esc(item.domain || "")} · ${this.t("relEntities", { n: item.entities })}${item.permanent ? ` · ${this.t("relPermanent", { n: item.permanent })}` : ""}`];
    if (item.shared_outages) {
      const layer = item.layer === "cloud" ? this.t("relLayerCloud") : this.t("relLayerLocal");
      lines.push(`${this.t(item.shared_outages === 1 ? "relSharedOne" : "relShared", { n: item.shared_outages, longest: this.relDuration(item.longest_outage) })} · ${layer}`);
    }
    const flags = [];
    if (item.reauth) flags.push(`<span class="pill red">${this.t("relReauth")}</span>`);
    if (item.state && item.state !== "loaded") flags.push(`<span class="pill warn">${this.esc(item.state)}</span>`);
    if (item.setup) lines.push(`${item.setup.count ? this.t("relSetup", { n: item.setup.count, days: item.setup.days, last: this.formatDate(item.setup.last) }) : ""}${item.setup.state ? `${item.setup.count ? " · " : ""}${this.t("relSetupNow", { state: item.setup.state })}` : ""}`);
    lines.push(item.last_disruption
      ? this.t(item.last_disruption.shared ? "relLastShared" : "relLastSingle", { date: this.formatDate(new Date(item.last_disruption.end * 1000).toISOString()), duration: this.relDuration(item.last_disruption.seconds) })
      : this.t("relNoDisruption"));
    if (item.delta !== null && item.delta !== undefined) lines.push(this.t("relDelta", { delta: `${item.delta > 0 ? "+" : item.delta < 0 ? "−" : "±"}${this.formatNumber(Math.abs(item.delta))}`, before: this.formatNumber(item.previous_availability) }));
    else if (this.reliability?.comparison?.available) lines.push(this.t("relDeltaNone"));
    return `<span class="tile ${tone}"><ha-icon icon="mdi:lan-connect"></ha-icon></span><span class="row-text"><strong>${this.esc(item.title)}</strong>${lines.map(line => `<small>${line}</small>`).join("")}${flags.length ? `<span class="relflags">${flags.join(" ")}</span>` : ""}</span><span class="pill ${tone}">${percent === null ? "—" : `${this.formatNumber(percent)} %`}</span>`;
  }

  // The row of one config entry in the loaded numbers, for its detail page.
  reliabilityRow(item) {
    if (item.object_type !== "config_entry") return null;
    return (this.reliability?.entries || []).find(row => row.entry_id === item.object_id) || null;
  }

  reliabilityDetailCard(row) {
    const r = this.reliability;
    const items = row.affected || [];
    const list = this.objectTable(`relaffected-${row.entry_id || row.domain || ""}`, items.map(m => {
      const tone = m.availability >= 99.5 ? "ok" : m.availability >= 95 ? "warn" : "red";
      return { key: `entity:${m.entity_id}`, type: "entity", name: m.name, sub: m.entity_id, tone, state: tone, stateLabel: this.t({ ok: "relAvailOk", warn: "relAvailWarn", red: "relAvailRed" }[tone]), avail: m.availability, pill: `<span class="pill ${tone}">${this.formatNumber(m.availability)} %</span>`, rank: m.availability };
    }), { extras: [{ key: "avail", label: "relColAvail", get: r => r.avail, cell: r => `${this.formatNumber(r.avail)} %` }], empty: "" });
    const more = row.affected_total > items.length ? `<p class="factnote">${this.t("relAffectedMore", { shown: items.length, total: row.affected_total })}</p>` : "";
    const hintKey = this.relSetupHint(row);
    const hint = hintKey ? `<div class="factnote"><strong>${this.t("relHintTitle")}</strong> ${this.t(hintKey, { n: row.setup.count, days: row.setup.days })}</div>` : "";
    const summary = `<div class="row">${this.relRowBody(row)}</div>${hint}`;
    return `<section class="panel"><div class="panelhead"><div><h2>${this.t("relTab")}</h2><p>${this.t(r.window_days === 1 ? "relWindow1" : "relWindow7")}${r.stale || r.age_seconds ? ` · ${this.t("relAgeNote", { when: this.relTime(new Date(r.computed_at * 1000).toISOString()) })}` : ""}</p></div></div>${summary}<div class="sectionlabel">${this.t("relAffected", { n: this.formatNumber(row.affected_total || 0) })}</div>${list || `<p class="factnote">${this.t("relNoAffected")}</p>`}${more}</section>`;
  }

  // A guess at the cause from the setup failures and the availability, worded as a possibility.
  relSetupHint(row) {
    const setup = row.setup;
    if (!setup) return null;
    if (setup.state === "failed_unload" || setup.state === "migration_error") return "relHintUnload";
    if (setup.state === "setup_error") return "relHintError";
    if (setup.count >= 2 && row.availability !== null && row.availability !== undefined && row.availability < 95) return "relHintOffline";
    return setup.count >= 2 ? "relHintEarly" : null;
  }

  relEntryState(e) { return e.reauth ? "reauth" : e.state && e.state !== "loaded" ? "notloaded" : ""; }

  // One row per integration entry: the numbers sit in columns so the list sorts by them; the sentences live on the detail page.
  relSetupCell(setup) {
    if (!setup) return "–";
    const now = setup.state ? `<small>${this.t("relSetupNow", { state: this.esc(setup.state) })}</small>` : "";
    const last = setup.last ? `<small>${this.t("relSetupLast", { date: this.formatDate(setup.last) })}</small>` : "";
    return `${setup.count ? this.t("relSetupCount", { n: setup.count, days: setup.days }) : ""}${last}${now}`;
  }

  relEntriesList(r) {
    const tone = p => (p === null || p === undefined ? "mute" : p >= 99.5 ? "ok" : p >= 95 ? "warn" : "red");
    const num = v => (v === null || v === undefined ? "–" : this.esc(this.formatNumber(v)));
    const compare = Boolean(r.comparison?.available);
    const delta = e => (e.delta === null || e.delta === undefined ? null : e.delta);
    const columns = [
      { key: "title", label: "utName", cell: e => this.nameCell(e.title, `${e.domain || ""} · ${this.t("relEntities", { n: e.entities })}`) },
      { key: "status", label: "relColStatus", sortable: false, cell: e => [e.reauth ? `<span class="pill red">${this.t("relReauth")}</span>` : "", e.state && e.state !== "loaded" ? `<span class="pill warn">${this.esc(e.state)}</span>` : "", e.shared_outages && e.layer === "cloud" ? `<span class="pill mute">${this.t("relLayerCloud")}</span>` : ""].filter(Boolean).join(" ") },
      { key: "setup", label: "relColSetup", dir: "desc", cell: e => this.relSetupCell(e.setup) },
      { key: "avail", label: "relSortAvail", dir: "asc", cell: e => (e.availability === null || e.availability === undefined ? "–" : `<span class="pill ${tone(e.availability)}">${this.esc(this.formatNumber(e.availability))} %</span>`) },
      { key: "outages", label: "relSortOutages", dir: "desc", cell: e => num(e.shared_outages) },
      { key: "longest", label: "relColLongest", dir: "desc", cell: e => (e.shared_outages ? this.esc(this.relDuration(e.longest_outage)) : "–") },
      { key: "last", label: "relColLast", dir: "desc", cell: e => (e.last_disruption ? this.esc(`${this.formatDate(new Date(e.last_disruption.end * 1000).toISOString())}, ${this.relDuration(e.last_disruption.seconds)}`) : this.esc(this.t("relNoDisruption"))) },
      ...(compare ? [{ key: "delta", label: "relColDelta", dir: "asc", cell: e => (delta(e) === null ? "–" : this.esc(`${delta(e) > 0 ? "+" : delta(e) < 0 ? "−" : "±"}${this.formatNumber(Math.abs(delta(e)))}`)) }] : []),
    ];
    return this.sysList("relentries", r.entries, {
      sort: "avail", dir: "asc",
      sorts: [
        ...this.relSorts(),
        { key: "setup", label: "relColSetup", dir: "desc", get: e => e.setup?.count ?? 0 },
        { key: "longest", label: "relColLongest", dir: "desc", get: e => e.longest_outage ?? null },
        { key: "last", label: "relColLast", dir: "desc", get: e => e.last_disruption?.end ?? null },
        ...(compare ? [{ key: "delta", label: "relColDelta", dir: "asc", get: delta }] : []),
      ],
      filters: [{ name: "state", all: this.t("relAllStates"), options: [["outages", this.t("relOnlyOutages")], ["reauth", this.t("relOnlyReauth")], ["notloaded", this.t("relOnlyNotLoaded")], ["setup", this.t("relOnlySetup")]] }],
      filterFns: { state: (e, v) => (v === "outages" ? e.shared_outages > 0 : v === "setup" ? Boolean(e.setup) : this.relEntryState(e) === v) },
      text: e => [e.title, e.domain].join(" "), tie: e => e.title, empty: "relEmpty", columns,
      rowAttrs: e => (this.findObject(`config_entry:${e.entry_id}`) ? `data-object="${this.esc(`config_entry:${e.entry_id}`)}" tabindex="0" role="button" aria-label="${this.esc(e.title)}"` : 'class="static"'),
      exportName: "reliability", header: [this.t("utName"), "Domain", this.t("relSortAvail"), this.t("relSortOutages"), this.t("relColLongest")], rows: e => [e.title, e.domain, e.availability ?? "", e.shared_outages ?? 0, e.longest_outage ?? ""],
    });
  }

  reliabilityView() {
    this.ensureReliability();
    const r = this.reliability;
    const windows = [[1, "relWindow1"], [7, "relWindow7"]].map(([days, key]) => `<button class="chip ${this.relWindow === days ? "active" : ""}" data-rel-window="${days}" aria-pressed="${this.relWindow === days}">${this.t(key)}</button>`).join("") + `<button class="chip ${this.relCompare ? "active" : ""}" data-rel-compare aria-pressed="${this.relCompare}">${this.t("relCompare")}</button>`;
    const aged = Boolean(r?.computed_at && (r.stale || r.age_seconds >= 60)), took = aged ? "" : this.tookNote(r).replace(/^ · /, "");
    const head = this.pageBar({ left: `${windows}${took ? `<span>${this.esc(took)}</span>` : ""}`, at: r?.computed_at ? new Date(r.computed_at * 1000).toISOString() : null, loading: this.relLoading, attr: "data-rel-refresh" });
    const alone = inner => `<div class="stack">${head}<div class="panel">${inner}</div></div>`;
    if (this.relError) return alone(`<div class="error">${this.esc(this.relError)}</div>`);
    if (!r) return alone(this.skeleton("relLoading"));
    if (!r.available) return alone(`<p class="factnote">${this.t("relNoRecorder")}</p>`);
    if (r.busy) return alone(`${this.skeleton("relBusy")}<p class="factnote">${this.t("relBusy")}</p>`);
    if (!r.entries.length) return alone(`<div class="emptymsg">${this.t("relEmpty")}</div>`);
    const loading = this.relLoading ? `<p class="factnote">${this.t("relLoading")}</p>` : "";
    const th = r.thresholds || {};
    const cov = r.coverage;
    const coverage = cov && cov.observed_share !== null && cov.observed_share !== undefined ? this.coverageNote(this.t("relCoverage", { days: r.window_days, withData: this.formatNumber(cov.with_data), known: this.formatNumber(cov.known), share: cov.observed_share })) : "";
    const list = this.relEntriesList(r);
    const u = r.unstable || { total: 0, entities: {} };
    const flapping = Object.values(u.entities || {}).filter(e => e.level === "flapping").length;
    const outages = r.entries.filter(e => e.shared_outages > 0).length;
    const attention = r.entries.filter(e => e.reauth || (e.state && e.state !== "loaded")).length;
    const counted = r.entries.reduce((n, e) => n + (e.availability === null || e.availability === undefined ? 0 : e.entities), 0);
    const overall = counted ? r.entries.reduce((n, e) => n + (e.availability === null || e.availability === undefined ? 0 : e.availability * e.entities), 0) / counted : null;
    const availText = overall === null ? "–" : `${this.formatNumber(Math.round(overall * 10) / 10)} %`;
    const odd = r.entries.filter(e => e.shared_outages > 0 || e.reauth || (e.state && e.state !== "loaded") || e.setup).length;
    const setupCount = r.entries.filter(e => e.setup).length;
    const tiles = this.sumTiles([
      { label: this.t("relSumAll"), value: this.formatNumber(r.entries.length), tone: "mute", lf: ["relentries", "", ""] },
      { label: this.t("relOnlyOutages"), value: this.formatNumber(outages), tone: outages ? "warn" : "ok", lf: ["relentries", "state", "outages"] },
      { label: this.t("relOnlyReauth"), value: this.formatNumber(r.entries.filter(e => e.reauth).length), tone: r.entries.some(e => e.reauth) ? "red" : "ok", lf: ["relentries", "state", "reauth"] },
      { label: this.t("relOnlyNotLoaded"), value: this.formatNumber(r.entries.filter(e => e.state && e.state !== "loaded").length), tone: r.entries.some(e => e.state && e.state !== "loaded") ? "warn" : "ok", lf: ["relentries", "state", "notloaded"] },
      { label: this.t("relOnlySetup"), value: this.formatNumber(setupCount), tone: setupCount ? "warn" : "ok", lf: ["relentries", "state", "setup"] },
    ]);
    const tabs = [
      { id: "integrations", icon: "mdi:puzzle-outline", label: this.t("relTabIntegrations"), hint: this.t("relTileIntHint", { avail: availText, window: this.t(r.window_days === 1 ? "relWindow1" : "relWindow7") }), count: r.entries.length, tone: outages || attention ? "warn" : "ok", pill: odd ? this.t("relTilePill", { n: this.formatNumber(odd) }) : "", pillTone: attention ? "red" : "warn" },
      { id: "unstable", icon: "mdi:pulse", label: this.t("relTabUnstable"), hint: this.t("relTileUnstableHint"), count: u.total || 0, tone: flapping ? "red" : u.total ? "warn" : "ok", pill: flapping ? this.t("relSumFlapping", { n: this.formatNumber(flapping) }) : "" },
    ];
    const open = this.viewTabOf("reliability", tabs, u.total && !outages ? "unstable" : "integrations");
    const body = open === "unstable" ? this.unstableCard(r) : `<div class="panel">${coverage}${loading}${list}${this.howCounted("relFootnote", { days: r.window_days, share: th.shared_share_percent ?? 80, entities: th.shared_min_entities ?? 3, minutes: Math.round((th.shared_min_seconds ?? 300) / 60) })}</div>`;
    return `<div class="stack">${head}${this.navTiles("reliability", tabs, open, this.t("reliability"), true)}${open === "integrations" ? tiles : ""}${body}</div>`;
  }

  // The numbers behind "unstable" or "flapping" as lines of text; also used on the entity's detail page.
  unstableLines(item, days) {
    const lines = [this.t("relEpisodes", { n: item.episodes, days, rate: this.formatNumber(item.per_day), total: this.relDuration(item.total_seconds), mean: this.relDuration(item.mean_seconds) })];
    if (item.pattern_hour !== null && item.pattern_hour !== undefined) lines.push(this.t("relPattern", { from: String(item.pattern_hour).padStart(2, "0"), to: String((item.pattern_hour + 2) % 24).padStart(2, "0") }));
    if (item.used) lines.push(this.t("relFollowers", { n: item.used }));
    return lines;
  }

  // The stability of an entity for its detail page, from numbers that already exist: it never starts the recorder query.
  ensureStability() {
    if (this._stabRequested === this.relWindow || this.reliability?.available) return;
    this._stabRequested = this.relWindow;
    setTimeout(async () => {
      try { this.stability = await this._hass.callWS({ type: "ha_housekeeper/reliability", window_days: this.relWindow, cached_only: true }); } catch (_) { return; }
      if (this.selected?.object_type === "entity" || this.view === "findingsNav") this.render();
    }, 0);
  }

  // null: unknown; { missing }: never calculated; { info: null }: calculated, stable; { info }: unstable or flapping.
  stabilityOf(item) {
    const r = this.reliability?.available && !this.reliability.busy ? this.reliability : this.stability;
    if (!r || !r.available) return null;
    if (r.missing) return { missing: true };
    const map = r.unstable?.entities;
    if (!map) return null; // a reply kept by an older version
    return { r, info: map[item.object_id] || null };
  }

  unstableCard(r) {
    const u = r.unstable, th = r.thresholds || {};
    if (!u) return "";
    const head = `${r.coverage ? this.coverageNote(this.t("relUnstableCoverage", { days: r.window_days, withData: this.formatNumber(r.coverage.with_data) }) + ` ${this.excludedText(u.excluded)}`.trimEnd()) : ""}`;
    if (!u.items.length) return `<div class="panel">${head}<div class="emptymsg">${this.t("relUnstableNone")}</div></div>`;
    const more = u.total > u.items.length ? `<p class="factnote">${this.t("relUnstableMore", { shown: u.items.length, total: u.total })}</p>` : "";
    const rank = new Map(u.items.map((item, i) => [item, i]));
    const sorts = [
      { key: "rank", label: "relSortRank", dir: "asc", get: item => rank.get(item) },
      { key: "name", label: "sortName", dir: "asc", get: item => item.name },
      { key: "episodes", label: "relSortEpisodes", dir: "desc", get: item => item.episodes },
      { key: "rate", label: "relSortRate", dir: "desc", get: item => item.per_day },
      { key: "duration", label: "relSortDuration", dir: "desc", get: item => item.total_seconds },
    ];
    const tone = item => (item.level === "flapping" ? "red" : "warn");
    const pattern = item => (item.pattern_hour === null || item.pattern_hour === undefined ? null : `${String(item.pattern_hour).padStart(2, "0")}–${String((item.pattern_hour + 2) % 24).padStart(2, "0")}`);
    const list = this.sysList("relunstable", u.items, {
      sort: "rank", dir: "asc",
      sorts: [...sorts, { key: "pattern", label: "relColPattern", dir: "asc", get: item => item.pattern_hour ?? null }],
      filters: [{ name: "level", all: this.t("relAllStates"), options: [["flapping", this.t("relOnlyFlapping")], ["unstable", this.t("relOnlyUnstable")]] }],
      filterFns: { level: (item, v) => item.level === v },
      text: item => [item.name, item.entity_id, item.entry_title].join(" "), tie: item => item.entity_id, empty: "relUnstableNone",
      rowAttrs: item => `data-object="entity:${this.esc(item.entity_id)}" tabindex="0" role="button" aria-label="${this.esc(item.name)}"`,
      columns: [
        { key: "name", label: "utName", cell: item => this.nameCell(item.name, `${item.entity_id}${item.entry_title ? ` · ${item.entry_title}` : ""}`) },
        { key: "level", label: "relColLevel", sortable: false, cell: item => `<span class="pill ${tone(item)}">${this.t(item.level === "flapping" ? "relFlapping" : "relUnstable")}</span>` },
        { key: "episodes", label: "relSortEpisodes", dir: "desc", cell: item => this.esc(this.formatNumber(item.episodes)) },
        { key: "rate", label: "relSortRate", dir: "desc", cell: item => this.esc(this.formatNumber(item.per_day)) },
        { key: "duration", label: "relSortDuration", dir: "desc", cell: item => this.esc(this.relDuration(item.total_seconds)) },
        { key: "pattern", label: "relColPattern", dir: "asc", cell: item => this.esc(pattern(item) || "–") },
      ],
      exportName: "reliability-unstable", header: [this.t("utName"), "ID", this.t("relSortEpisodes"), this.t("relSortRate"), this.t("relSortDuration")], rows: item => [item.name, item.entity_id, item.episodes, item.per_day, item.total_seconds],
    });
    const count = level => u.items.filter(item => item.level === level).length;
    const tiles = this.sumTiles([
      { label: this.t("relSumAll"), value: this.formatNumber(u.items.length), tone: "mute", lf: ["relunstable", "", ""] },
      { label: this.t("relOnlyFlapping"), value: this.formatNumber(count("flapping")), tone: count("flapping") ? "red" : "ok", lf: ["relunstable", "level", "flapping"] },
      { label: this.t("relOnlyUnstable"), value: this.formatNumber(count("unstable")), tone: count("unstable") ? "warn" : "ok", lf: ["relunstable", "level", "unstable"] },
    ]);
    return `${tiles}<div class="panel">${head}${list}${more}${this.howCounted("relUnstableFootnote", { episodes: th.unstable_min_episodes ?? 3, rate: this.formatNumber(th.unstable_per_day ?? 0.5), flap: this.formatNumber(th.flapping_per_day ?? 1.5) })}</div>`;
  }
}

// RunsMixin: the automation runs view; mixed into the panel in 99-register.js.
const RUN_FINDINGS = {
  failing: ["rfLabelFailing", "rfFailing"], overlap: ["rfLabelOverlap", "rfOverlap"], never_ok: ["rfLabelNeverOk", "rfNeverOk"],
  no_effect: ["rfLabelNoEffect", "rfNoEffect"], burst: ["rfLabelBurst", "rfBurst"], long_run: ["rfLabelLongRun", "rfLongRun"],
  after_update: ["rfLabelAfterUpdate", "rfAfterUpdate"], long_wait: ["rfLabelLongWait", "rfLongWait"],
  wait_no_timeout: ["rfLabelWaitNoTimeout", "rfWaitNoTimeout"], continue_on_error: ["rfLabelContinue", "rfContinue"],
};

class RunsMixin {
  async loadRuns() {
    this.runsLoading = true; this.runsError = ""; this.render();
    try { this.runs = await this._hass.callWS({ type: "ha_housekeeper/automation_runs" }); this.markLoaded("runs"); }
    catch (err) { this.runsError = this.errText(err); }
    this.runsLoading = false; this.render();
  }

  // Loaded once per visit; the button counts again.
  ensureRuns() {
    if (this.runsLoading || this._runsRequested) return;
    this._runsRequested = true;
    setTimeout(() => this.loadRuns(), 0);
  }

  runsDuration(ms) {
    if (ms === null || ms === undefined) return "—";
    if (ms < 1000) return this.t("runsMs", { n: ms });
    if (ms < 60000) return this.t("runsSec", { n: this.formatNumber(Math.round(ms / 100) / 10) });
    return this.relDuration(ms / 1000);
  }

  runFindingText(f) {
    const p = {
      failing: () => this.t("rfFailing", { errors: f.errors, runs: f.runs }) + (f.step ? this.t("rfFailingStep", { step: this.esc(f.step), count: f.step_count }) : ""),
      overlap: () => this.t("rfOverlap", { n: f.already + f.maxed, mode: this.esc(f.mode || "—") }),
      never_ok: () => this.t("rfNeverOk", { runs: f.runs }),
      no_effect: () => this.t("rfNoEffect", { conditions: f.conditions, runs: f.runs }),
      burst: () => this.t("rfBurst", { perDay: this.formatNumber(f.per_day), normal: this.formatNumber(f.normal) }),
      long_run: () => this.t("rfLongRun", { longest: this.runsDuration(f.longest_ms), normal: this.runsDuration(f.normal_ms) }),
      after_update: () => this.t("rfAfterUpdate", { after: f.rate_after, before: f.rate_before, what: this.esc(f.event === "ha_version" ? this.t("rfWhatHa", { to: f.to || "" }) : this.t("rfWhatEntry", { domain: f.domain || "", to: f.to || "" })) }),
      long_wait: () => this.t("rfLongWait", { duration: this.relDuration(f.seconds) }),
      wait_no_timeout: () => this.t("rfWaitNoTimeout", { n: f.count }),
      continue_on_error: () => this.t("rfContinue", { n: f.count }),
    }[f.kind];
    return p ? p() : "";
  }

  runsFindingLines(row) {
    return row.findings.map(f => `<small class="fline"><span class="pill ${f.level === "info" ? "mute" : f.level}">${this.t((RUN_FINDINGS[f.kind] || ["rfLabelFailing"])[0])}</span><span class="fnum">${this.runFindingText(f)}</span><span class="fnote">${this.t(`rfHint_${f.kind}`)}</span></small>`).join("");
  }

  runsTrend(row, days = row.per_day) {
    const max = Math.max(1, ...days);
    const bars = days.map(n => `<i style="height:${Math.round((n / max) * 100)}%"></i>`).join("");
    return `<span class="runspark" role="img" aria-label="${this.esc(this.t("runsTrendLabel", { values: days.join(", ") }))}">${bars}</span>`;
  }

  // The cells of one possible conflict or loop between automations: what it is and how often it was seen.
  conflictText(c) {
    const names = c.automations.map(a => `<b>${this.esc(a.name)}</b>`);
    return c.kind === "opposing"
      ? this.t("cfOpposing", { first: names[0], second: names[1], entity: `<code>${this.esc(c.entity_id)}</code>`, a: this.esc(c.commands[0]), b: this.esc(c.commands[1]) }) + " " + this.t(`cfWhy_${c.reason}`, { detail: this.esc(c.detail) })
      : this.t("cfLoop", { chain: names.join(", "), path: c.entities.map(e => `<code>${this.esc(e)}</code>`).join(" → ") });
  }

  conflictSeen(c) {
    return c.stage === "static" ? this.t("cfStatic") : this.t(c.kind === "loop" ? "cfSeenLoop" : "cfSeen", { n: c.days, min: this.runs?.thresholds?.conflicts_loop_min_runs_per_day ?? 20 });
  }

  // Possible conflicts and loops between automations as a table; only shown when the check found something.
  conflictsPanel(r) {
    const c = r.conflicts;
    if (!c) return "";
    if (!c.items.length) return `<p class="factnote">${this.t("cfNone")}</p>`;
    const rank = { confirmed: 0, observed: 1, static: 2 };
    const key = item => `${item.kind}|${item.entity_id || (item.entities || []).join(",")}|${item.automations.map(a => a.entity_id).join(",")}`;
    const tone = item => (item.stage === "confirmed" ? "warn" : "mute");
    const list = this.sysList("runs_conflicts", c.items, {
      sort: "stage", dir: "asc", tie: key, empty: "cfNone",
      sorts: [
        { key: "stage", label: "cfColStage", dir: "asc", get: item => rank[item.stage] ?? 3 },
        { key: "kind", label: "cfColKind", dir: "asc", get: item => this.t(`cfKind_${item.kind}`) },
      ],
      filters: [{ name: "kind", all: this.t("cfAllKinds"), options: [["opposing", this.t("cfKind_opposing")], ["loop", this.t("cfKind_loop")]] }],
      filterFns: { kind: (item, v) => item.kind === v },
      text: item => [...item.automations.map(a => a.name), item.entity_id, ...(item.entities || [])].join(" "),
      columns: [
        { key: "stage", label: "cfColStage", dir: "asc", cell: item => `<span class="pill ${tone(item)}">${this.t(`cfStage_${item.stage}`)}</span>` },
        { key: "kind", label: "cfColKind", dir: "asc", cell: item => this.t(`cfKind_${item.kind}`) },
        { key: "what", label: "cfColWhat", sortable: false, cell: item => `${this.conflictText(item)}<small>${this.esc(this.conflictSeen(item))}</small><small class="fnote">${this.t(`cfHint_${item.kind}`)}</small>` },
        { key: "autos", label: "cfColAutomations", sortable: false, cell: item => item.automations.map(a => `<button class="link" data-object="${this.esc(`automation:${a.entity_id}`)}">${this.esc(a.name)}</button>`).join(" · ") },
      ],
    });
    return `<div class="panel">${this.fold("runs_conflicts", { tone: "warn", title: this.t("cfTitle"), sub: this.t("cfHint"), pill: this.formatNumber(c.items.length) }, list, false)}</div>`;
  }

  runsSorts() {
    return [
      { key: "name", label: "runsColName", dir: "asc", get: r => r.name },
      { key: "runs", label: "runsColRuns", dir: "desc", get: r => r.runs },
      { key: "errors", label: "runsColErrors", dir: "desc", get: r => r.errors },
      { key: "conditions", label: "runsColConditions", dir: "desc", get: r => r.conditions },
      { key: "duration", label: "runsColDuration", dir: "desc", get: r => r.mean_ms },
    ];
  }

  // Search text and the two filters of the runs view; they cut the table and the list of what stands out alike.
  runsMatch(row) {
    const st = this.lv.runs, q = st.q.trim().toLowerCase();
    if (q && ![row.name, row.entity_id].join(" ").toLowerCase().includes(q)) return false;
    if (st.f.type && row.object_type !== st.f.type) return false;
    if (st.f.outcome === "errors" && !row.errors) return false;
    if (st.f.outcome === "flagged" && !row.findings.length) return false;
    if (st.f.outcome === "never" && !row.findings.some(f => f.kind === "never_ok")) return false;
    return true;
  }

  runsBar(rows = []) {
    this.setExporter("runs", "runs", [this.t("runsColName"), "ID", this.t("runsColRuns"), this.t("runsColErrors"), this.t("runsColConditions"), `${this.t("runsColDuration")} (ms, mean)`, `${this.t("runsColDuration")} (ms, max)`], () => rows.map(r => [r.name, r.entity_id, r.runs, r.errors, r.conditions, r.mean_ms ?? "", r.max_ms ?? ""]));
    return this.listBar("runs", { table: true, dense: true, columns: [{ key: "runs", label: "runsColRuns" }, { key: "errors", label: "runsColErrors" }, { key: "conditions", label: "runsColConditions" }, { key: "duration", label: "runsColDuration" }, { key: "trend", label: "runsColTrend" }], sorts: this.runsSorts(), filters: [
      { name: "type", all: this.t("allTypes"), options: [["automation", this.t("automation")], ["script", this.t("script")]] },
      { name: "outcome", all: this.t("runsAllOutcomes"), options: [["errors", this.t("runsOnlyErrors")], ["flagged", this.t("runsOnlyFlagged")], ["never", this.t("ovRunsNever")]] },
    ] });
  }

  runsTable(rows) {
    this.lvState("runs", "runs", "desc");
    const pg = this.paginate("runsall", rows);
    const columns = [
      { key: "name", label: "runsColName", dir: "asc", cell: row => this.nameCell(row.name, row.entity_id) + this.runsFindingLines(row) },
      { key: "runs", label: "runsColRuns", dir: "desc", cell: row => `${this.formatNumber(row.runs)}${row.lower_bound ? "+" : ""}` },
      { key: "errors", label: "runsColErrors", dir: "desc", cell: row => this.formatNumber(row.errors) },
      { key: "conditions", label: "runsColConditions", dir: "desc", cell: row => this.formatNumber(row.conditions) },
      { key: "duration", label: "runsColDuration", dir: "desc", cell: row => `${this.runsDuration(row.mean_ms)} / ${this.runsDuration(row.max_ms)}` },
      { key: "trend", label: "runsColTrend", sortable: false, cell: row => this.runsTrend(row) },
    ];
    const table = this.listTable("runs", columns, pg.rows, { cls: "runs", rowAttrs: row => `data-object="${this.esc(`${row.object_type}:${row.entity_id}`)}" tabindex="0" role="button" aria-label="${this.esc(row.name)}"` });
    return `${table}${pg.footer}`;
  }

  // The numbers of one automation or script for its detail page; only when runs were counted for it.
  runsRow(item) {
    if (!["automation", "script"].includes(item.object_type)) return null;
    return (this.runs?.items || []).find(row => row.entity_id === item.object_id && (row.runs || row.findings.length)) || null;
  }

  runsDetailCard(row) {
    const since = this.runs?.since ? this.t("runsTabHint", { date: this.formatDate(this.runs.since) }) : "";
    const facts = [["runsColRuns", `${this.formatNumber(row.runs)}${row.lower_bound ? "+" : ""}`], ["runsColErrors", this.formatNumber(row.errors)], ["runsColConditions", this.formatNumber(row.conditions)], ["runsColDuration", `${this.runsDuration(row.mean_ms)} / ${this.runsDuration(row.max_ms)}`]]
      .map(([label, value]) => `<dt>${this.t(label)}</dt><dd>${value}</dd>`).join("");
    const notes = row.findings.length ? `<div class="pad">${this.runsFindingLines(row)}</div>` : "";
    const c = row.change;
    const side = s => this.t("runsChangeSide", { errors: this.formatNumber(s.errors), runs: this.formatNumber(s.runs) });
    const change = c ? `<div class="pad"><p class="factnote"><ha-icon icon="mdi:source-commit"></ha-icon> ${this.esc(this.t("runsChange", { date: this.formatDate(c.at), after: side(c.after), before: side(c.before) }))}</p></div>` : "";
    return `<section class="panel"><div class="panelhead"><div><h2>${this.t("runsTab")}</h2><p>${since}</p></div></div><div class="pad"><dl class="kv">${facts}<dt>${this.t("runsTrend30")}</dt><dd>${this.runsTrend(row, row.per_day_30 || row.per_day)}</dd></dl></div>${change}${notes}${this.howCounted("runsFootnote")}</section>`;
  }

  // Two tabs: the counted runs, and the quality of each automation (46-diagnostics.js).
  runsView() {
    const tabs = [
      { id: "overview", icon: "mdi:clipboard-pulse-outline", label: this.t("qualityTab"), hint: this.t("runsTileQualityHint"), tone: "mute" },
      { id: "runs", icon: "mdi:run-fast", label: this.t("runsTabRuns"), hint: this.t("runsTileRunsHint"), tone: "mute" },
      { id: "scripts", icon: "mdi:script-text-outline", label: this.t("scTab"), hint: this.t("scTabHint"), tone: "mute" },
    ];
    const open = this.viewTabOf("runs", tabs, "overview");
    if (open === "overview") return `<div class="stack">${this.navTiles("runs", tabs, open, this.t("runs"), true)}${this.qualityView()}</div>`;
    const body = open === "scripts" ? this.scriptsView() : this.runsListView();
    return `<div class="stack">${this.navTiles("runs", tabs, open, this.t("runs"), true)}${body}</div>`;
  }

  runsListView() {
    this.ensureRuns();
    const r = this.runs;
    const since = r?.since ? ` · ${this.t("runsSince", { date: this.formatDate(r.since) })}` : "";
    const head = this.pageBar({ left: since ? `<span>${this.esc(since.replace(/^ · /, ""))}</span>` : "", at: this.loadedAt("runs"), loading: this.runsLoading, attr: "data-runs-refresh" });
    if (this.runsError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.runsError)}</div></div></div>`;
    if (!r) return `<div class="stack">${head}<div class="panel">${this.skeleton("runsLoading")}</div></div>`;
    this.lvState("runs", "runs", "desc");
    const lower = r.items.filter(row => row.lower_bound).length;
    const coverage = this.coverageNote(this.t(lower ? "runsCoverageLower" : "runsCoverageFull", { n: this.formatNumber(lower), days: r.window_days }) + ` ${this.excludedText(r.excluded)}`.trimEnd());
    const everyCounted = r.items.filter(row => row.runs);
    const counted = this.refine("runs", everyCounted.filter(row => this.runsMatch(row)), { text: row => [row.name, row.entity_id].join(" "), sorts: this.runsSorts(), tie: row => row.entity_id });
    const bar = everyCounted.length > 5 || this.lv.runs.q ? this.runsBar(counted) : "";
    const more = r.total > r.items.length ? `<p class="factnote">${this.t("runsMore", { shown: r.items.length, total: r.total })}</p>` : "";
    const all = everyCounted.length ? `<div class="panel"><div class="panelhead"><div><h2>${this.t("runsAll")}</h2></div></div>${bar}${counted.length ? this.runsTable(counted) : `<div class="emptymsg">${this.t("noMatches")}</div>`}${more}${this.howCounted("runsFootnote")}</div>` : "";
    const runTotal = r.items.reduce((n, row) => n + row.runs, 0), errorTotal = r.items.reduce((n, row) => n + row.errors, 0);
    const neverOk = r.items.filter(row => row.findings.some(f => f.kind === "never_ok")).length;
    const allFlagged = r.items.filter(row => row.findings.length).length;
    const tiles = this.sumTiles([
      { label: this.t("runsSumRuns"), value: this.formatNumber(runTotal), sub: this.t("runsSumOf", { n: this.formatNumber(everyCounted.length) }), tone: "mute" },
      { label: this.t("runsColErrors"), value: this.formatNumber(errorTotal), sub: runTotal ? this.t("runsSumShare", { n: this.formatNumber(Math.round((1000 * errorTotal) / runTotal) / 10) }) : "", tone: errorTotal ? "warn" : "ok", lf: ["runs", "outcome", "errors"] },
      { label: this.t("runsSumFlagged"), value: this.formatNumber(allFlagged), tone: allFlagged ? "warn" : "ok", lf: ["runs", "outcome", "flagged"] },
      { label: this.t("runsSumNeverOk"), value: this.formatNumber(neverOk), tone: neverOk ? "red" : "ok", lf: ["runs", "outcome", "never"] },
    ]);
    return `<div class="stack">${head}${tiles}<div class="panel">${coverage}${!everyCounted.length ? `<div class="emptymsg">${this.t("runsNoData")}</div>` : allFlagged ? "" : `<p class="factnote">${this.t("runsNone")}</p>`}</div>${all}${this.conflictsPanel(r)}</div>`;
  }
}

// StormsMixin: the recorder load view; mixed into the panel in 99-register.js.
class StormsMixin {
  async loadStorms(refresh = false) {
    this.stormsLoading = true; this.stormsError = ""; this.render();
    try { this.storms = await this._hass.callWS({ type: "ha_housekeeper/storms", window_days: this.stormsWindow, refresh }); this.markLoaded("storms"); }
    catch (err) { this.stormsError = this.errText(err); }
    this.stormsLoading = false; this.render();
    this.followUp("storms", "recorder", this.storms, r => this.loadStorms(r), refresh);
  }

  // The first visit and every change of the window load once; the backend keeps the result for ten minutes.
  ensureStorms() {
    if (this.stormsLoading || this._stormsRequested === this.stormsWindow) return;
    this._stormsRequested = this.stormsWindow;
    setTimeout(() => this.loadStorms(), 0);
  }

  // "2 automations, 1 script": what hangs on the loud entity, by type.
  stormFollowers(followers) {
    const parts = Object.entries(followers || {}).map(([type, n]) => `${this.formatNumber(n)} ${this.t(type === "config_entry" ? "config_entry" : type)}`);
    return parts.length ? this.t("stormFollowers", { list: parts.join(", ") }) : "";
  }

  stormFindingText(f) {
    const n = v => this.formatNumber(v);
    if (f.kind === "storm") return this.t("stormStorm", { perDay: n(f.per_day), peak: n(f.peak_hour) });
    if (f.kind === "attribute_flood") return this.t("stormFlood", { perDay: n(f.per_day), kb: this.formatNumber(Math.round(f.attr_bytes / 102.4) / 10) });
    if (f.kind === "no_new_state") return this.t("stormNoNew", { share: f.share, perDay: n(f.per_day) });
    if (f.kind === "integration_share") return this.t("stormShare", { share: this.formatNumber(f.load_share), perDay: n(f.per_day) });
    return this.t("stormEvent", { count: n(f.count), type: f.event_type });
  }

  // One card per entity with all its findings; an integration and an event type stand alone. The findings come sorted by kind and rate.
  stormGroups(r) {
    const map = new Map(), groups = [];
    for (const f of r?.findings || []) {
      const type = f.kind === "integration_share" ? "integrations" : f.kind === "event_burst" ? "events" : "entities";
      const key = `${type}:${f.entity_id || f.title || f.event_type}`;
      let group = map.get(key);
      if (!group) { group = { key, type, items: [] }; map.set(key, group); groups.push(group); }
      group.items.push(f);
    }
    return groups;
  }

  // One row per group: the numbers sit in columns so the list sorts by them; the sentences live in the object's details.
  stormGroupFact(group, kind, field) {
    return group.items.find(f => f.kind === kind)?.[field] ?? null;
  }

  stormGroupsList(groups) {
    const num = v => (v === null || v === undefined ? "–" : this.esc(this.formatNumber(v)));
    const tone = f => (f.kind === "storm" ? "red" : f.kind === "integration_share" || f.kind === "event_burst" ? "blue" : "warn");
    const title = g => (g.type === "events" ? g.items[0].event_type : g.type === "integrations" ? g.items[0].title : g.items[0].name || g.items[0].entity_id);
    const perDay = g => g.items.map(f => f.per_day ?? f.count).find(v => v !== undefined) ?? null;
    const peak = g => this.stormGroupFact(g, "storm", "peak_hour");
    const share = g => this.stormGroupFact(g, "no_new_state", "share");
    const target = g => (g.type === "entities" ? `entity:${g.items[0].entity_id}` : g.type === "integrations" && g.items[0].entry_id && this.findObject(`config_entry:${g.items[0].entry_id}`) ? `config_entry:${g.items[0].entry_id}` : "");
    const kindsOf = g => g.items.map(f => f.kind);
    const present = ["storm", "attribute_flood", "no_new_state", "integration_share", "event_burst"].filter(k => groups.some(g => kindsOf(g).includes(k)));
    const columns = [
      { key: "sel", label: "stormColSelect", sortable: false, narrow: true, allBox: rows => this.excludeAllBox(rows.filter(g => g.type === "entities").map(g => g.items[0].entity_id)), cell: g => (g.type === "entities" ? this.excludeBox(g.items[0].entity_id) : "") },
      { key: "name", label: "utName", cell: g => { const chain = g.items.map(f => this.stormFollowers(f.followers)).find(Boolean); return `${this.nameCell(title(g), g.type === "entities" && g.items[0].entity_id !== title(g) ? g.items[0].entity_id : "")}${chain ? `<small class="muted">${this.esc(chain)}</small>` : ""}`; } },
      { key: "kinds", label: "stormColKinds", sortable: false, cell: g => g.items.map(f => `<span class="pill ${tone(f)}">${this.t(`stormKind_${f.kind}`)}</span>`).join(" ") },
      { key: "perDay", label: "stormColPerDay", dir: "desc", cell: g => num(perDay(g)) },
      { key: "peak", label: "stormColPeak", dir: "desc", cell: g => num(peak(g)) },
      { key: "share", label: "stormColNoNew", dir: "desc", cell: g => (share(g) === null ? "–" : `${this.esc(this.formatNumber(share(g)))} %`) },
      { key: "mark", label: "stormColAction", sortable: false, cell: g => (g.type === "integrations" && g.items[0].entry_id ? this.stormEntryButton(g.items[0].entry_id) : "") },
    ];
    return this.sysList("stormfind", groups, {
      sort: "perDay", dir: "desc",
      sorts: [
        { key: "perDay", label: "stormColPerDay", dir: "desc", get: perDay },
        { key: "name", label: "utName", dir: "asc", get: title },
        { key: "peak", label: "stormColPeak", dir: "desc", get: peak },
        { key: "share", label: "stormColNoNew", dir: "desc", get: share },
      ],
      filters: [
        { name: "type", all: this.t("stormFilterAll"), options: [["entities", this.t("stormGroupEntities")], ["integrations", this.t("stormGroupIntegrations")], ["events", this.t("stormGroupEvents")]].filter(([id]) => groups.some(g => g.type === id)) },
        { name: "kind", all: this.t("stormFilterKind"), options: present.map(k => [k, this.t(`stormKind_${k}`)]) },
      ],
      filterFns: { type: (g, v) => g.type === v, kind: (g, v) => kindsOf(g).includes(v) },
      text: g => g.items.flatMap(f => [f.name, f.entity_id, f.title, f.event_type]).join(" "), tie: g => g.key, empty: "stormNone", columns,
      rowAttrs: g => (target(g) ? `data-object="${this.esc(target(g))}" tabindex="0" role="button" aria-label="${this.esc(title(g))}"` : 'class="static"'),
    });
  }

  // Shows the loudest entities of one integration entry: the list already carries each entity's entry_id.
  stormEntryButton(entryId) {
    return `<button class="btn" data-storm-entry="${this.esc(entryId)}">${this.t("stormShowEntities")}</button>`;
  }

  stormLegend(r) {
    const th = r.thresholds || {}, n = v => this.formatNumber(v);
    const row = (kind, text) => `<div><span class="pill ${kind === "storm" ? "red" : kind === "integration_share" || kind === "event_burst" ? "blue" : "warn"}">${this.t(`stormKind_${kind}`)}</span><span>${this.esc(text)}</span></div>`;
    return `<details class="howto"><summary>${this.t("stormLegendTitle")}</summary><div class="stormlegend">${[
      row("storm", this.t("stormLegStorm", { peak: n(th.storm_peak_rows ?? 3600), day: n(th.storm_rows_per_day ?? 50000) })),
      row("attribute_flood", this.t("stormLegFlood", { kb: n(Math.round((th.flood_attr_bytes ?? 4096) / 1024)), min: n(th.flood_min_rows_per_day ?? 1000) })),
      row("no_new_state", this.t("stormLegNoNew", { share: n(Math.round((th.no_new_state_share ?? 0.8) * 100)), min: n(th.no_new_state_min_rows_per_day ?? 1000) })),
      row("integration_share", this.t("stormLegShare", { share: n(th.share_percent ?? 25), min: n(th.share_min_rows_per_day ?? 10000) })),
      row("event_burst", this.t("stormLegBurst", { count: n(th.event_burst ?? 100000) })),
    ].join("")}</div></details>`;
  }

  // The loudest entities as the same kind of table as the findings: numbers in columns, sortable, with the box column.
  stormEntitiesList(entities) {
    const num = v => (v === null || v === undefined ? "–" : this.esc(this.formatNumber(v)));
    const kb = item => (item.attr_bytes === null || item.attr_bytes === undefined ? null : Math.round(item.attr_bytes / 102.4) / 10);
    const info = item => this.excludeInfo(item.entity_id, item.per_day, item.excluded);
    const columns = [
      { key: "sel", label: "stormColSelect", sortable: false, narrow: true, allBox: rows => this.excludeAllBox(rows.map(item => item.entity_id)), cell: item => this.excludeBox(item.entity_id) },
      { key: "name", label: "utName", cell: item => this.nameCell(item.name || item.entity_id, item.name ? item.entity_id : "") },
      { key: "hint", label: "stormColHint", sortable: false, cell: item => { const i = info(item); return `<span class="extags" ${i.why ? `title="${this.esc(i.why)}"` : ""}>${i.tags}</span>`; } },
      { key: "rows", label: "stormColRows", dir: "desc", cell: item => num(item.rows) },
      { key: "perDay", label: "stormColPerDay", dir: "desc", cell: item => num(item.per_day) },
      { key: "noNew", label: "stormColNoNew", dir: "desc", cell: item => (item.no_new_state === null || item.no_new_state === undefined ? "–" : `${this.esc(this.formatNumber(Math.round(item.no_new_state * 100)))} %`) },
      { key: "attr", label: "stormColAttr", dir: "desc", cell: item => num(kb(item)) },
      { key: "peak", label: "stormColPeak", dir: "desc", cell: item => num(item.peak_hour) },
    ];
    return this.sysList("stormentities", entities, {
      sort: "rows", dir: "desc",
      sorts: [
        { key: "rows", label: "stormColRows", dir: "desc", get: item => item.rows ?? 0 },
        { key: "perDay", label: "stormColPerDay", dir: "desc", get: item => item.per_day ?? 0 },
        { key: "name", label: "utName", dir: "asc", get: item => item.name || item.entity_id },
        { key: "noNew", label: "stormColNoNew", dir: "desc", get: item => item.no_new_state ?? 0 },
        { key: "peak", label: "stormColPeak", dir: "desc", get: item => item.peak_hour ?? 0 },
      ],
      text: item => `${item.name || ""} ${item.entity_id}`, tie: item => item.entity_id, empty: "stormNone", columns,
      rowAttrs: item => `class="${[info(item).suggest ? "exsug" : "", item.excluded ? "exdone" : ""].filter(Boolean).join(" ")}" data-object="entity:${this.esc(item.entity_id)}" tabindex="0" role="button" aria-label="${this.esc(item.name || item.entity_id)}"`,
    });
  }

  // The shares of the integrations as a table; a bar needs a text next to it, so the percentage stands in the cell.
  stormSharesList(items) {
    const bar = v => `<span class="sharebar" aria-hidden="true"><i style="width:${Math.max(0, Math.min(100, v))}%"></i></span>`;
    return this.sysList("stormshares", items, {
      sort: "load", dir: "desc",
      sorts: [
        { key: "load", label: "stormColLoad", dir: "desc", get: item => item.load_share ?? 0 },
        { key: "rowShare", label: "stormColRowShare", dir: "desc", get: item => item.row_share ?? 0 },
        { key: "perDay", label: "stormColPerDay", dir: "desc", get: item => item.per_day ?? 0 },
        { key: "entities", label: "stormColEntities", dir: "desc", get: item => item.entities ?? 0 },
        { key: "name", label: "utName", dir: "asc", get: item => item.title },
      ],
      text: item => [item.title, item.domain].join(" "), tie: item => item.title, empty: "stormNone",
      rowAttrs: item => (item.entry_id && this.findObject(`config_entry:${item.entry_id}`) ? `data-object="${this.esc(`config_entry:${item.entry_id}`)}" tabindex="0" role="button" aria-label="${this.esc(item.title)}"` : 'class="static"'),
      columns: [
        { key: "name", label: "utName", dir: "asc", cell: item => this.nameCell(item.title, item.domain || "") },
        { key: "entities", label: "stormColEntities", dir: "desc", cell: item => this.esc(this.formatNumber(item.entities)) },
        { key: "perDay", label: "stormColPerDay", dir: "desc", cell: item => this.esc(this.formatNumber(item.per_day)) },
        { key: "rowShare", label: "stormColRowShare", dir: "desc", cell: item => `${this.esc(this.formatNumber(item.row_share))} %` },
        { key: "load", label: "stormColLoad", dir: "desc", cell: item => `${this.esc(this.formatNumber(item.load_share))} %${bar(item.load_share)}` },
        { key: "act", label: "stormColAction", sortable: false, cell: item => (item.entry_id ? this.stormEntryButton(item.entry_id) : "") },
      ],
    });
  }

  // The events by type as a table: count, share with a bar, and the rate per day; state_changed is the normal bulk and never "far ahead".
  stormEventsList(r) {
    const top = Math.max(...r.events.map(e => e.count), 1), total = r.event_total || r.events.reduce((sum, e) => sum + e.count, 0) || 1, days = r.window_days || 1;
    const pct = e => (e.count / total) * 100;
    const ahead = e => r.events.length > 1 && pct(e) > 50 && e.type !== "state_changed";
    return this.sysList("stormevents", r.events, {
      sort: "count", dir: "desc",
      sorts: [
        { key: "count", label: "stormColCount", dir: "desc", get: e => e.count },
        { key: "name", label: "stormColEvent", dir: "asc", get: e => e.type },
      ],
      text: e => `${e.type} ${this.t(`evt_${e.type}`)}`, tie: e => e.type, empty: "stormNone",
      columns: [
        { key: "name", label: "stormColEvent", dir: "asc", cell: e => { const key = `evt_${e.type}`, what = this.t(key); return `<strong class="mono">${this.esc(e.type)}</strong>${ahead(e) ? ` <span class="pill warn">${this.t("evAhead")}</span>` : ""}${what !== key ? `<small class="exwhy">${this.esc(what)}</small>` : ""}`; } },
        { key: "count", label: "stormColCount", dir: "desc", cell: e => `<strong>${this.esc(this.formatNumber(e.count))}</strong><span class="bar evbar"><i style="width:${Math.max(1, Math.round((e.count / top) * 100))}%"></i></span>` },
        { key: "share", label: "stormColShare", sortable: false, cell: e => this.esc(pct(e) < 1 ? this.t("evLessThanOne") : `${Math.round(pct(e))} %`) },
        { key: "perDay", label: "stormColPerDay", sortable: false, cell: e => this.esc(this.formatNumber(Math.round(e.count / days))) },
      ],
    });
  }

  // Operation > Recorder: what writes the most, what fills the database, and how healthy it is.
  // The two recorder queries run one after the other: the second starts when the first is done.
  recorderView() {
    const stormsDone = this.storms || this.stormsError;
    if (stormsDone) this.ensureDbHealth();
    const st = this.storms?.available && !this.storms.busy ? this.storms : null;
    const db = this.dbHealth?.available && !this.dbHealth.busy ? this.dbHealth : null;
    const meta = this.data?.meta?.database;
    const stormFindings = st ? this.stormGroups(st).length : 0;
    const dbFindings = db ? db.findings.length : 0;
    const dbTone = !db ? "mute" : db.findings.some(f => f.level === "problem") ? "red" : dbFindings ? "warn" : "ok";
    const stormTone = !st ? "mute" : st.findings.some(f => f.kind === "storm" || f.kind === "integration_share") ? "red" : stormFindings ? "warn" : "ok";
    const bytes = db?.db_bytes ?? meta?.db_bytes;
    const perDay = db?.growth?.known ? db.growth.per_day : meta?.per_day;
    const keep = db?.keep_days ?? meta?.keep_days, purge = db?.auto_purge ?? meta?.auto_purge;
    const loud = st?.entities?.[0], topCost = this.costs?.entities?.[0];
    const stormGroups = st ? this.stormGroups(st) : [];
    const loadFacts = ["storm", "integration_share", "no_new_state", "attribute_flood", "event_burst"]
      .map(k => ({ k, n: stormGroups.filter(g => g.items.some(f => f.kind === k)).length })).filter(x => x.n)
      .map(x => ({ text: `${this.t(`stormKind_${x.k}`)}: ${this.formatNumber(x.n)}`, tone: x.k === "storm" || x.k === "integration_share" ? "red" : "warn" }));
    const dbFacts = [
      purge === false ? { text: this.t("recSumPurgeOff"), tone: "warn" } : null,
      bytes !== null && bytes !== undefined ? { text: this.formatBytes(bytes), tone: "mute" } : null,
      perDay !== null && perDay !== undefined ? { text: this.t("dbOvPerDay", { size: this.formatBytes(Math.max(0, perDay)) }), tone: "mute" } : null,
    ].filter(Boolean);
    const tabs = [
      { id: "load", icon: "mdi:chart-timeline-variant", label: this.t("stormTitle"), hint: this.t("recTileLoadHint"), count: st ? stormFindings : null, facts: loadFacts, tone: stormTone },
      { id: "costs", icon: "mdi:database-search-outline", label: this.t("recorderTitle"), hint: this.t("recTileCostsHint"), facts: topCost ? [{ text: this.t("recTileCostsTop", { name: topCost.name || topCost.entity_id, share: topCost.share }), tone: "mute" }] : [], tone: "mute" },
      { id: "db", icon: "mdi:database-outline", label: this.t("dbTitle"), hint: this.t("recTileDbHint"), count: db ? dbFindings : null, facts: dbFacts, tone: dbTone },
    ];
    const open = this.viewTabOf("recorder", tabs, "load");
    const body = open === "costs" ? this.recorderCard() : open === "db" ? this.dbCard() : this.stormsView();
    return `<div class="stack">${this.navTiles("recorder", tabs, open, this.t("recorder"), true)}${body}</div>`;
  }

  // What the load view shows, for the export of the page: findings, loudest entities, integrations and events.
  stormsExporter(r) {
    const days = r.window_days || 1, kb = e => (e.attr_bytes === null || e.attr_bytes === undefined ? "" : Math.round(e.attr_bytes / 102.4) / 10), total = r.event_total || (r.events || []).reduce((sum, e) => sum + e.count, 0) || 1;
    const name = g => (g.type === "events" ? g.items[0].event_type : g.type === "integrations" ? g.items[0].title : g.items[0].name || g.items[0].entity_id);
    this.setPageExporter("recload", `recorder-load-${days}d`, `${this.t("recorder")} · ${this.t("stormTitle")}`, [
      { name: "findings", title: this.t("stormTabFindings"), header: [this.t("utName"), "ID", this.t("stormColKinds"), this.t("stormColPerDay"), this.t("stormColPeak"), this.t("stormColNoNew"), this.t("expColText")],
        rows: () => this.stormGroups(r).map(g => [name(g), g.type === "entities" ? g.items[0].entity_id : "", g.items.map(f => this.t(`stormKind_${f.kind}`)).join(", "), g.items.map(f => f.per_day ?? f.count).find(v => v !== undefined) ?? "", this.stormGroupFact(g, "storm", "peak_hour") ?? "", this.stormGroupFact(g, "no_new_state", "share") ?? "", g.items.map(f => this.plainText(this.stormFindingText(f))).join(" ")]) },
      { name: "entities", title: this.t("stormTabEntities"), header: [this.t("utName"), "ID", this.t("stormColRows"), this.t("stormColPerDay"), this.t("stormColNoNew"), this.t("stormColAttr"), this.t("stormColPeak")],
        rows: () => (r.entities || []).map(e => [e.name || "", e.entity_id, e.rows ?? "", e.per_day ?? "", e.no_new_state === null || e.no_new_state === undefined ? "" : Math.round(e.no_new_state * 100), kb(e), e.peak_hour ?? ""]) },
      { name: "integrations", title: this.t("stormTabIntegrations"), header: [this.t("utName"), "Domain", this.t("stormColEntities"), this.t("stormColPerDay"), this.t("stormColRowShare"), this.t("stormColLoad")],
        rows: () => (r.integrations || []).map(i => [i.title, i.domain || "", i.entities ?? "", i.per_day ?? "", i.row_share ?? "", i.load_share ?? ""]) },
      { name: "events", title: this.t("stormTabEvents"), header: [this.t("stormColEvent"), this.t("stormColCount"), "%", this.t("stormColPerDay")],
        rows: () => (r.events || []).map(e => [e.type, e.count, Math.round((e.count / total) * 1000) / 10, Math.round(e.count / days)]) },
    ].filter(sec => sec.rows().length));
  }

  stormsView() {
    this.ensureStorms();
    const r = this.storms;
    const windows = [[1, "relWindow1"], [7, "relWindow7"]].map(([days, key]) => `<button class="chip ${this.stormsWindow === days ? "active" : ""}" data-storm-window="${days}" aria-pressed="${this.stormsWindow === days}">${this.t(key)}</button>`).join("");
    const aged = Boolean(r?.computed_at && (r.stale || r.age_seconds >= 60)), took = aged ? "" : this.tookNote(r).replace(/^ · /, "");
    const ready = Boolean(r?.available && !r.busy);
    if (ready) this.stormsExporter(r);
    const head = this.pageBar({ left: `${windows}${took ? `<span>${this.esc(took)}</span>` : ""}`, at: this.isoOf(r?.computed_at) || this.loadedAt("storms"), loading: this.stormsLoading, attr: "data-storm-refresh", exportId: ready ? "recload" : "" });
    if (this.stormsError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.stormsError)}</div></div></div>`;
    if (!r) return `<div class="stack">${head}<div class="panel">${this.skeleton("stormLoading")}</div></div>`;
    if (!r.available) return `<div class="stack">${head}<div class="panel"><p class="factnote">${this.t("relNoRecorder")}</p></div></div>`;
    if (r.busy) return `<div class="stack">${head}<div class="panel">${this.skeleton("relBusy")}<p class="factnote">${this.t("relBusy")}</p></div></div>`;
    const loading = this.stormsLoading ? `<p class="factnote">${this.t("stormLoading")}</p>` : "";
    const groups = this.stormGroups(r);
    const tiles = groups.length ? this.sumTiles([
      { label: this.t("stormFilterAll"), value: this.formatNumber(groups.length), tone: "mute", lf: ["stormfind", "", ""] },
      ...["storm", "no_new_state", "attribute_flood", "integration_share", "event_burst"].map(k => ({ k, n: groups.filter(g => g.items.some(f => f.kind === k)).length })).filter(x => x.n).map(x => ({ label: this.t(`stormKind_${x.k}`), value: this.formatNumber(x.n), tone: x.k === "storm" || x.k === "integration_share" ? "red" : "warn", lf: ["stormfind", "kind", x.k] })),
    ]) : "";
    const attention = groups.length ? `<p class="factnote">${this.t("stormGroupHint")}</p>${this.stormLegend(r)}${this.excludeCard([])}${this.stormGroupsList(groups)}<p class="factnote">${this.t("stormWhatToDo")}</p>` : `<div class="emptymsg">${this.t("stormNone")}</div>`;
    const days = r.window_days || 1, f = n => this.formatNumber(n);
    const stats = this.sumTiles([
      { label: this.t("stormStatRows"), value: f(r.total_rows), sub: this.esc(days > 1 ? this.t("stormSubRowsDays", { days, perDay: f(r.per_day) }) : this.t("stormSubRowsDay")), tone: "mute" },
      { label: this.t("stormStatEntities"), value: f(r.entity_count), sub: this.esc(this.t("stormSubEntities")), tone: "mute" },
      { label: this.t("stormStatEvents"), value: f(r.event_total), sub: this.esc(this.t("stormSubEvents")), tone: "mute" },
    ]);
    const entry = this.stormEntry && r.integrations.find(g => g.entry_id === this.stormEntry);
    const ofEntry = entry ? r.entities.filter(item => item.entry_id === entry.entry_id) : r.entities;
    const shownEntities = this.exOnlySug ? ofEntry.filter(item => this.excludeInfo(item.entity_id, item.per_day, item.excluded).suggest) : ofEntry;
    const entryBar = entry ? `<div class="toolbar exbar"><span class="date">${this.t("stormOnlyEntry", { title: this.esc(entry.title), shown: this.formatNumber(ofEntry.length), total: this.formatNumber(entry.entities) })}</span><button class="btn quiet" data-storm-entry-clear>${this.t("stormEntryClear")}</button></div>` : "";
    const table = r.entities.length ? `<div class="panel"><div class="panelhead"><div><h2>${this.t("stormLoudest")}</h2><p>${this.t("stormLoudestHint")}</p></div></div>${this.excludeCard(r.entities.filter(item => this.excludeInfo(item.entity_id, item.per_day, item.excluded).suggest).map(item => item.entity_id))}${entryBar}${this.stormEntitiesList(shownEntities)}</div>` : "";
    const shares = r.integrations.length ? `<div class="panel"><div class="panelhead"><div><h2>${this.t("stormShares")}</h2><p>${this.t("stormSharesHint")}</p></div></div>${this.stormSharesList(r.integrations)}</div>` : "";
    const events = r.events.length ? `<div class="panel"><div class="panelhead"><div><h2>${this.t("stormEvents")}</h2><p>${this.t("stormEventsHint")}</p></div></div>${this.stormEventsList(r)}<details class="howto"><summary>${this.t("evWhenTitle")}</summary><p class="factnote">${this.t("evWhen")}</p></details><p class="factnote">${this.t("evFoot")}</p>${this.howCounted("stormFootnote")}</div>` : "";
    const ex = r.excluded || {};
    const chips = [["ignored", "exclIgnored", "mdi:eye-off-outline"], ["disabled", "exclDisabled", "mdi:power-plug-off-outline"], ["permanent", "exclPermanent", "mdi:link-off"]].filter(([k]) => ex[k]).map(([k, key, icon]) => `<span class="exchip"><ha-icon icon="${icon}"></ha-icon>${this.esc(this.t(key, { n: this.formatNumber(ex[k]) }))}</span>`).join("");
    const left = chips ? `<div class="exchips">${chips}${this.infoTip(this.t("stormExclTip"))}</div>` : "";
    // The sections are tabs, so the lower ones are not hidden far down the page.
    const warn = r.findings.some(f => f.kind === "storm" || f.kind === "integration_share");
    const tabs = [
      { id: "findings", label: this.t("stormTabFindings"), count: groups.length, tone: warn ? "red" : groups.length ? "warn" : "ok" },
      r.entities.length ? { id: "entities", label: this.t("stormTabEntities"), count: r.entities.length } : null,
      r.integrations.length ? { id: "shares", label: this.t("stormTabIntegrations"), count: r.integrations.length } : null,
      r.events.length ? { id: "events", label: this.t("stormTabEvents"), count: r.events.length } : null,
    ].filter(Boolean);
    const open = this.viewTabOf("recload", tabs, r.findings.length ? "findings" : "entities");
    const body = open === "entities" ? table : open === "shares" ? shares : open === "events" ? events : `<div class="panel"><div class="panelhead"><div><h2>${this.t("stormTabFindings")}</h2></div></div>${attention}</div>`;
    return `<div class="stack">${head}${loading}${stats}${left}${this.viewTabBar("recload", tabs, open)}${open === "findings" ? tiles : ""}${body}</div>`;
  }
}

// DbHealthMixin: the database card in Maintenance; mixed into the panel in 99-register.js.
class DbHealthMixin {
  async loadDbHealth(refresh = false, check = false) {
    this.dbLoading = true; this.dbError = ""; this.render();
    try { this.dbHealth = await this._hass.callWS({ type: "ha_housekeeper/db_health", refresh, ...(check ? { check } : {}) }); }
    catch (err) { this.dbError = this.errText(err); }
    this.dbLoading = false; this.render();
    this.followUp("db", "recorder", this.dbHealth, r => this.loadDbHealth(r), refresh);
    // The full check runs on in the background: look again until it is done (cached reply, no new query).
    globalThis.clearTimeout?.(this._dbCheckTimer);
    if (this.dbHealth?.integrity?.running) this._dbCheckTimer = setTimeout(() => this.loadDbHealth(false), 5000);
  }

  // Loads on the first visit of Maintenance only: the query reads the recorder, so the overview never starts it.
  ensureDbHealth() {
    if (this.dbLoading || this._dbRequested) return;
    this._dbRequested = true;
    setTimeout(() => this.loadDbHealth(), 0);
  }

  dbSeriesList(series) {
    return series.map(s => this.esc(s.name || s.statistic_id)).join(", ");
  }

  dbFindingText(f) {
    const n = v => this.formatNumber(v), size = v => this.formatBytes(v);
    if (f.kind === "wal_large") return this.t("dbWal", { wal: size(f.wal_bytes), db: size(f.db_bytes) });
    if (f.kind === "growth") return this.t("dbGrowth", { recent: size(f.recent_bytes), base: size(f.base_bytes) });
    if (f.kind === "duplicates") return this.t("dbDuplicates", { n: n(f.groups), more: f.capped ? "+" : "", list: this.dbSeriesList(f.series) });
    if (f.kind === "missing_hours") {
      if (!f.gap_hours) return this.t("dbMissingOwnOnly", { n: n(f.series_total) });
      return `${this.t("dbMissingShared", { n: n(f.series_total), hours: n(f.gap_hours), count: n(f.gaps_total) })} ${f.own_series ? this.t("dbMissingOwn", { n: n(f.own_series) }) : this.t("dbMissingOnlyShared")}`;
    }
    if (f.kind === "statistics_issues") return this.t("dbIssues", { n: n(f.series_total), list: f.series.map(s => `${this.esc(s.name || s.statistic_id)} (${s.types.map(type => this.t(`dbIssue_${type}`) === `dbIssue_${type}` ? type : this.t(`dbIssue_${type}`)).join(", ")})`).join(", ") });
    if (f.kind === "disk_low") return this.t("dbDiskLow", { free: size(f.free_bytes), total: size(f.total_bytes) });
    if (f.kind === "corrupt_files") return this.t("dbCorruptFiles", { n: n(f.files), size: size(f.bytes), list: f.names.map(x => this.esc(x)).join(", ") });
    if (f.kind === "integrity") return this.t("dbIntegrity", { at: this.formatDate(f.at), lines: f.lines.map(l => this.esc(l)).join("; ") }) + (f.unclean_starts ? ` ${this.t("dbIntegrityCrash", { n: n(f.unclean_starts) })}` : "");
    return this.t("dbRecorderGap", { n: n(f.gaps), longest: this.relDuration(f.longest_seconds), latest: this.formatDate(new Date(f.latest[0].start * 1000).toISOString()) });
  }

  // What lies behind a finding: the periods all series lack, and the series with their own and their shared hours.
  dbFindingExtra(f) {
    if (f.kind !== "missing_hours" || !(f.gaps?.length || f.series?.length)) return "";
    const day = seconds => this.formatDate(new Date(seconds * 1000).toISOString());
    const gaps = f.gaps?.length ? this.sysList("dbgaps", f.gaps, {
      sort: "start", dir: "desc", tie: g => g.start, empty: "dbSeriesNone",
      sorts: [{ key: "start", label: "dbColFrom", dir: "desc", get: g => g.start }, { key: "hours", label: "dbColHours", dir: "desc", get: g => g.hours ?? 0 }],
      text: g => `${day(g.start)} ${day(g.end)} ${this.t(`dbGapCause_${g.cause}`)}`,
      columns: [
        { key: "start", label: "dbColFrom", dir: "desc", cell: g => this.esc(day(g.start)) },
        { key: "end", label: "dbColTo", sortable: false, cell: g => this.esc(day(g.end)) },
        { key: "hours", label: "dbColHours", dir: "desc", cell: g => this.esc(this.t("dbMissingHours", { n: this.formatNumber(g.hours) })) },
        { key: "cause", label: "dbColCause", sortable: false, cell: g => `<span class="pill ${g.cause === "restart" ? "mute" : "warn"}">${this.t(`dbGapCause_${g.cause}`)}</span>` },
      ],
    }) : "";
    const shared = Boolean(f.gap_hours);
    const sorts = [
      { key: "name", label: "utName", dir: "asc", get: x => x.name || x.statistic_id },
      { key: "own", label: "dbColOwn", dir: "desc", get: x => x.own ?? 0 },
      ...(shared ? [{ key: "shared", label: "dbColShared", dir: "desc", get: x => x.shared ?? 0 }] : []),
      { key: "missing", label: "dbColMissing", dir: "desc", get: x => x.missing ?? 0 },
    ];
    const num = key => x => this.formatNumber(x[key] ?? 0);
    const table = this.sysList("dbseries", f.series, {
      sort: "missing", dir: "desc", sorts, text: x => `${x.name || ""} ${x.statistic_id}`, tie: x => x.statistic_id, empty: "dbSeriesNone",
      rowAttrs: x => this.findObject(`entity:${x.statistic_id}`) ? `data-object="${this.esc(`entity:${x.statistic_id}`)}" tabindex="0" role="button"` : 'class="static"',
      columns: [
        { key: "name", label: "utName", dir: "asc", cell: x => this.nameCell(x.name || x.statistic_id, x.statistic_id) },
        { key: "own", label: "dbColOwn", dir: "desc", cell: num("own") },
        ...(shared ? [{ key: "shared", label: "dbColShared", dir: "desc", cell: num("shared") }] : []),
        { key: "missing", label: "dbColMissing", dir: "desc", cell: num("missing") },
      ],
    });
    const more = f.series_total > f.series.length ? `<p class="factnote">${this.t("relUnstableMore", { shown: f.series.length, total: f.series_total })}</p>` : "";
    return `<div class="dbextra">${gaps ? `<div class="sectionlabel">${this.t("dbGapsTitle")}</div>${gaps}` : ""}<div class="sectionlabel">${this.t("dbSeriesTitle", { n: this.formatNumber(f.series_total) })}</div>${table}${more}</div>`;
  }

  dbFindingRow(f) {
    const tone = f.level === "problem" ? "red" : "warn";
    return `<div class="row"><span class="tile ${tone}"><ha-icon icon="mdi:database-alert-outline"></ha-icon></span><span class="row-text"><strong>${this.t(`dbKind_${f.kind}`)}</strong><small>${this.dbFindingText(f)}</small><small>${this.t(`dbAdvice_${f.kind}`)}</small></span><span class="pill ${tone}">${this.t(f.level === "problem" ? "dbProblem" : "dbHint")}</span></div>${this.dbFindingExtra(f)}`;
  }

  // The full integrity check on demand: a button, and the result of the last run.
  dbCheckRow(r) {
    const c = r.integrity || {};
    const note = c.running ? this.t("dbChecking")
      : c.state === "ok" ? this.t("dbCheckOk", { at: this.formatDate(c.at) })
      : c.state === "failed" ? this.t("dbCheckFailed", { at: this.formatDate(c.at) })
      : c.state === "damaged" ? "" : this.t("dbCheckNever");
    return `<div class="row"><span class="row-text"><small>${this.esc(note)}</small><small>${this.t("dbCheckHint")}</small></span><button class="btn" data-db-check${c.running ? " disabled" : ""}>${this.t("dbCheck")}</button></div>`;
  }

  dbCard() {
    const r = this.dbHealth;
    const took = this.tookNote(r);
    const ready = Boolean(r?.available && !r.busy);
    const head = this.pageBar({ left: took ? `<span>${this.esc(took.replace(/^ · /, ""))}</span>` : "", at: this.isoOf(r?.computed_at), loading: this.dbLoading, attr: "data-db-refresh", exportId: ready && !this.dbError ? "recdb" : "" });
    if (this.dbError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.dbError)}</div></div></div>`;
    if (!r) return `<div class="stack">${head}<div class="panel">${this.skeleton("dbLoading")}</div></div>`;
    if (!r.available) return `<div class="stack">${head}<div class="panel"><p class="factnote">${this.t("relNoRecorder")}</p></div></div>`;
    if (r.busy) return `<div class="stack">${head}<div class="panel">${this.skeleton("relBusy")}<p class="factnote">${this.t("relBusy")}</p></div></div>`;
    const th = r.thresholds || {};
    const facts = [];
    if (r.supported && r.db_bytes !== null && r.db_bytes !== undefined) facts.push(this.t("dbSize", { db: this.formatBytes(r.db_bytes), wal: this.formatBytes(r.wal_bytes || 0) }));
    else facts.push(this.t("dbNoSize", { dialect: this.esc(r.dialect || "?") }));
    if (r.growth?.known) facts.push(this.t("dbPerDay", { size: this.formatBytes(Math.max(0, r.growth.per_day)) }));
    else facts.push(this.t("dbGrowthUnknown"));
    if (r.keep_days) facts.push(this.t("dbKeep", { n: this.formatNumber(r.keep_days) }));
    if (r.auto_purge === false) facts.push(this.t("dbOvPurgeOff"));
    if (r.restart_gaps) facts.push(this.t("dbRestartGaps", { n: this.formatNumber(r.restart_gaps) }));
    this.setPageExporter("recdb", "recorder-database", `${this.t("recorder")} · ${this.t("dbTitle")}`, [
      { name: "findings", title: this.t("stormTabFindings"), header: [this.t("stormColKinds"), this.t("expColLevel"), this.t("expColText"), this.t("expColAdvice")], rows: () => r.findings.map(f => [this.t(`dbKind_${f.kind}`), this.t(f.level === "problem" ? "dbProblem" : "dbHint"), this.plainText(this.dbFindingText(f)), this.t(`dbAdvice_${f.kind}`)]) },
      { name: "facts", title: this.t("expColFact"), header: [this.t("expColFact")], rows: () => facts.map(x => [this.plainText(x)]) },
    ].filter(sec => sec.rows().length));
    const rows = r.findings.length ? r.findings.map(f => this.dbFindingRow(f)).join("") : `<div class="emptymsg"><ha-icon icon="mdi:check-circle-outline"></ha-icon>${this.t("dbNone")}</div>`;
    return `<div class="stack">${head}<div class="panel">${rows}${this.dbCheckRow(r)}<p class="factnote">${facts.join(" · ")}</p>${this.howCounted("dbFootnote", { gap: th.state_gap_minutes ?? 10, gapDays: th.state_gap_window_days ?? 7, missing: th.gap_min_hours ?? 6, missingDays: th.gap_window_days ?? 30 })}</div></div>`;
  }
}

// ExposureMixin: which entities assistants and bridges can reach; mixed into the panel in 99-register.js.
const EXPO_DOMAIN_ICONS = {
  light: "mdi:lightbulb-outline", switch: "mdi:toggle-switch-outline", sensor: "mdi:eye-outline", binary_sensor: "mdi:radiobox-marked", climate: "mdi:thermostat",
  cover: "mdi:window-shutter", media_player: "mdi:play-box-outline", lock: "mdi:lock-outline", fan: "mdi:fan", scene: "mdi:palette-outline", script: "mdi:script-text-outline",
  automation: "mdi:robot-outline", input_boolean: "mdi:toggle-switch-variant-outline", button: "mdi:gesture-tap-button", camera: "mdi:cctv", vacuum: "mdi:robot-vacuum",
  humidifier: "mdi:air-humidifier", water_heater: "mdi:water-boiler", alarm_control_panel: "mdi:shield-home-outline", number: "mdi:numeric", select: "mdi:format-list-bulleted",
  weather: "mdi:weather-partly-cloudy", remote: "mdi:remote", valve: "mdi:valve", siren: "mdi:bullhorn-outline", todo: "mdi:clipboard-list-outline", person: "mdi:account-outline",
};

class ExposureMixin {
  async loadExposure() {
    this.exposureLoading = true; this.exposureError = ""; this.render();
    try { this.exposure = await this._hass.callWS({ type: "ha_housekeeper/exposure" }); this.exposureAt = new Date().toISOString(); }
    catch (err) { this.exposureError = this.errText(err); }
    this.exposureLoading = false; this.render();
  }

  // Loads on the first visit; a refresh button reloads. The query is cheap and only reads registries.
  ensureExposure() {
    if (this.exposureLoading || this._exposureRequested) return;
    this._exposureRequested = true;
    setTimeout(() => this.loadExposure(), 0);
  }

  // The tile of an entity row: the symbol of its domain, so the row reads as an entity and not as something that unfolds.
  expoTile(entityId, tone = "mute") {
    const icon = EXPO_DOMAIN_ICONS[String(entityId).split(".")[0]] || ICONS.entity;
    return `<span class="tile ${tone}"><ha-icon icon="${icon}"></ha-icon></span>`;
  }

  expoAssistantName(id) {
    return this.t(`expoName_${id.replace(/\./g, "_")}`);
  }

  expoAssistantList(ids) {
    return (ids || []).map(id => this.expoAssistantName(id)).join(", ");
  }

  expoFindingText(f) {
    return this.t(`expoText_${f.kind}`, { n: this.formatNumber(f.count), alias: f.alias || "", assistant: f.assistant ? this.expoAssistantName(f.assistant) : "", domain: f.domain || "" });
  }

  // One finding as a fold: the head always shows, the entities (a table of their own, with search, sorting and pages) and the advice only when open.
  expoFindingRows(f) {
    const tone = f.level === "warn" ? "warn" : "mute";
    const items = (f.items || []).map(item => {
      const obj = this.findObject(`entity:${item.entity_id}`);
      return { ...item, domain: item.entity_id.split(".")[0], area: obj ? this.areaName(obj) : "" };
    });
    const table = items.length ? this.sysList(`expofind_${f.kind}`, items, {
      sort: "name", tie: item => item.entity_id, empty: "expoNone",
      sorts: [
        { key: "name", label: "expoColName", dir: "asc", get: item => item.name || item.entity_id },
        { key: "domain", label: "expoColDomain", dir: "asc", get: item => item.domain },
        { key: "area", label: "expoColArea", dir: "asc", get: item => item.area },
      ],
      text: item => [item.name, item.entity_id, item.area, ...(item.assistants || [])].join(" "),
      rowAttrs: item => `data-object="entity:${this.esc(item.entity_id)}" tabindex="0" role="button" aria-label="${this.esc(item.name || item.entity_id)}"`,
      columns: [
        { key: "name", label: "expoColName", dir: "asc", cell: item => `<div class="statcell">${this.expoTile(item.entity_id)}<div>${this.nameCell(item.name || item.entity_id, item.entity_id)}</div></div>` },
        { key: "domain", label: "expoColDomain", dir: "asc", cell: item => this.esc(item.domain) },
        { key: "area", label: "expoColArea", dir: "asc", cell: item => (item.area ? this.esc(item.area) : `<span class="muted">—</span>`) },
        { key: "assistants", label: "expoColAssistants", sortable: false, cell: item => (item.assistants?.length ? this.esc(this.expoAssistantList(item.assistants)) : `<span class="muted">—</span>`) },
      ],
    }) : "";
    const more = f.count > items.length ? `<p class="factnote">${this.t("expoMore", { n: this.formatNumber(f.count - items.length) })}</p>` : "";
    const body = `<p class="factnote foldadvice">${this.t(`expoAdvice_${f.kind}`)}</p>${table}${more}`;
    const head = { tone, title: this.t(`expoKind_${f.kind}`), sub: this.expoFindingText(f), pill: this.t(f.level === "warn" ? "expoWarn" : "expoHint2") };
    return this.fold(`expo_${f.kind}`, head, body, false);
  }

  expoSection(titleKey, list) {
    return list.length ? `<h3 class="expohd">${this.t(titleKey)}</h3>${list.map(f => this.expoFindingRows(f)).join("")}` : "";
  }

  // Voice assistants and bridges as one list: id, name, state and how many entities each one reaches.
  expoSources(r) {
    const list = r.assistants.map(a => ({ id: a.id, label: this.expoAssistantName(a.id), status: a.status, count: a.exposed }));
    const kinds = {};
    for (const b of r.bridges) {
      const kind = (kinds[b.kind] ||= { id: b.kind, label: this.expoAssistantName(b.kind), status: "ok", count: 0, titles: [] });
      kind.count += b.exposed; kind.titles.push(b.title);
    }
    return [...list, ...Object.values(kinds)];
  }

  // The entities one assistant or bridge can reach, as a table: sortable, filterable by domain and by the other assistants; a row opens the entity.
  expoSourceTab(r, source) {
    const id = `expo_${source.id}`;
    const all = (r.exposed_entities || []).filter(e => e.assistants.includes(source.id)).map(e => {
      const obj = this.findObject(`entity:${e.entity_id}`);
      return { ...e, domain: e.entity_id.split(".")[0], area: obj ? this.areaName(obj) : "", others: e.assistants.filter(x => x !== source.id) };
    });
    this.lvState(id, "name", "asc");
    const domains = [...new Set(all.map(e => e.domain))].sort();
    const others = [...new Set(all.flatMap(e => e.others))].sort();
    const sorts = [
      { key: "name", label: "expoColName", dir: "asc", get: e => e.name },
      { key: "domain", label: "expoColDomain", dir: "asc", get: e => e.domain },
      { key: "area", label: "expoColArea", dir: "asc", get: e => e.area },
      { key: "also", label: "expoColAlso", dir: "desc", get: e => e.others.length },
    ];
    const bar = all.length ? this.listBar(id, { table: true, dense: true, sorts, filters: [
      { name: "domain", all: this.t("expoAllDomains"), options: domains.map(d => [d, d]) },
      ...(others.length ? [{ name: "also", all: this.t("expoAllAlso"), options: others.map(o => [o, this.expoAssistantName(o)]) }] : []),
    ] }) : "";
    const rows = all.length ? this.refine(id, all, { text: e => [e.name, e.entity_id, e.area].join(" "), filters: { domain: (e, v) => e.domain === v, also: (e, v) => e.others.includes(v) }, sorts, tie: e => e.entity_id }) : [];
    const pg = this.paginate(id, rows);
    const columns = [
      { key: "name", label: "expoColName", dir: "asc", cell: e => `<div class="statcell">${this.expoTile(e.entity_id)}<div>${this.nameCell(e.name, e.entity_id)}</div></div>` },
      { key: "domain", label: "expoColDomain", dir: "asc", cell: e => this.esc(e.domain) },
      { key: "area", label: "expoColArea", dir: "asc", cell: e => e.area ? this.esc(e.area) : `<span class="muted">—</span>` },
      { key: "also", label: "expoColAlso", dir: "desc", cell: e => e.others.length ? this.esc(this.expoAssistantList(e.others)) : `<span class="muted">—</span>` },
    ];
    const table = rows.length ? this.listTable(id, columns, pg.rows, { cls: "expo", rowAttrs: e => `data-object="entity:${this.esc(e.entity_id)}" tabindex="0" role="button" aria-label="${this.esc(e.name)}"` }) : "";
    const none = all.length && !rows.length ? `<div class="emptymsg">${this.noMatches(id)}</div>` : "";
    const where = source.titles?.length ? ` (${this.esc(source.titles.join(", "))})` : "";
    const capped = r.exposed_total > (r.exposed_entities || []).length ? `<p class="factnote">${this.t("expoCapped", { n: this.formatNumber(r.exposed_entities.length) })}</p>` : "";
    const empty = all.length ? "" : `<div class="emptymsg">${this.t(source.status === "inactive" ? "expoInactiveText" : "expoNoneFor")}</div>`;
    return `<div class="panel"><div class="panelhead"><div><h2>${this.esc(source.label)}${where}</h2><p>${this.t("expoSourceHint", { n: this.formatNumber(source.count), name: this.esc(source.label) })}</p></div></div>${bar}${none}${empty}${table}${pg.footer}${capped}</div>`;
  }

  exposureView() {
    this.ensureExposure();
    const r = this.exposure;
    const head = this.pageBar({ at: this.exposureAt, loading: this.exposureLoading, attr: "data-expo-refresh" });
    if (this.exposureError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.exposureError)}</div></div></div>`;
    if (!r) return `<div class="stack">${head}<div class="panel">${this.skeleton("expoLoading")}</div></div>`;
    const sources = this.expoSources(r);
    const live = sources.filter(x => x.status === "ok");
    const warn = r.findings.filter(f => f.level === "warn").length;
    const tabs = [
      { id: "findings", icon: "mdi:shield-alert-outline", label: this.t("expoTabFindings"), hint: this.t("expoTileFindingsHint"), count: r.findings.length, tone: warn ? "warn" : "ok" },
      ...sources.map(x => x.status === "ok"
        ? { id: x.id, icon: "mdi:microphone-outline", label: x.label, hint: this.t("expoTileSourceHint", { n: this.formatNumber(x.count) }), count: x.count, tone: "ok" }
        : { id: x.id, icon: "mdi:microphone-off", label: x.label, hint: this.t(x.status === "inactive" ? "expoInactive" : "expoUnavailable"), disabled: true }),
    ];
    const open = this.viewTabOf("exposure", tabs.filter(x => !x.disabled), r.findings.length || !live.length ? "findings" : live[0].id);
    let body;
    if (open === "findings") {
      const rows = r.findings.length ? this.expoSection("expoToCheck", r.findings.filter(f => f.level === "warn")) + this.expoSection("expoToNote", r.findings.filter(f => f.level !== "warn")) : `<div class="emptymsg"><ha-icon icon="mdi:check-circle-outline"></ha-icon>${this.t("expoNone")}</div>`;
      body = `<div class="panel">${rows}${this.howCounted("expoFootnote")}</div>`;
    } else body = this.expoSourceTab(r, sources.find(x => x.id === open));
    return `<div class="stack">${head}${this.navTiles("exposure", tabs, open, this.t("exposure"), true)}${body}</div>`;
  }
}

// SearchPagesMixin: the top-bar search finds pages, settings tabs and finding filters, not only objects.
// The words are German and English together, so a page is found in either language. Mixed into the panel in 99-register.js.
Object.assign(TEXT.de, { quickGroupPages: "Seiten", quickGroupFilters: "Filter", quickGroupObjects: "Objekte", quickFilterHint: "Liste filtern" });
Object.assign(TEXT.en, { quickGroupPages: "Pages", quickGroupFilters: "Filters", quickGroupObjects: "Objects", quickFilterHint: "Filter the list" });

const SEARCH_WORDS = {
  overview: "start home status gesundheit zustand health",
  findingsNav: "befunde probleme fehler hinweise findings problems issues",
  cleanup: "aufräumen bereinigen löschen entfernen quarantäne cleanup delete remove quarantine",
  repair: "reparieren zähler umziehen ersetzen austauschen repair counter meter replace exchange",
  journal: "journal pläne rückgängig verlauf plans undo history",
  maintenance: "wartung backup sicherung wiederherstellung update ziele maintenance restore goals",
  batteries: "batterien batterie akku schwach batteries battery low",
  reminders: "erinnerungen wartung filter reminders due",
  policies: "richtlinien regeln policies rules",
  reliability: "zuverlässigkeit ausfälle instabil reliability outages unstable",
  runs: "läufe automationen ausführungen runs automations traces",
  recorder: "recorder datenbank statistik größe database statistics size",
  storage: "speicher system festplatte arbeitsspeicher cpu storage disk memory",
  exposure: "freigabe assist sprachassistent exposure voice",
  dataflow: "zugriff datenfluss webhook zugang access data flow",
  secrets: "zugangsdaten passwörter schlüssel geheimnisse credentials secrets tokens passwords",
  inventory: "bestand objekte entitäten geräte inventory objects entities devices",
  components: "komponenten integrationen apps add-ons components integrations",
  graph: "abhängigkeiten beziehungen netz graph dependencies relations",
  changes: "änderungen vergleich scan-vergleich logbuch changes compare logbook",
  settings: "einstellungen optionen konfiguration settings options preferences",
  look: "darstellung theme dunkel hell schrift farbe appearance dark light font",
  protection: "schutz schutzmodus sicherheit ausgeblendet ignoriert ausnahmen protection mode hidden ignored exceptions",
  scan: "scan schwellen intervall tage benachrichtigung meldung ereignisse threshold interval notification message events",
  goals: "ziele goals",
  info: "info version speichert daten diagnose prüfung quellen dauer about stored diagnostics coverage timing",
  compare: "scan-vergleich verlauf vergleich scans history compare",
  logbook: "logbuch notizen logbook notes",
};
// What a person may type for a finding status, besides its label.
const SEARCH_STATE_WORDS = {
  "": "offen open", new: "neu new", inwork: "in arbeit work", known: "bekannt behalten known keep",
  snoozed: "später zurückgestellt snoozed later", hidden: "ausgeblendet ignoriert hidden ignored", fixed: "behoben repariert fixed repaired",
};
const SEARCH_PAGE_LIMIT = 5, SEARCH_FILTER_LIMIT = 5;

class SearchPagesMixin {
  // Every page of the menu, the tabs of Settings and of Changes, as { view, tab?, label, path, words }.
  searchPages() {
    const pages = [];
    for (const [group, views] of NAV_GROUPS) {
      for (const view of views) pages.push({ view, label: this.t(view), path: group === NAV_GROUPS[0][0] ? "" : this.t(group), words: SEARCH_WORDS[view] || "" });
    }
    pages.push({ view: "settings", label: this.t("settings"), path: "", words: SEARCH_WORDS.settings });
    for (const [id, , labelKey] of this.settingsTabs()) pages.push({ view: "settings", settingsTab: id, label: this.t(labelKey), path: this.t("settings"), words: SEARCH_WORDS[id] || "" });
    pages.push({ view: "maintenance", viewTab: "goals", label: this.t("goalsTitle"), path: this.t("maintenance"), words: SEARCH_WORDS.goals });
    pages.push({ view: "changes", viewTab: "compare", label: this.t("tabScans"), path: this.t("changes"), words: SEARCH_WORDS.compare });
    pages.push({ view: "changes", viewTab: "logbook", label: this.t("logbook"), path: this.t("changes"), words: SEARCH_WORDS.logbook });
    return pages;
  }

  // The filters a person could set by hand: a status of the findings and a status of the objects, with how many each shows.
  searchFilters() {
    const filters = [];
    const states = ["", "new", "inwork", "known", "snoozed", "hidden", "fixed"];
    for (const state of states) {
      const count = state === "" ? this.findingTotal() : state === "fixed" ? this.doneCount() : this.statusCount(state);
      if (count) filters.push({ findingStatus: state, label: `${this.t("findingsNav")}: ${this.t(state === "" ? "stateOpen" : `state_${state}`)}`, count, words: SEARCH_STATE_WORDS[state] });
    }
    for (const [status, count] of Object.entries(this.data?.meta?.status_counts || {})) {
      if (count && status !== "active") filters.push({ objectStatus: status, label: `${this.t("inventory")}: ${this.t(status)}`, count, words: `${status} ${SEARCH_WORDS.inventory}` });
    }
    return filters;
  }

  // Matching entries of one list, best first: the label starts with the first word, contains it, or only the extra words do.
  searchMatch(list, query, limit) {
    const terms = String(query).toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    const found = [];
    for (const entry of list) {
      const label = String(entry.label).toLowerCase(), hay = `${label} ${String(entry.path || "").toLowerCase()} ${entry.words || ""}`;
      if (terms.every(term => hay.includes(term))) found.push({ entry, rank: label.startsWith(terms[0]) ? 0 : label.includes(terms[0]) ? 1 : 2 });
    }
    return found.sort((a, b) => a.rank - b.rank).slice(0, limit).map(f => ({ ...f.entry, rank: f.rank }));
  }

  // The list the search box shows and the keyboard walks: pages and filters (the better matching block first), then objects.
  quickEntries() {
    const query = this.quickQuery;
    if (query.trim().length < 2) return [];
    const pages = this.searchMatch(this.searchPages(), query, SEARCH_PAGE_LIMIT).map(e => ({ ...e, kind: "page" }));
    const filters = this.searchMatch(this.searchFilters(), query, SEARCH_FILTER_LIMIT).map(e => ({ ...e, kind: "filter" }));
    const objects = this.quickResults().map(item => ({ kind: "object", item }));
    const filtersFirst = filters.length && (!pages.length || filters[0].rank < pages[0].rank);
    return [...(filtersFirst ? [...filters, ...pages] : [...pages, ...filters]), ...objects];
  }

  quickGo(entry) {
    if (entry.kind === "object") return this.quickPick(this.objectKey(entry.item));
    this.quickQuery = ""; this.quickOpen = false; this.quickIndex = 0; this.menuOpen = null; this.navOpen = false;
    const view = entry.kind === "filter" ? (entry.objectStatus ? "inventory" : "findingsNav") : entry.view;
    if (view !== this.view) this.noteJump(view);
    this.view = view; this.pages = {}; this.selected = null; this.trail = []; this.graphTrail = []; this.graphOrigin = null;
    if (entry.settingsTab) this.settingsTab = entry.settingsTab;
    if (entry.viewTab) (this.viewTab ||= {})[view] = entry.viewTab;
    if (entry.kind === "filter" && entry.objectStatus) { this.statusFilter = entry.objectStatus; this.typeFilter = ""; this.originFilter = ""; }
    if (entry.kind === "filter" && !entry.objectStatus) {
      const fresh = FRESH_STATES.includes(entry.findingStatus);
      this.findingStatus = fresh ? "" : entry.findingStatus;
      if (fresh) this.lvState("findings", "impact", "desc").f.fresh = entry.findingStatus;
    }
    this.render();
    if (view === "changes" && !this.compare) this.loadCompare();
  }
}

// SearchMixin: one search box in the top bar for entities, devices, integrations, automations and scripts.
const QUICK_TYPES = ["entity", "device", "config_entry", "automation", "script"];
const QUICK_LIMIT = 12;

class SearchMixin {
  // The one object search: every word must occur in the name, the id, the integration, the maker or the model; names that
  // start with the first word come first. The top bar, the dependency path and the sensor fields all use it.
  searchObjects(query, { types = QUICK_TYPES, limit = QUICK_LIMIT, filter = null } = {}) {
    const terms = String(query).toLowerCase().split(/\s+/).filter(Boolean);
    if (!this.data || !terms.length) return [];
    const found = [];
    for (const item of this.data.objects) {
      if ((types && !types.includes(item.object_type)) || (filter && !filter(item))) continue;
      const name = String(item.name || "").toLowerCase();
      const hay = `${name} ${String(item.object_id).toLowerCase()} ${String(item.platform || item.domain || "").toLowerCase()} ${String(item.manufacturer || "").toLowerCase()} ${String(item.model || "").toLowerCase()}`;
      if (!terms.every(term => hay.includes(term))) continue;
      found.push({ item, rank: name.startsWith(terms[0]) ? 0 : name.includes(terms[0]) ? 1 : 2 });
    }
    const order = types || QUICK_TYPES;
    found.sort((a, b) => a.rank - b.rank || order.indexOf(a.item.object_type) - order.indexOf(b.item.object_type) || String(a.item.name).localeCompare(String(b.item.name)));
    return found.slice(0, limit).map(entry => entry.item);
  }

  quickResults() {
    return this.quickQuery.trim().length < 2 ? [] : this.searchObjects(this.quickQuery);
  }

  quickSearchBox() {
    if (!this.data) return "";
    const entries = this.quickOpen ? this.quickEntries() : [];
    const active = Math.min(this.quickIndex, Math.max(entries.length - 1, 0));
    let heading = "";
    const rows = entries.map((entry, i) => {
      const group = entry.kind === "object" ? "quickGroupObjects" : entry.kind === "filter" ? "quickGroupFilters" : "quickGroupPages";
      const head = group !== heading ? `<li class="grp" role="presentation">${this.t(group)}</li>` : "";
      heading = group;
      const attrs = `role="option" id="quick-opt-${i}" aria-selected="${i === active}" data-quick-entry="${i}" class="${i === active ? "on" : ""}"`;
      if (entry.kind === "object") {
        const item = entry.item;
        return `${head}<li ${attrs}>${this.tile(item.object_type)}<span class="row-text"><strong>${this.esc(item.name)}</strong><small>${this.esc(this.t(item.object_type))} · ${this.esc(item.object_id)}</small></span></li>`;
      }
      const icon = entry.kind === "filter" ? "mdi:filter-outline" : NAV_ICONS[entry.view] || "mdi:compass-outline";
      const note = entry.kind === "filter" ? `${this.t("quickFilterHint")} · ${this.formatNumber(entry.count)}` : entry.path;
      return `${head}<li ${attrs}><span class="tile mute"><ha-icon icon="${icon}"></ha-icon></span><span class="row-text"><strong>${this.esc(entry.label)}</strong>${note ? `<small>${this.esc(note)}</small>` : ""}</span></li>`;
    }).join("");
    const list = this.quickOpen && this.quickQuery.trim().length >= 2
      ? `<ul class="quicklist" id="quick-list" role="listbox" aria-label="${this.esc(this.t("quickLabel"))}">${entries.length ? rows : `<li class="none">${this.t("quickNone")}</li>`}</ul>` : "";
    return `<div class="quick"><ha-icon icon="mdi:magnify"></ha-icon><input type="search" data-quick autocomplete="off" role="combobox" aria-expanded="${Boolean(list)}" aria-controls="quick-list" aria-autocomplete="list" ${list && entries.length ? `aria-activedescendant="quick-opt-${active}"` : ""} placeholder="${this.esc(this.t("quickPlaceholder"))}" aria-label="${this.esc(this.t("quickLabel"))}" value="${this.esc(this.quickQuery)}">${list}</div>`;
  }

  quickPick(key) {
    const obj = this.findObject(key);
    if (!obj) return;
    this.quickQuery = ""; this.quickOpen = false; this.quickIndex = 0; this.menuOpen = null; this.navOpen = false;
    this.openObject(obj);
  }

  bindQuick(root) {
    const input = root.querySelector("[data-quick]");
    if (input) {
      input.oninput = () => { this.quickQuery = input.value; this.quickOpen = true; this.quickIndex = 0; this.scheduleRender(); };
      input.onfocus = () => { if (this.quickQuery && !this.quickOpen) { this.quickOpen = true; this.render(); } };
      input.onkeydown = ev => {
        const results = this.quickEntries();
        if (ev.key === "ArrowDown" || ev.key === "ArrowUp") {
          if (!results.length) return;
          ev.preventDefault();
          this.quickOpen = true;
          this.quickIndex = (this.quickIndex + (ev.key === "ArrowDown" ? 1 : results.length - 1)) % results.length;
          this.render();
        } else if (ev.key === "Enter" && results.length) {
          ev.preventDefault();
          this.quickGo(results[Math.min(this.quickIndex, results.length - 1)]);
        } else if (ev.key === "Escape" && (this.quickOpen || this.quickQuery)) {
          ev.stopPropagation();
          this.quickQuery = ""; this.quickOpen = false; this.render();
        }
      };
    }
    root.querySelectorAll("[data-quick-entry]").forEach(el => el.onclick = () => { const entry = this.quickEntries()[Number(el.dataset.quickEntry)]; if (entry) this.quickGo(entry); });
    if (!this._quickBound && root.addEventListener) {
      this._quickBound = true;
      root.addEventListener("click", ev => {
        if (!this.quickOpen || (ev.composedPath?.() || []).some(node => node.classList?.contains?.("quick"))) return;
        this.quickOpen = false; this.render();
      });
    }
  }
}

// PoliciesMixin: quality rules you switch on and the objects that break them; mixed into the panel in 99-register.js.
class PoliciesMixin {
  async loadPolicies() {
    this.policiesLoading = true; this.policiesError = ""; this.render();
    try { this.policies = await this._hass.callWS({ type: "ha_housekeeper/policies" }); this.policiesAt = new Date().toISOString(); }
    catch (err) { this.policiesError = this.errText(err); }
    this.policiesLoading = false; this.render();
  }

  // Loads on the first visit; the answer is computed from the last scan and needs no recorder.
  ensurePolicies() {
    if (this.policiesLoading || this._policiesRequested) return;
    this._policiesRequested = true;
    setTimeout(() => this.loadPolicies(), 0);
  }

  async changePolicy(call) {
    try { await this._hass.callWS(call); }
    catch (err) { this.policiesError = this.errText(err); }
    await this.loadPolicies();
  }

  addPolicyPrefix(domain, prefix) {
    domain = (domain || "").trim(); prefix = (prefix || "").trim();
    if (!domain || !prefix) return Promise.resolve();
    return this.changePolicy({ type: "ha_housekeeper/set_policy_prefix", domain, prefix });
  }

  removePolicyPrefix(domain) {
    return this.changePolicy({ type: "ha_housekeeper/set_policy_prefix", domain, prefix: "" });
  }

  polItemNote(item) {
    if (item.keep_days !== undefined) return `<small>${this.esc(this.t("polRetention", { days: item.keep_days, size: this.formatBytes(item.db_bytes) }))}</small>`;
    if (item.also?.length) return `<small>${this.esc(this.t(TEXT[this.lang]?.[`polAlso_${item.rule}`] ? `polAlso_${item.rule}` : "polAlso", { ids: item.also.join(", ") }))}</small>`;
    if (item.idle_days !== undefined) return `<small>${this.esc(this.t("polIdle", { n: this.formatNumber(item.idle_days) }))}</small>`;
    if (item.days !== undefined) return `<small>${this.esc(this.t("polDays", { n: this.formatNumber(item.days) }))}</small>`;
    if (item.rate !== undefined) return `<small>${this.esc(this.t("polRate", { n: this.formatNumber(item.rate) }))}</small>`;
    if (item.expected) return `<small>${this.esc(this.t("polExpected", { prefix: item.expected }))}</small>`;
    return "";
  }

  // The prefix of each domain for the naming scheme: a row per prefix with a remove button, and a small form to add one.
  polPrefixEditor() {
    const entries = Object.entries(this.policies?.prefixes || {});
    const rows = entries.map(([domain, prefix]) => `<div class="row politem"><span class="tile mute"><ha-icon icon="mdi:format-letter-starts-with"></ha-icon></span><span class="row-text"><strong>${this.esc(domain)}</strong><small>${this.esc(this.t("polPrefixIs", { prefix }))}</small></span><button class="btn" data-policy-prefix-remove="${this.esc(domain)}">${this.t("polPrefixRemove")}</button></div>`).join("");
    const form = `<div class="row politem polform"><label class="sr-only" for="polDomain">${this.t("polPrefixDomain")}</label><input id="polDomain" type="text" placeholder="${this.esc(this.t("polPrefixDomain"))}" autocomplete="off" maxlength="40"><label class="sr-only" for="polPrefix">${this.t("polPrefixValue")}</label><input id="polPrefix" type="text" placeholder="${this.esc(this.t("polPrefixValue"))}" autocomplete="off" maxlength="30"><button class="btn" data-policy-prefix-add>${this.t("polPrefixAdd")}</button></div>`;
    return `${rows}${form}${entries.length ? "" : `<p class="factnote">${this.t("polPrefixNone")}</p>`}`;
  }

  // The daily limit of the state-changes rule and, while the load numbers are missing, why the rule shows nothing.
  polLimitEditor(rule) {
    const note = rule.pending ? `<p class="factnote">${this.t("polPending")}</p>` : "";
    return `<div class="row politem polform"><label for="polLimit">${this.t("polLimit")}</label><input id="polLimit" type="number" min="100" max="100000" step="100" value="${this.esc(String(this.policies?.limit ?? 5000))}"><button class="btn" data-policy-limit-save>${this.t("polLimitSave")}</button></div>${note}`;
  }

  setPolicyLimit(value) {
    const limit = Number.parseInt(value, 10);
    if (!Number.isFinite(limit)) return Promise.resolve();
    return this.changePolicy({ type: "ha_housekeeper/set_policy_limit", limit });
  }

  // The pieces of a violation that the compact row (the object's own page) and the table of the policies page share.
  polItemParts(item) {
    const pill = item.ignored ? `<span class="pill mute">${this.t(item.by === "label" ? "polByLabel" : "polHiddenLabel")}</span>` : "";
    const due = item.resurfaced ? `<span class="pill warn">${this.t("dueLabel")}</span>` : "";
    const button = item.by === "label" ? ""
      : item.ignored ? `<button class="btn" data-policy-ignore="${this.esc(item.key)}" data-policy-value="0">${this.t("polShow")}</button>`
      : `<button class="btn" data-decide-open="${this.esc(item.key)}">${this.t("polHide")}</button>`;
    const decision = item.ignored && item.by === "user" ? `<small>${this.esc(this.decisionLabel(item))}</small>` : "";
    const form = this.decide?.key === item.key ? this.decideForm(item) : "";
    const open = this.polIsOpen(item), main = this.polMainAction(item);
    // A row with a fix offers it as its button (it folds the row open); the other rows keep their hide button; an opened row has it next to "open object".
    const act = open ? "" : main ? `<button class="btn" data-pol-open="${this.esc(item.key)}">${this.t(main)}</button>` : button;
    return { pill, due, button, decision, form, open, act };
  }

  // The compact row of the object's own page: the violation with its note and fix, no table around it.
  polItemRow(item) {
    const { pill, due, button, decision, form, open, act } = this.polItemParts(item);
    const chev = this.expandBtn("data-pol-open", item.key, open, this.t(open ? "polCloseRow" : "polOpenRow"));
    const detail = open ? this.polDetail(item, button) : "";
    return `<div class="row politem${open ? " open" : ""}" data-pol-row="${this.esc(item.key)}">${chev}<span class="row-text"><strong>${this.esc(item.name)}</strong>${this.rowId(item.object_id, item.rule ? this.t(`polRule_${item.rule}`) : "")}${this.polItemNote(item)}${decision}${detail}</span>${due}${pill}${act}</div>${form}`;
  }

  // The violations of one object, on its overview: the same rows as in the policies view, so a fix can be made here.
  // Nothing at all when the object breaks no rule (or the rules are not loaded yet); hidden violations stay out.
  polObjectCard(item) {
    this.ensurePolicies();
    const items = (this.policies?.rules || []).filter(rule => rule.enabled)
      .flatMap(rule => rule.items.map(i => ({ ...i, rule: rule.id })))
      .filter(i => !i.ignored && i.object_type === item.object_type && i.object_id === item.object_id);
    if (!items.length) return "";
    const title = this.t(items.length === 1 ? "polObjTitleOne" : "polObjTitle", { n: this.formatNumber(items.length) });
    return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2><p>${this.t("polObjHint")}</p></div><div class="actions"><button class="btn" data-view="policies">${this.t("polObjAll")}</button></div></div>${items.map(i => this.polItemRow(i)).join("")}</section>`;
  }

  // One rule on the "Rules" tab: what it checks, how many violations, and its switch.
  polRuleBlock(rule) {
    const state = !rule.enabled ? this.t("polOff") : rule.count === 1 ? this.t("polCountOne") : rule.count ? this.t("polCount", { n: this.formatNumber(rule.count) }) : this.t("polNone");
    const tone = !rule.enabled ? "mute" : rule.count ? "warn" : "ok";
    const toggle = `<input class="policyswitch" type="checkbox" role="switch" aria-label="${this.esc(this.t(`polRule_${rule.id}`))}" data-policy-toggle="${rule.id}" ${rule.enabled ? "checked" : ""}>`;
    const head = `<div class="row"><span class="tile ${tone}"><ha-icon icon="mdi:clipboard-check-outline"></ha-icon></span><span class="row-text"><strong>${this.t(`polRule_${rule.id}`)}</strong><small>${this.t(`polDesc_${rule.id}`)}</small></span><span class="pill ${tone}">${this.esc(state)}</span>${toggle}</div>`;
    const wait = rule.pending && rule.id !== "state_rate" ? `<p class="factnote">${this.t(rule.id === "recorder_retention" ? "polPendingDb" : "polPendingLoad")}</p>` : "";
    const extra = (rule.enabled && rule.id === "naming_scheme" ? this.polPrefixEditor() : rule.enabled && rule.id === "state_rate" ? this.polLimitEditor(rule) : "") + wait;
    return head + extra;
  }

  // The box in the table head: all rows of the page that can be picked.
  polHeadBox() {
    const ids = this._polPage || [];
    if (!ids.length) return "";
    const n = ids.filter(id => this.polSel?.has(id)).length;
    return `<input type="checkbox" class="selbox" data-pol-page ${n === ids.length ? "checked" : ""} ${n && n < ids.length ? "data-partial" : ""} aria-label="${this.esc(this.t("selectPage"))}">`;
  }

  // The violations of all switched-on rules as one table: filter by rule, search, sort, open a row for the fix.
  polViolations(r) {
    const on = r.rules.filter(rule => rule.enabled);
    if (!on.length) return `<div class="panel"><div class="emptymsg"><ha-icon icon="mdi:toggle-switch-off-outline"></ha-icon>${this.t("polNoneOn")}</div></div>`;
    const id = "polviol";
    this.lvState(id, "name", "asc");
    const ruleName = item => this.t(`polRule_${item.rule}`);
    const sorts = [
      { key: "name", label: "sortName", dir: "asc", get: item => item.name },
      { key: "rule", label: "polColRule", dir: "asc", get: ruleName },
      { key: "status", label: "sortStatus", dir: "asc", get: item => (item.ignored ? 2 : item.resurfaced ? 0 : 1) },
    ];
    const bar = this.listBar(id, { table: true, dense: true, sorts, filters: [{ name: "rule", all: this.t("polAllRules"), options: on.map(rule => [rule.id, `${this.t(`polRule_${rule.id}`)} (${this.formatNumber(rule.count)})`]) }] });
    const items = on.flatMap(rule => rule.items.map(item => ({ ...item, rule: rule.id }))).filter(item => this.policyShowHidden || !item.ignored);
    const shown = this.refine(id, items, { text: item => [item.name, item.object_id, ...(item.also || [])].join(" "), filters: { rule: (item, v) => item.rule === v }, sorts, tie: item => item.key });
    const pg = this.paginate(id, shown);
    this._polPage = pg.rows.filter(i => !i.ignored && ["entity", "device"].includes(i.object_type)).map(i => i.key);
    const columns = [
      { key: "sel", label: "selectPage", narrow: true, sortable: false, allBox: () => this.polHeadBox(), cell: item => this.polSelBox(item) },
      { key: "name", label: "sortName", dir: "asc", cell: item => {
        const { open } = this.polItemParts(item);
        const name = this.nameCell(item.name, item.object_id, "span");
        const link = ["recorder", "system", "user"].includes(item.object_type) ? name : `<button class="linklike" data-object="${this.esc(`${item.object_type}:${item.object_id}`)}">${name}</button>`;
        return `<div class="statcell">${this.expandBtn("data-pol-open", item.key, open, this.t(open ? "polCloseRow" : "polOpenRow"))}<div>${link}</div></div>`;
      } },
      { key: "rule", label: "polColRule", dir: "asc", cell: item => this.esc(ruleName(item)) },
      { key: "note", label: "polColNote", sortable: false, cell: item => `${this.polItemNote(item)}${this.polItemParts(item).decision}` || "—" },
      { key: "status", label: "sortStatus", dir: "asc", cell: item => { const { pill, due } = this.polItemParts(item); return `${due}${pill}` || "—"; } },
      { key: "act", label: "btColAct", sortable: false, cell: item => this.polItemParts(item).act },
    ];
    const after = item => {
      const { open, button, form } = this.polItemParts(item);
      return `${open ? `<tr class="static poldetailrow"><td colspan="${columns.length}">${this.polDetail(item, button)}</td></tr>` : ""}${form ? `<tr class="static poldetailrow"><td colspan="${columns.length}">${form}</td></tr>` : ""}`;
    };
    const hidden = on.reduce((n, rule) => n + (rule.ignored || 0), 0);
    const note = hidden && !this.policyShowHidden ? `<p class="factnote">${this.t("polHiddenN", { n: this.formatNumber(hidden) })}</p>` : "";
    const table = shown.length ? this.listTable(id, columns, pg.rows, { cls: "pols", rowAttrs: item => `data-pol-row="${this.esc(item.key)}"`, after }) : `<div class="emptymsg">${items.length ? this.noMatches(id) : `<ha-icon icon="mdi:check-circle-outline"></ha-icon>${this.t("polNoViolations")}`}</div>`;
    return `<div class="panel">${bar}${this.polSelBar(shown.length)}${table}${pg.footer}${note}</div>`;
  }

  policiesView() {
    this.ensurePolicies();
    const r = this.policies;
    const anyHidden = r?.rules?.some(rule => rule.ignored);
    const left = anyHidden ? `<button class="chip ${this.policyShowHidden ? "active" : ""}" data-policy-hidden aria-pressed="${Boolean(this.policyShowHidden)}">${this.t(this.policyShowHidden ? "polHideHidden" : "polShowHidden")}</button>` : "";
    const head = this.pageBar({ left, at: this.policiesAt, loading: this.policiesLoading, attr: "data-policy-refresh" });
    if (this.policiesError) return `<div class="stack">${head}<div class="panel"><div class="error">${this.esc(this.policiesError)}</div></div></div>`;
    if (!r) return `<div class="stack">${head}<div class="panel">${this.skeleton("polLoading")}</div></div>`;
    const on = r.rules.filter(rule => rule.enabled);
    const violations = on.reduce((n, rule) => n + rule.count, 0);
    const hidden = on.reduce((n, rule) => n + (rule.ignored || 0), 0);
    const tabs = [
      { id: "rules", icon: "mdi:clipboard-list-outline", label: this.t("polTabRules"), hint: this.t("polTileRulesHint", { on: this.formatNumber(on.length) }), count: r.rules.length, tone: on.length ? "ok" : "mute" },
      { id: "violations", icon: "mdi:clipboard-alert-outline", label: this.t("polTabViolations"), hint: this.t("polTileViolationsHint"), count: violations, tone: !on.length ? "mute" : violations ? "warn" : "ok", pill: hidden ? this.t("polTileHidden", { n: this.formatNumber(hidden) }) : "", pillTone: "mute" },
    ];
    const open = this.viewTabOf("policies", tabs, violations ? "violations" : "rules");
    const body = open === "rules"
      ? `<div class="panel">${r.rules.map(rule => this.polRuleBlock(rule)).join("")}${on.length ? "" : `<p class="factnote">${this.t("polNoneOn")}</p>`}${this.howCounted("polFootnote")}</div>`
      : this.polViolations(r);
    return `<div class="stack">${head}${this.navTiles("policies", tabs, open, this.t("policies"), true)}${body}</div>`;
  }
}

// LayoutMixin: the pieces every long view shares (a row of key figures and tabs for its sections); mixed in by 99-register.js.
class LayoutMixin {
  // A row of key figures. tile: { label, value, sub, tone ("ok"|"warn"|"red"|"mute"), tab, filter, lf } where tab ("view|id") makes it a button; lf ([list id, filter name, value]) sets that list filter, an empty name clears them all.
  sumTiles(tiles) {
    const cells = tiles.filter(Boolean).map(t => {
      const inner = `<span class="sumlabel">${this.esc(t.label)}</span><b class="sumvalue">${t.value}</b>${t.sub ? `<small>${t.sub}</small>` : ""}${t.spark ? `<span class="spark-row">${t.spark}</span>` : ""}`;
      const hint = t.hint ? ` title="${this.esc(t.hint)}"` : "";
      // Three kinds, told apart by a cue in the corner: a figure only (flat), a filter of the list below (funnel, marked when on), a link to another page (arrow).
      const filter = (attr, active) => `<button class="sumtile filter ${t.tone || "mute"}"${hint} ${attr} aria-pressed="${Boolean(active)}"><ha-icon class="sumcue" icon="mdi:filter-variant"></ha-icon>${inner}</button>`;
      if (t.filter !== undefined) return filter(`data-finding-filter="${this.esc(t.filter)}"`, t.active);
      if (t.lf) {
        const [id, name, value] = t.lf, f = this.lv[id]?.f || {};
        return filter(`data-lf-set="${this.esc(t.lf.join("|"))}"`, name ? f[name] === value : !Object.values(f).some(Boolean));
      }
      if (t.attr && t.attr[0] !== "data-object") return filter(`${t.attr[0]}="${this.esc(t.attr[1])}"`, t.active);
      if (t.inv !== undefined) return filter(`data-inv-filter="${this.esc(t.inv)}"`, t.active);
      const go = attr => `<button class="sumtile go ${t.tone || "mute"}"${hint} ${attr}><ha-icon class="sumcue" icon="mdi:chevron-right"></ha-icon>${inner}</button>`;
      if (t.attr) return go(`${t.attr[0]}="${this.esc(t.attr[1])}"`);
      if (t.unref) return go(`data-unref-tab="${t.unref}"`);
      return t.tab ? go(`data-view-tab="${this.esc(t.tab)}"`) : `<div class="sumtile ${t.tone || "mute"}"${hint}>${inner}</div>`;
    }).join("");
    return cells ? `<div class="sumtiles" role="group" aria-label="${this.esc(this.t("sumLabel"))}">${cells}</div>` : "";
  }

  // When the data of a page was read last (for its "as of"), and a time given in seconds as ISO text.
  markLoaded(key) { (this._loadedAt ||= {})[key] = new Date().toISOString(); }
  loadedAt(key) { return this._loadedAt?.[key] || null; }
  isoOf(seconds) { return seconds ? new Date(seconds * 1000).toISOString() : null; }

  // The slim row under a page title: the page's own controls and facts on the left, "as of" and the refresh button on the
  // right. { left, at (ISO time or null), loading, error, attr (the data-… attribute of the refresh button), exportId (a page exporter) }.
  pageBar({ left = "", at = null, loading = false, attr = "", refresh = true, exportId = "" }) {
    const stand = loading ? this.t("sysReading") : at ? this.t("sysAsOf", { time: this.formatDate(at) }) : "";
    return `<div class="pagebar"><div class="pb-left">${left}</div><div class="pb-right">${stand ? `<span class="scanago">${this.esc(stand)}</span>` : ""}${exportId ? this.exportMenu(exportId) : ""}${refresh ? `<button class="btn" ${attr} title="${this.esc(this.t("sysRefreshHint"))}" ${loading ? 'disabled aria-busy="true"' : ""}><ha-icon icon="mdi:refresh" class="${loading ? "spin" : ""}"></ha-icon>${this.t("sysRefresh")}</button>` : ""}</div></div>`;
  }

  // Tiles that switch between the areas of one view: icon, title, number and a short hint; the open one is marked.
  // tab: { id, icon, label, hint, count, tone, pill, pillTone, disabled }.
  navTiles(view, tabs, open, label, compact = false) {
    const fixed = compact && tabs.some(t => t.facts);
    const cells = tabs.map(t => {
      const tone = t.tone || "mute", has = t.count !== undefined && t.count !== null;
      const pills = `${has ? `<span class="pill ${tone}">${this.esc(this.formatNumber(t.count))}</span>` : ""}${t.pill ? `<span class="pill ${t.pillTone || tone}">${this.esc(t.pill)}</span>` : ""}`;
      const inner = `<ha-icon icon="${t.icon}"></ha-icon><strong>${this.esc(t.label)}</strong><span class="setpill">${pills}</span><small title="${this.esc(t.hint || "")}">${this.esc(t.hint || "")}</small>${t.facts ? `<span class="navfacts">${t.facts.map(f => `<span class="pill ${f.tone}">${this.esc(f.text)}</span>`).join("")}</span>` : ""}`;
      if (t.disabled) return `<div class="taskcard t-mute off" aria-disabled="true">${inner}</div>`;
      return `<button class="taskcard t-${tone}${t.id === open ? " on" : ""}" aria-pressed="${t.id === open}" data-view-tab="${this.esc(`${view}|${t.id}`)}">${inner}</button>`;
    }).join("");
    return `<div class="taskgrid compactgrid setgrid navtiles${compact ? " compact" : ""}${fixed ? " fixed" : ""}${view === "cleanup" && tabs.length === 5 ? " five" : ""}"${compact ? ` style="--cols:${this.navColumns(tabs.length)}"` : ""} role="group" aria-label="${this.esc(label)}">${cells}</div>`;
  }

  // How many tiles go side by side before a row breaks: few tiles in one row, many in even rows (7 become 4 + 3).
  navColumns(n) { return n <= 4 ? Math.max(1, n) : Math.min(5, Math.ceil(n / 2)); }

  // The tab that is open in a view: the chosen one if it exists, else the first one of `tabs` or `prefer`.
  viewTabOf(view, tabs, prefer) {
    const chosen = (this.viewTab ||= {})[view];
    if (tabs.some(t => t.id === chosen)) return chosen;
    return tabs.some(t => t.id === prefer) ? prefer : tabs[0].id;
  }

  // Tabs of one view; a coloured dot marks a tab that holds something to look at. tab: { id, label, count, tone }.
  viewTabBar(view, tabs, active) {
    const list = tabs.map(t => `<button class="tab" role="tab" aria-selected="${t.id === active}" tabindex="${t.id === active ? 0 : -1}" data-view-tab="${this.esc(`${view}|${t.id}`)}">${this.esc(t.label)}${t.count !== undefined && t.count !== null ? ` <em>${this.formatNumber(t.count)}</em>` : ""}${t.tone && t.tone !== "ok" && t.tone !== "mute" ? `<i class="tabdot ${t.tone}" aria-hidden="true"></i>` : ""}</button>`).join("");
    return `<div class="tabs" role="tablist" aria-label="${this.esc(this.t("tabsLabel"))}">${list}</div>`;
  }

  pickViewTab(tab) {
    const [view, id] = String(tab || "").split("|");
    if (!view || !id) return;
    (this.viewTab ||= {})[view] = id;
    if (view === "cleanup") { this.cleanupSel = new Set(); if (this.lv?.cleanup) this.lv.cleanup.f = {}; this.pages = {}; }
    if (view === "unreferenced") { this.unrefTab = id; this.retryOrphanLast(); this.pages = {}; }
    this.render();
  }
}

// FlowMixin: the "Ablauf" tab of an automation or script: triggers, conditions and actions as a readable tree; mixed in by 99-register.js.
// The configuration is the one the detail request already delivers; nothing here reads Home Assistant.
const FLOW_NESTED = ["sequence", "then", "else", "default", "parallel", "conditions", "condition", "choose", "if", "repeat"];
const FLOW_LIMIT = 300;
const FLOW_DEPTH = 6;
const FLOW_REF_KEYS = ["entity_id", "device_id", "area_id", "floor_id", "label_id"];

class FlowMixin {
  // The concrete ids a block names itself (not what its nested blocks name): target, data and the block's own keys.
  flowRefs(step) {
    const out = [];
    const take = (type, value) => {
      for (const v of Array.isArray(value) ? value : [value]) {
        if (typeof v === "string" && v && !["all", "none"].includes(v) && !v.includes("{{") && !v.startsWith("!input")) out.push([type, v]);
      }
    };
    const walk = (node, depth) => {
      if (!node || typeof node !== "object" || Array.isArray(node) || depth > 3) return;
      for (const [k, v] of Object.entries(node)) {
        if (FLOW_NESTED.includes(k)) continue;
        if (FLOW_REF_KEYS.includes(k)) take(k.replace("_id", ""), v);
        else if (typeof v === "object") walk(v, depth + 1);
      }
    };
    walk(step, 0);
    return out;
  }

  flowType(step, kind) {
    if (!step || typeof step !== "object") return "unknown";
    if (kind === "trigger") return step.trigger || step.platform || "unknown";
    if (kind === "condition") return step.condition || "unknown";
    for (const key of ["choose", "if", "repeat", "parallel", "sequence", "wait_template", "wait_for_trigger", "delay", "variables", "stop", "event", "scene", "set_conversation_response"]) if (key in step) return key;
    if ("action" in step || "service" in step) return "action";
    if ("condition" in step) return "condition";
    if (step.device_id && step.domain && step.type) return "device";
    return "unknown";
  }

  flowLabel(type) { const key = `flow_${type}`; const text = this.t(key); return text === key ? type : text; }

  // One line of facts for a block, built from the keys people look for first.
  flowFacts(step, type) {
    const facts = [];
    const add = v => { if (v !== undefined && v !== null && v !== "" && typeof v !== "object") facts.push(String(v)); };
    if (step.alias) add(step.alias);
    if (type === "action") add(step.action || step.service);
    if (["state", "numeric_state"].includes(type)) { add(step.attribute); add(step.from !== undefined ? `${this.t("flowFrom")} ${step.from}` : ""); add(step.to !== undefined ? `${this.t("flowTo")} ${step.to}` : ""); add(step.state !== undefined ? `= ${Array.isArray(step.state) ? step.state.join(", ") : step.state}` : ""); add(step.above !== undefined ? `> ${step.above}` : ""); add(step.below !== undefined ? `< ${step.below}` : ""); }
    if (["time", "sun"].includes(type)) { add(step.at); add(step.event); add(step.after); add(step.before); add(step.offset); }
    if (type === "time_pattern") add([step.hours, step.minutes, step.seconds].filter(x => x !== undefined).join(":"));
    if (type === "event") add(step.event_type);
    if (type === "delay") add(typeof step.delay === "object" ? Object.entries(step.delay).map(([k, v]) => `${v} ${k}`).join(" ") : step.delay);
    if (type === "wait_template") add(this.t("flowTemplate"));
    if (type === "template") add(this.t("flowTemplate"));
    if (type === "repeat") { const r = step.repeat || {}; add(r.count !== undefined ? `${r.count}×` : r.while ? this.t("flowWhile") : r.until ? this.t("flowUntil") : r.for_each !== undefined ? this.t("flowForEach") : ""); }
    if (type === "choose") add(this.t("flowBranches", { n: (step.choose || []).length }));
    if (type === "stop") add(step.stop);
    if (type === "device") add(`${step.domain} · ${step.type}`);
    if (step.for !== undefined && type === "state") add(`${this.t("flowFor")} ${typeof step.for === "object" ? Object.values(step.for).join(":") : step.for}`);
    if (step.continue_on_error) add(this.t("flowContinueOnError"));
    if (step.enabled === false) add(this.t("flowDisabled"));
    return facts;
  }

  flowRefButton([type, id]) {
    const key = `${type}:${id}`, obj = this.findObject(key);
    return obj
      ? `<button class="chip flowref" data-object="${this.esc(key)}">${this.esc(obj.name || id)}</button>`
      : `<span class="chip flowref missing" title="${this.esc(id)}">${this.esc(id)} · ${this.t("missing")}</span>`;
  }

  // Locations of the findings of this object, with the root keys of the lists made equal ("actions" and "action").
  flowNormal(path) { return String(path).replace(/^(trigger|condition|action)s?(?=\/|$)/, "$1").replace(/\/conditions?\//g, "/condition/"); }

  // One block and what it contains. `ctx` carries the counter, the finding places and the kind of the list.
  flowNode(step, path, kind, depth, ctx) {
    if (ctx.count >= FLOW_LIMIT) { ctx.cut += 1; return ""; }
    ctx.count += 1;
    const type = this.flowType(step, kind);
    const refs = this.flowRefs(step);
    const broken = ctx.places.some(place => place.startsWith(this.flowNormal(path))) || refs.some(([t, id]) => !this.findObject(`${t}:${id}`));
    const facts = this.flowFacts(step, type).map(f => this.esc(f)).join(" · ");
    const head = `<span class="fhead"><ha-icon icon="${FLOW_ICONS[type] || "mdi:circle-small"}"></ha-icon><b>${this.esc(this.flowLabel(type))}</b>${facts ? `<span class="ffacts">${facts}</span>` : ""}${refs.map(r => this.flowRefButton(r)).join("")}<code class="fpath">${this.esc(path)}</code></span>`;
    const kids = depth >= FLOW_DEPTH ? "" : this.flowChildren(step, type, path, depth, ctx);
    const cls = `fstep${broken ? " broken" : ""}`;
    return kids ? `<details class="${cls}" open><summary>${head}</summary><div class="fkids">${kids}</div></details>` : `<div class="${cls}">${head}</div>`;
  }

  flowList(list, path, kind, depth, ctx) {
    return (Array.isArray(list) ? list : list ? [list] : []).map((step, i) => this.flowNode(step, `${path}/${i}`, kind, depth + 1, ctx)).join("");
  }

  flowGroup(label, body) { return body ? `<div class="fgroup"><small>${this.esc(label)}</small>${body}</div>` : ""; }

  flowChildren(step, type, path, depth, ctx) {
    if (type === "choose") {
      const branches = (step.choose || []).map((b, i) => `<div class="fbranch"><b>${this.t("flowBranch", { n: i + 1 })}</b>${this.flowGroup(this.t("flowIf"), this.flowList(b.conditions ?? b.condition, `${path}/choose/${i}/conditions`, "condition", depth + 1, ctx))}${this.flowGroup(this.t("flowThen"), this.flowList(b.sequence, `${path}/choose/${i}/sequence`, "action", depth + 1, ctx))}</div>`).join("");
      return branches + this.flowGroup(this.t("flowElse"), this.flowList(step.default, `${path}/default`, "action", depth, ctx));
    }
    if (type === "if") return this.flowGroup(this.t("flowIf"), this.flowList(step.if, `${path}/if`, "condition", depth, ctx)) + this.flowGroup(this.t("flowThen"), this.flowList(step.then, `${path}/then`, "action", depth, ctx)) + this.flowGroup(this.t("flowElse"), this.flowList(step.else, `${path}/else`, "action", depth, ctx));
    if (type === "repeat") { const r = step.repeat || {}; return this.flowList(r.sequence, `${path}/repeat/sequence`, "action", depth, ctx) + this.flowGroup(this.t("flowWhile"), this.flowList(r.while, `${path}/repeat/while`, "condition", depth, ctx)) + this.flowGroup(this.t("flowUntil"), this.flowList(r.until, `${path}/repeat/until`, "condition", depth, ctx)); }
    if (type === "parallel") return this.flowList(step.parallel, `${path}/parallel`, "action", depth, ctx);
    if (type === "sequence") return this.flowList(step.sequence, `${path}/sequence`, "action", depth, ctx);
    if (["and", "or", "not"].includes(type)) return this.flowList(step.conditions, `${path}/conditions`, "condition", depth, ctx);
    return "";
  }

  flowCard(item, key) {
    const script = item.object_type === "script";
    const places = (this.data?.findings || []).filter(f => this.findingKey(f) === key && !f.ignored).map(f => this.flowNormal(f.evidence?.[0]?.location || "")).filter(Boolean);
    const ctx = { count: 0, cut: 0, places };
    const root = script ? ["sequence"] : ["trigger", "condition", "action"];
    const blocks = script ? [["actions", item.actions, "sequence", "action"]] : [["triggers", item.triggers, "trigger", "trigger"], ["conditions", item.conditions, "condition", "condition"], ["actions", item.actions, "action", "action"]];
    const sections = blocks.map(([label, list, path, kind]) => {
      const body = this.flowList(list, root.length === 1 ? "sequence" : path, kind, 0, ctx);
      return `<section class="panel"><div class="panelhead"><h2>${this.t(label)} <em class="date">${this.formatNumber((list || []).length)}</em></h2></div><div class="fflow">${body || `<p class="factnote">${this.t(label === "conditions" ? "flowNoConditions" : "flowNone")}</p>`}</div></section>`;
    }).join("");
    const facts = [item.mode ? [this.t("flowMode"), item.mode] : null, item.max ? [this.t("flowMax"), item.max] : null].filter(Boolean).map(([k, v]) => `<span><small>${k}</small><b>${this.esc(String(v))}</b></span>`).join("");
    const cut = ctx.cut ? `<p class="factnote">${this.t("flowCut", { n: ctx.cut })}</p>` : "";
    return `<div class="stack">${facts ? `<div class="panel sumline">${facts}</div>` : ""}${sections}${cut}<p class="factnote">${this.t("flowNote")}</p></div>`;
  }
}

const FLOW_ICONS = {
  state: "mdi:toggle-switch-outline", numeric_state: "mdi:numeric", time: "mdi:clock-outline", time_pattern: "mdi:timer-sand", sun: "mdi:weather-sunny", event: "mdi:lightning-bolt-outline", template: "mdi:code-braces", webhook: "mdi:webhook", mqtt: "mdi:message-text-outline", homeassistant: "mdi:home-assistant", zone: "mdi:map-marker-outline", device: "mdi:devices", trigger: "mdi:flash-outline",
  action: "mdi:play-circle-outline", choose: "mdi:source-branch", if: "mdi:help-rhombus-outline", repeat: "mdi:repeat", parallel: "mdi:call-split", sequence: "mdi:format-list-numbered", wait_template: "mdi:timer-sand-empty", wait_for_trigger: "mdi:timer-sand-empty", delay: "mdi:timer-outline", variables: "mdi:variable", stop: "mdi:stop-circle-outline", scene: "mdi:palette-outline", and: "mdi:set-all", or: "mdi:set-merge", not: "mdi:not-equal-variant", condition: "mdi:filter-outline",
};

// CorrelationMixin: findings that began at about the time of an update or restart; mixed in by 99-register.js.
// Always worded "at about the same time as", never as a cause.
class CorrelationMixin {
  async loadCorrelations() {
    try { this.corr = await this._hass.callWS({ type: "ha_housekeeper/correlations" }); }
    catch (_) { this.corr = { groups: [], by_key: {} }; }
    this.render();
  }

  // Loads once, and again after every new scan.
  ensureCorrelations() {
    const key = this.data?.meta?.scanned_at || "";
    if (!this.data || (this._corrKey === key && this._corrRequested)) return;
    this._corrRequested = true; this._corrKey = key;
    setTimeout(() => this.loadCorrelations(), 0);
  }

  corrText(group) {
    const vars = { title: this.esc(group.title || ""), domain: this.esc(group.domain || ""), from: this.esc(group.from ?? ""), to: this.esc(group.to ?? "") };
    return this.t(`corr_${group.kind}`, vars);
  }

  // The sentence on one finding, or "" when it began with nothing the log knows.
  corrLine(key) {
    const id = this.corr?.by_key?.[key];
    const group = id && this.corr.groups.find(g => g.id === id);
    return group ? this.t("corrAfter", { what: this.corrText(group), when: this.formatDate(group.at) }) : "";
  }

  corrFindingCount() { return Object.keys(this.corr?.by_key || {}).length; }

  // What the findings of one group have in common: how many, which classes, and over what time they began.
  corrSummary(group, findings) {
    const reasons = {};
    findings.forEach(f => { const r = this.findingReason(f); reasons[r] = (reasons[r] || 0) + 1; });
    const parts = Object.entries(reasons).sort((a, b) => b[1] - a[1]).map(([r, n]) => `<span class="pill mute">${this.esc(this.t("corrReason", { n: this.formatNumber(n), what: this.reasonLabel(r) }))}</span>`).join(" ");
    const times = findings.map(f => Date.parse(f.first_detected_at)).filter(Number.isFinite).sort((a, b) => a - b);
    const span = times.length ? this.t("corrSpan", { first: this.formatDate(new Date(times[0]).toISOString()), last: this.formatDate(new Date(times[times.length - 1]).toISOString()) }) : "";
    const more = group.total > findings.length ? ` ${this.t("corrMore", { n: this.formatNumber(group.total - findings.length) })}` : "";
    return `<p class="sub u-mb14">${this.esc(span)}${more}</p><div class="chips u-mb14">${parts}</div>`;
  }

  // The other updates of an incident, as one line under the title.
  corrAlso(group) {
    const list = (group.also || []).map(a => `<li><ha-icon icon="mdi:package-up"></ha-icon><span>${this.corrText(a)}</span></li>`);
    return list.length ? `<div class="corralso u-mb14"><strong>${this.t("corrAlsoLabel")}</strong><ul>${list.join("")}</ul></div>` : "";
  }

  corrGroupBody(group) {
    const findings = group.keys.map(k => this.data.findings.find(x => x.key === k)).filter(Boolean);
    const pg = this.paginate(`corr_${group.id}`, findings);
    return `${this.corrAlso(group)}${this.corrSummary(group, findings)}${pg.rows.map(f => this.findingRow(f)).join("")}${pg.footer}`;
  }

  // The incidents of the findings page: every update or restart that has findings, and every watch after a system
  // update. A watch belongs to the incident that holds the same update (kind, from, to); one without findings stands alone.
  incidents() {
    const groups = this.corr?.groups || [], watches = this.watch?.watches || [];
    const system = ["ha_version", "os_version", "supervisor_version"];
    const same = t => `${t.kind}|${t.from ?? ""}|${t.to ?? ""}`;
    const used = new Set();
    const items = groups.map(group => {
      const mine = new Set([group, ...(group.also || [])].filter(e => system.includes(e.kind)).map(same));
      const watch = watches.find(w => !used.has(w.id) && w.triggers.some(t => mine.has(same(t)))) || null;
      if (watch) used.add(watch.id);
      return { group, watch, at: group.at };
    });
    watches.filter(w => !used.has(w.id)).forEach(watch => items.push({ group: null, watch, at: watch.started_at }));
    const running = it => (it.watch && !it.watch.closed_at ? 1 : 0);
    return items.sort((a, b) => running(b) - running(a) || (Date.parse(b.at) || 0) - (Date.parse(a.at) || 0));
  }

  incidentId(item) { return item.group ? `corr_${item.group.id}` : `corr_w_${item.watch.id}`; }

  // The fold of the incident that holds a watch, so the band in the page head can open it.
  incidentFoldId(watchId) {
    const item = this.incidents().find(it => it.watch && it.watch.id === watchId);
    return item ? this.incidentId(item) : `corr_w_${watchId}`;
  }

  incidentBody(item) {
    const parts = [];
    if (item.watch) parts.push(`<div class="incsec obs"><h4>${this.t("incObs")}</h4>${this.watchBody(item.watch)}</div>`);
    if (item.group) parts.push(`<div class="incsec"><h4>${this.t("incFindings", { n: this.formatNumber(item.group.total) })}</h4>${this.corrGroupBody(item.group)}</div>`);
    return parts.join("");
  }

  incidentRow(item) {
    const { group, watch } = item, id = this.incidentId(item), open = this.foldOpen(id, false);
    const running = watch && !watch.closed_at;
    const icon = !group ? "mdi:package-up" : group.kind === "start" ? "mdi:restart" : group.kind === "plan" ? "mdi:broom" : group.kind === "purge" ? "mdi:database-remove" : group.kind === "note" ? "mdi:pin-outline" : "mdi:package-up";
    const title = group ? this.corrText(group) + (group.also?.length ? ` <span class="pill warn alsopill" title="${this.esc(this.t("corrAlsoLabel"))}">+${group.also.length}</span>` : "") : this.watchWhat(watch);
    const when = [this.formatDate(item.at)];
    if (running) when.push(this.t("incLeft", { hours: Math.max(0, Math.ceil((Date.parse(watch.until) - Date.now()) / 3600000)) }));
    else if (watch?.closed_at) when.push(this.t("watchEnded", { when: this.formatDate(watch.closed_at) }));
    const tones = { worse: "red", stable: "ok", transient: "mute", unknown: "mute", pending: "warn" };
    const pills = [group ? `<span class="pill ${group.only_group ? "mute" : "warn"}">${this.esc(this.t("corrCount", { n: this.formatNumber(group.total) }))}</span>` : (watch ? `<span class="pill mute">${this.esc(this.t("incNoFindings"))}</span>` : ""),
      watch ? `<span class="pill ${tones[watch.result?.verdict] || "mute"}">${this.esc(this.t(`watchV_${watch.result?.verdict || "unknown"}`))}</span>` : ""].join("");
    const endBtn = running ? `<button class="btn quiet" data-watch-end><ha-icon icon="mdi:eye-off-outline"></ha-icon>${this.t("watchEnd")}</button>` : "";
    const tile = group && group.only_group ? "mute" : "warn";
    const head = `<div class="incidenthead"><button class="row foldhead" data-fold="${this.esc(id)}" aria-expanded="${open}"><span class="tile ${tile}"><ha-icon icon="${open ? "mdi:chevron-down" : icon}"></ha-icon></span><span class="row-text"><strong>${title}</strong><small>${this.esc(when.join(" · "))}</small></span>${pills}</button>${endBtn}</div>`;
    return `<div class="fold${open ? " open" : ""}">${head}${open ? `<div class="foldbody">${this.incidentBody(item)}</div>` : ""}</div>`;
  }

  // One card for what began or stopped after an update or restart. Closed by default; the filter line stays in view.
  corrGroupsCard(afterCount = 0, follows = 0) {
    this.ensureWatches?.();
    const items = this.incidents();
    if (!items.length) return "";
    const pg = this.paginate("corr", items);
    const open = this.foldOpen("corr", false);
    const rows = pg.rows.map(it => this.incidentRow(it)).join("");
    const pill = `<span class="pill warn">${this.esc(this.t("corrIncidents", { n: this.formatNumber(items.length) }))}</span>`;
    const top = `<button class="row foldhead" data-fold="corr" aria-expanded="${open}"><span class="tile warn"><ha-icon icon="mdi:${open ? "chevron-down" : "chevron-right"}"></ha-icon></span><span class="row-text"><strong>${this.t("corrTitle")}</strong><small>${this.esc(this.t("corrHint"))}</small></span>${pill}</button>`;
    const on = Boolean(this.findingAfter);
    const strip = afterCount ? `<div class="incfilter${on ? " on" : ""}"><span><b>${this.esc(this.t("corrStrip", { n: this.formatNumber(afterCount) }))}</b>${follows ? ` <span class="muted">· ${this.esc(this.t("findingsFollowSub", { n: this.formatNumber(follows) }))}</span>` : ""}</span><button class="chip" data-finding-after="1" aria-pressed="${on}"><ha-icon icon="mdi:${on ? "close" : "filter-variant"}"></ha-icon>${this.t(on ? "corrFilterOff" : "corrFilterOn")}</button></div>` : "";
    return `<div class="panel"><div class="fold${open ? " open" : ""}">${top}${strip}${open ? `<div class="foldbody">${rows}${pg.footer}</div>` : ""}</div></div>`;
  }
}

