const COMP_RANK = { problem: 3, disabled: 2, active: 1, ignored: 0 };

class ComponentsMixin {
  // The config entries grouped by domain, with the sums the list shows.
  compIntegrations() {
    return this.memo("compInt", [this.data?.objects, this.reliability?.entries, this.sysState("storage").data, this.lang], () => {
      const sizes = new Map((this.sysState("storage").data?.custom_integrations || []).map(x => [x.domain, x.bytes]));
      const groups = new Map();
      for (const o of this.data?.objects || []) {
        if (o.object_type !== "config_entry") continue;
        const g = groups.get(o.domain) || { domain: o.domain, name: o.integration_name || o.domain, custom: false, version: null, entries: [], entities: 0, devices: 0, status: "ignored", avail: null, hacs: null, bytes: sizes.get(o.domain) ?? null };
        g.entries.push(o);
        g.custom ||= Boolean(o.custom);
        g.version ||= o.integration_version || null;
        g.hacs ||= o.hacs || null;
        g.entities += o.entity_count || 0;
        g.devices += o.device_count || 0;
        if ((COMP_RANK[o.status] ?? 1) > (COMP_RANK[g.status] ?? 1)) g.status = o.status;
        const row = this.reliability?.available ? this.reliabilityRow(o) : null;
        if (row && row.availability !== null && row.availability !== undefined) g.avail = g.avail === null ? row.availability : Math.min(g.avail, row.availability);
        groups.set(o.domain, g);
      }
      return [...groups.values()];
    });
  }

  compRowAttrs(g) {
    return `data-object="${this.esc(`integration:${g.domain}`)}" tabindex="0" role="button" aria-label="${this.esc(g.name)}"`;
  }

  compNameCell(g) {
    const sub = [g.domain, g.entries.length > 1 ? this.t("compEntries", { n: g.entries.length }) : ""].filter(Boolean).join(" · ");
    const open = (this.compOpen || []).includes(g.domain);
    return `${g.entries.length > 1 ? this.expandBtn("data-comp-open", g.domain, open, this.t(open ? "compCloseEntries" : "compOpenEntries")) : ""}${this.nameCell(g.name, sub)}`;
  }

  // The entries of an opened integration: one line each, a click opens the entry.
  compEntryRows(g, span) {
    if (!(this.compOpen || []).includes(g.domain)) return "";
    return g.entries.map(o => `<tr data-object="${this.esc(this.objectKey(o))}" tabindex="0" role="button" class="compentry"><td colspan="${span}">${this.nameCell(o.name || g.name, o.title && o.title !== o.name ? o.title : "")}<span class="compentrymeta">${this.pill(o.status)} · ${this.esc(this.formatNumber(o.entity_count || 0))} ${this.t("entities")} · ${this.esc(this.formatNumber(o.device_count || 0))} ${this.t("compColDevices")}</span></td></tr>`).join("");
  }

  compIntegrationsList(items, name) {
    const hasSize = items.some(g => g.bytes !== null);
    const hasAvail = items.some(g => g.avail !== null);
    const max = Math.max(0, ...items.map(g => g.bytes || 0));
    const origin = g => this.t(g.custom ? "originKindCustom" : "originKindCore");
    const columns = [
      { key: "name", label: "sysColIntegration", cell: g => this.compNameCell(g) },
      { key: "version", label: "compColVersion", cell: g => `${this.esc(g.version || "–")}${g.hacs?.pending_update ? ` <span class="pill warn" title="${this.esc(this.t("compUpdateHint", { v: g.hacs.available_version || "" }))}">${this.t("compUpdate")}</span>` : ""}` },
      { key: "state", label: "sysColState", cell: g => this.pill(g.status) },
      { key: "entities", label: "entities", dir: "desc", cell: g => this.esc(this.formatNumber(g.entities)) },
      { key: "devices", label: "compColDevices", dir: "desc", cell: g => this.esc(this.formatNumber(g.devices)) },
      ...(hasAvail ? [{ key: "avail", label: "compColAvail", dir: "asc", cell: g => (g.avail === null ? "–" : `${this.esc(this.formatNumber(Math.round(g.avail * 10) / 10))} %`) }] : []),
      ...(hasSize ? [{ key: "size", label: "sysColSize", dir: "desc", cell: g => (g.bytes === null ? "–" : `${this.esc(this.formatBytes(g.bytes))}${this.sysShare(g.bytes, max)}`) }] : []),
    ];
    return this.sysList(`compint_${name}`, items, {
      sort: "name", dir: "asc",
      sorts: [
        { key: "name", label: "sysColIntegration", dir: "asc", get: g => g.name },
        { key: "entities", label: "entities", dir: "desc", get: g => g.entities },
        { key: "version", label: "compColVersion", dir: "asc", get: g => g.version },
        { key: "state", label: "sysColState", dir: "desc", get: g => COMP_RANK[g.status] ?? 1 },
        { key: "devices", label: "compColDevices", dir: "desc", get: g => g.devices },
        ...(hasSize ? [{ key: "size", label: "sysColSize", dir: "desc", get: g => g.bytes }] : []),
        ...(hasAvail ? [{ key: "avail", label: "compColAvail", dir: "asc", get: g => g.avail }] : []),
      ],
      filters: [
        { name: "state", all: this.t("compFilterState"), options: [["problem", this.statusLabel("problem")], ["disabled", this.statusLabel("disabled")], ["active", this.statusLabel("active")]] },
        ...(items.some(g => g.hacs) ? [{ name: "hacs", all: this.t("compFilterHacs"), options: [["update", this.t("compFilterUpdate")], ["hacs", this.t("compFilterViaHacs")]] }] : []),
      ],
      filterFns: { state: (g, v) => g.status === v, hacs: (g, v) => (v === "update" ? Boolean(g.hacs?.pending_update) : Boolean(g.hacs)) },
      text: g => `${g.name} ${g.domain}`, tie: g => g.domain, empty: "compNoIntegrations",
      rowAttrs: g => this.compRowAttrs(g), columns, after: g => this.compEntryRows(g, columns.length),
      exportName: "integrations", header: [this.t("sysColIntegration"), "Domain", this.t("compColOrigin"), this.t("compColVersion"), this.t("sysColState"), this.t("compColEntries"), this.t("entities"), this.t("compColDevices"), this.t("intHacsAvailable"), this.t("compUpdate")],
      rows: g => [g.name, g.domain, origin(g), g.version || "", this.statusLabel(g.status), g.entries.length, g.entities, g.devices, g.hacs ? g.hacs.available_version || "" : "", g.hacs ? (g.hacs.pending_update ? "yes" : "no") : ""],
    });
  }

  compAppsList(apps) {
    // CPU, RAM and data come from the system report; it is read when this tab opens (see componentsView).
    const usage = new Map((this.sysState("storage").data?.apps || []).map(a => [a.slug, a]));
    const use = a => usage.get(a.object_id) || null;
    const has = key => [...usage.values()].some(u => u[key] !== null && u[key] !== undefined);
    const hasLoad = has("cpu_percent") || has("memory_usage"), hasSize = has("size_bytes");
    const max = Math.max(0, ...[...usage.values()].map(u => u.size_bytes || 0));
    const running = a => a.state === "started";
    const columns = [
      { key: "name", label: "sysColApp", cell: a => this.nameCell(a.name, a.object_id) },
      { key: "state", label: "sysColState", cell: a => `<span class="pill ${running(a) ? "ok" : "mute"}">${this.t(running(a) ? "sysAppRunning" : "sysAppStopped")}</span>` },
      { key: "version", label: "compColVersion", cell: a => `${this.esc(a.version || "–")}${a.update_available ? ` <span class="pill warn" title="${this.esc(this.t("compUpdateHint", { v: a.version_latest || "" }))}">${this.t("compUpdate")}</span>` : ""}` },
      { key: "latest", label: "compColLatest", cell: a => this.esc(a.version_latest || "–") },
      ...(hasLoad ? [
        { key: "cpu", label: "sysColCpu", dir: "desc", cell: a => this.esc(use(a) ? this.sysAppCpu(use(a)) : "–") },
        { key: "ram", label: "sysColRam", dir: "desc", cell: a => this.esc(use(a) ? this.sysAppRam(use(a)) : "–") },
      ] : []),
      ...(hasSize ? [{ key: "size", label: "sysColData", dir: "desc", cell: a => (use(a)?.size_bytes == null ? "–" : `${this.esc(this.formatBytes(use(a).size_bytes))}${this.sysShare(use(a).size_bytes, max)}`) }] : []),
    ];
    return this.sysList("compapps", apps, {
      sort: "name", dir: "asc",
      sorts: [
        { key: "name", label: "sysColApp", dir: "asc", get: a => a.name }, { key: "state", label: "sysColState", dir: "desc", get: a => (running(a) ? 1 : 0) }, { key: "version", label: "compColVersion", dir: "asc", get: a => a.version }, { key: "latest", label: "compColLatest", dir: "asc", get: a => a.version_latest },
        ...(hasLoad ? [{ key: "ram", label: "sysColRam", dir: "desc", get: a => use(a)?.memory_usage ?? null }, { key: "cpu", label: "sysColCpu", dir: "desc", get: a => use(a)?.cpu_percent ?? null }] : []),
        ...(hasSize ? [{ key: "size", label: "sysColData", dir: "desc", get: a => use(a)?.size_bytes ?? null }] : []),
      ],
      filters: [
        { name: "state", all: this.t("sysColState"), options: [["on", this.t("sysAppRunning")], ["off", this.t("sysAppStopped")]] },
        ...(apps.some(a => a.update_available) ? [{ name: "update", all: this.t("compUpdate"), options: [["yes", this.t("compFilterUpdate")]] }] : []),
      ],
      filterFns: { state: (a, v) => running(a) === (v === "on"), update: a => Boolean(a.update_available) },
      text: a => `${a.name} ${a.object_id}`, tie: a => a.object_id, empty: "compNoApps",
      rowAttrs: a => `data-object="${this.esc(this.objectKey(a))}" tabindex="0" role="button" aria-label="${this.esc(a.name)}"`, columns,
      exportName: "apps", header: [this.t("sysColApp"), "Slug", this.t("sysColState"), this.t("compColVersion"), this.t("compColLatest"), "CPU %", "RAM bytes", "Data bytes"],
      rows: a => [a.name, a.object_id, a.state || "", a.version || "", a.version_latest || "", use(a)?.cpu_percent ?? "", use(a)?.memory_usage ?? "", use(a)?.size_bytes ?? ""],
    });
  }

  componentsView() {
    const apps = (this.data?.objects || []).filter(o => o.object_type === "app");
    const ints = this.compIntegrations();
    const core = ints.filter(g => !g.custom), custom = ints.filter(g => g.custom);
    const storage = this.sysState("storage").data;
    // Disk space only once "Storage & system" is loaded; apps without a figure add nothing.
    const sum = list => (list.some(x => x !== null && x !== undefined) ? list.reduce((t, x) => t + (x || 0), 0) : null);
    const appBytes = storage ? sum(apps.map(a => (storage.apps || []).find(u => u.slug === a.object_id)?.size_bytes)) : null;
    const customBytes = storage ? sum(custom.map(g => g.bytes)) : null;
    const size = b => (b === null ? "" : this.t("compSumSize", { size: this.formatBytes(b) }));
    const n = f => this.formatNumber(f);
    const bad = list => list.filter(g => g.status === "problem").length;
    const fact = (count, label, tone) => (count ? { text: `${n(count)} ${this.t(label)}`, tone } : null);
    const sizeFact = b => (size(b) ? { text: size(b), tone: "mute" } : null);
    const tabs = [
      { id: "apps", icon: "mdi:apps", label: this.t("compTabApps"), hint: this.t("compTabAppsHint"), count: apps.length,
        facts: [fact(apps.filter(a => a.update_available).length, "compSumAppUpdates", "warn"), fact(apps.filter(a => a.state === "started").length, "compSumRunning", "ok"), sizeFact(appBytes)] },
      { id: "core", icon: "mdi:puzzle-outline", label: this.t("compTabCore"), hint: this.t("compTabCoreHint"), count: core.length,
        facts: [fact(bad(core), "compSumProblem", "red")] },
      { id: "custom", icon: "mdi:puzzle-plus-outline", label: this.t("compTabCustom"), hint: this.t("compTabCustomHint"), count: custom.length,
        facts: [fact(bad(custom), "compSumProblem", "red"), fact(custom.filter(g => g.hacs?.pending_update).length, "compSumUpdates", "warn"), sizeFact(customBytes)] },
    ].map(t => ({ ...t, facts: t.facts.filter(Boolean), tone: t.facts.some(f => f?.tone === "red") ? "red" : "mute" }));
    const open = this.viewTabOf("components", tabs, "core");
    if (apps.length || custom.length) this.sysEnsure("storage"); // CPU, RAM and data of the apps, folder sizes of custom integrations
    const body = open === "apps" ? this.compAppsList(apps) : this.compIntegrationsList(open === "custom" ? custom : core, open);
    const st = this.sysState("storage");
    const bar = this.pageBar({ at: st.at, loading: st.loading, attr: 'data-sys-refresh="storage"' });
    return `<div class="stack">${bar}${this.navTiles("components", tabs, open, this.t("components"), true)}<div class="panel">${body}</div></div>`;
  }
}

// The page of an integration as a whole (core or custom): all config entries of one domain. It is a synthetic object
// `integration:<domain>` made in the panel from the config entries of the scan, so the page runs through the same
// detail path (header, tabs, back trail, keys) as every other object. The page of one entry stays and holds the actions.
Object.assign(TEXT.de, {
  integration: "Integration", intTabEntries: "Einträge", intTabMembers: "Entitäten & Geräte", intTabUsed: "Verwendung", intTabRel: "Zuverlässigkeit",
  intSumEntries: "Einträge", intSumDevices: "Geräte", intSumEntities: "Entitäten", intSumVersion: "Version", intSumOrigin: "Herkunft", intSumHA: "Home Assistant {v}",
  intFolder: "Ordner", intFolderSize: "Größe des Ordners", intDocs: "Dokumentation", intOpenHA: "In Home Assistant öffnen", intToIntegration: "Zur Integration",
  intEntriesTitle: "Einträge dieser Integration", intMembersTitle: "Entitäten und Geräte", intNoMembers: "Keine Entitäten oder Geräte.", intUsedTitle: "Verwendet von", intNoUsed: "Keine Automation, kein Skript und keine Szene nutzt Entitäten dieser Integration.",
  intNoRel: "Für diese Integration liegen noch keine Zuverlässigkeitswerte vor.", intColName: "Name", intColType: "Typ", intColStatus: "Status",
  intSources: "Quellen der Einträge", intFirstCreated: "Ältester Eintrag angelegt", intLastModified: "Zuletzt geändert", intIds: "Eintrags-IDs",
  intEntityCount: "{e} Entitäten · {d} Geräte",
  intHacsTitle: "HACS", intHacsInstalled: "Installierte Version", intHacsAvailable: "Neueste Version", intHacsUpdate: "Update verfügbar", intHacsCurrent: "Aktuell", intHacsArchived: "Archiviert", intHacsBlocked: "Braucht neuere HA-Version", intHacsOpen: "In HACS öffnen", intHacsGitHub: "Repository auf GitHub", intHacsNote: "Stand aus dem Speicher von HACS; es wird nichts bei GitHub abgefragt und nichts installiert.",
});
Object.assign(TEXT.en, {
  integration: "Integration", intTabEntries: "Entries", intTabMembers: "Entities & devices", intTabUsed: "Used by", intTabRel: "Reliability",
  intSumEntries: "Entries", intSumDevices: "Devices", intSumEntities: "Entities", intSumVersion: "Version", intSumOrigin: "Origin", intSumHA: "Home Assistant {v}",
  intFolder: "Folder", intFolderSize: "Size of the folder", intDocs: "Documentation", intOpenHA: "Open in Home Assistant", intToIntegration: "To the integration",
  intEntriesTitle: "Entries of this integration", intMembersTitle: "Entities and devices", intNoMembers: "No entities or devices.", intUsedTitle: "Used by", intNoUsed: "No automation, script or scene uses entities of this integration.",
  intNoRel: "There are no reliability values for this integration yet.", intColName: "Name", intColType: "Type", intColStatus: "Status",
  intSources: "Sources of the entries", intFirstCreated: "Oldest entry created", intLastModified: "Last changed", intIds: "Entry IDs",
  intEntityCount: "{e} entities · {d} devices",
  intHacsTitle: "HACS", intHacsInstalled: "Installed version", intHacsAvailable: "Latest version", intHacsUpdate: "Update available", intHacsCurrent: "Up to date", intHacsArchived: "Archived", intHacsBlocked: "Needs newer HA version", intHacsOpen: "Open in HACS", intHacsGitHub: "Repository on GitHub", intHacsNote: "Taken from the memory of HACS; nothing is asked from GitHub and nothing is installed.",
});

const INT_RANK = { problem: 3, disabled: 2, active: 1, ignored: 0 };

class IntegrationPageMixin {
  // One synthetic object per domain that has config entries; they are not part of the inventory list.
  buildIntegrationObjects(objects) {
    const groups = new Map();
    for (const o of objects) {
      if (o.object_type !== "config_entry") continue;
      const g = groups.get(o.domain) || { object_type: "integration", object_id: o.domain, domain: o.domain, name: o.integration_name || o.domain, custom: false, integration_version: null, integration_dir: null, documentation: null, hacs: null, entries: [], entity_count: 0, device_count: 0, status: "ignored" };
      g.entries.push(o);
      g.custom ||= Boolean(o.custom);
      g.integration_version ||= o.integration_version || null;
      g.integration_dir ||= o.integration_dir || null;
      g.documentation ||= o.documentation || null;
      g.hacs ||= o.hacs || null;
      g.entity_count += o.entity_count || 0;
      g.device_count += o.device_count || 0;
      if ((INT_RANK[o.status] ?? 1) > (INT_RANK[g.status] ?? 1)) g.status = o.status;
      groups.set(o.domain, g);
    }
    return groups;
  }

  intEntries(item) { return item.entries || []; }

  // Entities and devices of all entries of the domain, from the registry objects of the scan.
  intMembers(item) {
    const ids = new Set(this.intEntries(item).map(e => e.object_id));
    return this.memo("intMembers", [this.data?.objects, item.object_id], () => (this.data?.objects || []).filter(o =>
      (o.object_type === "entity" && ids.has(o.config_entry_id)) || (o.object_type === "device" && (o.config_entry_ids || []).some(id => ids.has(id)))));
  }

  // Automations, scripts and scenes that use an entity of the integration.
  intUsedBy(item) {
    const found = new Map();
    for (const m of this.intMembers(item)) {
      if (m.object_type !== "entity") continue;
      for (const edge of this.edgesTo(`entity:${m.object_id}`)) {
        const src = this.findObject(edge.source);
        if (src && ["automation", "script", "scene"].includes(src.object_type)) found.set(edge.source, src);
      }
    }
    return [...found.values()];
  }

  intAccessTone(item) {
    const tones = this.intEntries(item).map(e => this.accessTone(e));
    return tones.includes("red") ? "red" : tones.includes("warn") ? "warn" : "";
  }

  intTabs(item) {
    const used = this.intUsedBy(item).length;
    const tabs = [["overview", "tabOverview"], ["members", "intTabMembers", this.intMembers(item).length]];
    if (used) tabs.push(["used", "intTabUsed", used]);
    if (this.intEntries(item).some(e => this.reliabilityRow(e))) tabs.push(["reliability", "intTabRel"]);
    tabs.push(["access", "accTab", null, this.intAccessTone(item)], ["technical", "tabTechnical"]);
    return tabs;
  }

  intSummary(item) {
    const n = f => this.formatNumber(f);
    return [
      [this.t("intSumOrigin"), this.esc(this.t(item.custom ? "originKindCustom" : "originKindCore"))],
      item.custom && item.integration_version ? [this.t("intSumVersion"), `${this.esc(item.integration_version)}${item.hacs?.pending_update ? ` <span class="pill warn" title="${this.esc(this.t("compUpdateHint", { v: item.hacs.available_version || "" }))}">${this.t("compUpdate")}</span>` : ""}`] : !item.custom && this.data?.meta?.ha_version ? [this.t("intSumVersion"), this.esc(this.t("intSumHA", { v: this.data.meta.ha_version }))] : null,
      [this.t("intSumEntries"), n(this.intEntries(item).length)],
      [this.t("intSumDevices"), n(item.device_count)],
      [this.t("intSumEntities"), n(item.entity_count)],
    ].filter(Boolean);
  }

  // The panel of one tab; the heading names the entry when there are several.
  intEachEntry(item, build) {
    const entries = this.intEntries(item);
    return `<div class="stack">${entries.map(e => (entries.length > 1 ? `<h3 class="intentry">${this.esc(e.name || e.object_id)}</h3>` : "") + build(e)).join("")}</div>`;
  }

  intPanel(tab, item) {
    if (tab === "members") return this.intMembersCard(item);
    if (tab === "used") return this.intUsedCard(item);
    if (tab === "reliability") return this.intEachEntry(item, e => { const row = this.reliabilityRow(e); return row ? this.reliabilityDetailCard(row) : `<div class="panel"><div class="emptymsg">${this.t("intNoRel")}</div></div>`; });
    if (tab === "access") return this.intEachEntry(item, e => this.accessDetailCard(e));
    if (tab === "technical") return this.intTechnicalCard(item);
    return this.intOverview(item);
  }

  intOverview(item) {
    const fact = (label, value) => `<div class="fact"><span>${this.t(label)}</span><b>${value}</b></div>`;
    const size = item.custom ? (this.sysState("storage").data?.custom_integrations || []).find(x => x.domain === item.domain) : null;
    const docs = /^https:\/\//.test(item.documentation || "") ? `<a class="btn" href="${this.esc(item.documentation)}" target="_blank" rel="noopener noreferrer"><ha-icon icon="mdi:book-open-variant"></ha-icon>${this.t("intDocs")}</a>` : "";
    const folder = item.custom ? `<section class="panel"><div class="panelhead"><h2>${this.t("intFolder")}</h2></div><div class="facts">${fact("intFolder", this.esc(item.integration_dir || `custom_components/${item.domain}`))}${size ? fact("intFolderSize", this.esc(this.formatBytes(size.bytes))) : ""}</div></section>` : "";
    const hacs = item.hacs ? this.intHacsCard(item.hacs) : "";
    const rows = this.objectTable(`intentries-${item.object_id}`, this.intEntries(item).map(e => ({ key: `config_entry:${e.object_id}`, type: "config_entry", name: e.name || e.object_id, sub: "", tone: this.tone(e.status), state: e.status, stateLabel: this.statusLabel(e.status), pill: this.pill(e.status), entities: e.entity_count || 0, devices: e.device_count || 0 })), {
      min: 8, extras: [
        { key: "entities", label: "objColEntities", dir: "desc", get: r => r.entities, cell: r => this.formatNumber(r.entities) },
        { key: "devices", label: "objColDevices", dir: "desc", get: r => r.devices, cell: r => this.formatNumber(r.devices) },
      ],
    });
    return `<div class="stack"><section class="panel"><div class="panelhead"><h2>${this.t("intEntriesTitle")}</h2>${docs ? `<div class="actions">${docs}</div>` : ""}</div>${rows}</section>${hacs}${folder}</div>`;
  }

  // What HACS says about the integration, for custom integrations that HACS installed.
  intHacsCard(h) {
    const fact = (label, value) => `<div class="fact"><span>${this.t(label)}</span><b>${value}</b></div>`;
    const status = `<span class="pill ${h.pending_update ? "warn" : "ok"}">${this.t(h.pending_update ? "intHacsUpdate" : "intHacsCurrent")}</span>${h.blocked ? ` <span class="pill warn">${this.t("intHacsBlocked")}</span>` : ""}${h.archived ? ` <span class="pill warn">${this.t("intHacsArchived")}</span>` : ""}`;
    const open = h.id ? `<button class="btn" data-ha-path="${this.esc(`/hacs/repository/${encodeURIComponent(h.id)}`)}"><ha-icon icon="mdi:open-in-new"></ha-icon>${this.t("intHacsOpen")}</button>` : "";
    const github = h.full_name ? `<a class="btn" href="${this.esc(`https://github.com/${h.full_name}`)}" target="_blank" rel="noopener noreferrer"><ha-icon icon="mdi:github"></ha-icon>${this.t("intHacsGitHub")}</a>` : "";
    return `<section class="panel"><div class="panelhead"><h2>${this.t("intHacsTitle")}</h2>${open || github ? `<div class="actions">${open}${github}</div>` : ""}</div><div class="facts">${fact("intHacsInstalled", this.esc(h.installed_version || "–"))}${fact("intHacsAvailable", this.esc(h.available_version || "–"))}${fact("sysColState", status)}</div><p class="factnote">${this.t("intHacsNote")}</p></section>`;
  }

  intMembersCard(item) {
    const members = this.intMembers(item);
    return `<div class="stack"><section class="panel"><div class="panelhead"><h2>${this.t("intMembersTitle")}</h2></div>${this.sysList("intmembers", members, {
      sort: "name", dir: "asc",
      sorts: [{ key: "name", label: "intColName", dir: "asc", get: o => o.name || o.object_id }, { key: "type", label: "intColType", dir: "asc", get: o => o.object_type }, { key: "status", label: "intColStatus", dir: "asc", get: o => o.status }],
      text: o => `${o.name} ${o.object_id}`, tie: o => this.objectKey(o), empty: "intNoMembers",
      rowAttrs: o => `data-object="${this.esc(this.objectKey(o))}" tabindex="0" role="button" aria-label="${this.esc(o.name || o.object_id)}"`,
      columns: [
        { key: "name", label: "intColName", cell: o => this.nameCell(o.name || o.object_id, o.object_id) },
        { key: "type", label: "intColType", cell: o => this.esc(this.t(o.object_type)) },
        { key: "status", label: "intColStatus", cell: o => this.pill(o.status) },
      ],
    })}</section></div>`;
  }

  intUsedCard(item) {
    const used = this.intUsedBy(item);
    const rows = this.objectTable(`intused-${item.object_id}`, used.map(o => ({ key: this.objectKey(o), type: o.object_type, name: o.name || o.object_id, sub: o.object_id, tone: this.tone(o.status), state: o.status, stateLabel: this.statusLabel(o.status), pill: this.pill(o.status) })), { empty: this.t("intNoUsed") });
    return `<div class="stack"><section class="panel"><div class="panelhead"><h2>${this.t("intUsedTitle")}</h2></div>${rows}</section></div>`;
  }

  intTechnicalCard(item) {
    const entries = this.intEntries(item);
    const dates = key => entries.map(e => e[key]).filter(Boolean).sort();
    const row = (k, v) => (v ? `<dt>${this.esc(k)}</dt><dd>${this.esc(v)}</dd>` : "");
    return `<div class="stack"><section class="panel"><div class="panelhead"><h2>${this.t("registry")}</h2></div><div class="pad"><dl class="kv">${[
      row("domain", item.domain), row(this.t("integrationName"), item.name), row(this.t("intSumOrigin"), this.t(item.custom ? "originKindCustom" : "originKindCore")),
      row(this.t("intSumVersion"), item.integration_version), row(this.t("intFolder"), item.integration_dir), row(this.t("intDocs"), item.documentation),
      row(this.t("intSources"), [...new Set(entries.map(e => e.source).filter(Boolean))].join(", ")),
      row(this.t("intFirstCreated"), dates("created_at")[0] ? this.formatDate(dates("created_at")[0]) : ""), row(this.t("intLastModified"), dates("modified_at").slice(-1)[0] ? this.formatDate(dates("modified_at").slice(-1)[0]) : ""),
      row(this.t("intIds"), entries.map(e => e.object_id).join(", ")),
    ].join("")}</dl></div></section></div>`;
  }
}

